    /// How a surface should be implemented for a desktop capability app.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum AppParityRoute {
        /// Ready to build as normal native Kael/app APIs.
        NativeReady,
        /// Native path exists, but builders should expose setup, permission, or
        /// platform caveats.
        NativeWithGuardrails,
        /// Keep this as a small WebView island when the dependency is inherently
        /// browser-shaped.
        WebViewFallback,
        /// Known product gap that should be stated explicitly in audits.
        Roadmap,
    }

    impl AppParityRoute {
        /// Stable text label for diagnostics and UI.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::NativeReady => "native-ready",
                Self::NativeWithGuardrails => "native-with-guardrails",
                Self::WebViewFallback => "webview-fallback",
                Self::Roadmap => "roadmap",
            }
        }

        /// Returns true when the surface is primarily native.
        pub fn is_native(self) -> bool {
            matches!(self, Self::NativeReady | Self::NativeWithGuardrails)
        }

        /// Returns true when the surface should remain a browser compatibility
        /// island.
        pub fn is_webview_fallback(self) -> bool {
            matches!(self, Self::WebViewFallback)
        }

        /// Returns true when the surface is still a stated product gap.
        pub fn is_roadmap(self) -> bool {
            matches!(self, Self::Roadmap)
        }
    }

    /// A feature-backed capability gap with safe support-level metadata.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    pub struct PlatformFeatureGap {
        /// Feature that did not satisfy the planned path.
        pub feature: PlatformFeature,
        /// Current support level reported for the feature.
        pub support: SupportLevel,
    }

    /// Suggested response for a feature-backed capability gap.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
    pub enum PlatformFeatureGapRemediation {
        /// Ask for runtime initialization, permission, or metadata before retrying.
        InitializeOrRequestPermission,
        /// Proceed through guarded native APIs with setup/caveat UI.
        UseGuardedNativePath,
        /// Feature is disabled by policy and needs policy/configuration change.
        ChangePolicyOrConfiguration,
        /// Feature is not available; use a fallback, reduce scope, or mark roadmap.
        UseFallbackOrRoadmap,
    }

    impl PlatformFeatureGapRemediation {
        /// Stable text label for diagnostics and UI.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::InitializeOrRequestPermission => "initialize-or-request-permission",
                Self::UseGuardedNativePath => "use-guarded-native-path",
                Self::ChangePolicyOrConfiguration => "change-policy-or-configuration",
                Self::UseFallbackOrRoadmap => "use-fallback-or-roadmap",
            }
        }
    }

    /// Count summary of remediation classes across feature-backed gaps.
    #[derive(Debug, Clone, Copy, Default, PartialEq, Eq, Serialize, Deserialize)]
    pub struct PlatformFeatureGapRemediationSummary {
        /// Gaps that need initialization, permission, or metadata.
        pub initialize_or_permission: usize,
        /// Gaps that can proceed through guarded native APIs.
        pub guarded_native: usize,
        /// Gaps that need a policy or configuration change.
        pub policy_change: usize,
        /// Gaps that need fallback, scope reduction, or roadmap work.
        pub fallback_or_roadmap: usize,
    }

    impl PlatformFeatureGapRemediationSummary {
        /// Total remediation entries.
        pub fn total(&self) -> usize {
            self.initialize_or_permission
                + self.guarded_native
                + self.policy_change
                + self.fallback_or_roadmap
        }

        /// Add one remediation to the summary.
        pub fn add(&mut self, remediation: PlatformFeatureGapRemediation) {
            match remediation {
                PlatformFeatureGapRemediation::InitializeOrRequestPermission => {
                    self.initialize_or_permission += 1;
                }
                PlatformFeatureGapRemediation::UseGuardedNativePath => {
                    self.guarded_native += 1;
                }
                PlatformFeatureGapRemediation::ChangePolicyOrConfiguration => {
                    self.policy_change += 1;
                }
                PlatformFeatureGapRemediation::UseFallbackOrRoadmap => {
                    self.fallback_or_roadmap += 1;
                }
            }
        }

        /// Whether any gap needs initialization, permission, or metadata.
        pub fn needs_initialization_or_permission(&self) -> bool {
            self.initialize_or_permission > 0
        }

        /// Whether any gap needs policy/configuration changes.
        pub fn needs_policy_change(&self) -> bool {
            self.policy_change > 0
        }

        /// Whether any gap needs fallback, scope reduction, or roadmap work.
        pub fn needs_fallback_or_roadmap(&self) -> bool {
            self.fallback_or_roadmap > 0
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "platform feature gap remediation summary: {} total, {} initialize/permission, {} guarded native, {} policy change, {} fallback/roadmap",
                self.total(),
                self.initialize_or_permission,
                self.guarded_native,
                self.policy_change,
                self.fallback_or_roadmap
            )
        }
    }

    impl PlatformFeatureGap {
        /// Create a feature gap record.
        pub fn new(feature: PlatformFeature, support: SupportLevel) -> Self {
            Self { feature, support }
        }

        /// Suggested response for this gap.
        pub fn remediation(self) -> PlatformFeatureGapRemediation {
            match self.support {
                SupportLevel::RequiresInit => {
                    PlatformFeatureGapRemediation::InitializeOrRequestPermission
                }
                SupportLevel::Partial => PlatformFeatureGapRemediation::UseGuardedNativePath,
                SupportLevel::Disabled => {
                    PlatformFeatureGapRemediation::ChangePolicyOrConfiguration
                }
                SupportLevel::Full => PlatformFeatureGapRemediation::UseGuardedNativePath,
                SupportLevel::Unsupported => PlatformFeatureGapRemediation::UseFallbackOrRoadmap,
            }
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "platform feature gap: feature {:?}, support {:?}, remediation {}",
                self.feature,
                self.support,
                self.remediation().as_str()
            )
        }
    }

    /// One app surface in an app-category capability recipe.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct AppParitySurface {
        /// Human-readable surface name, such as "media playback" or "helper process".
        pub name: String,
        /// Recommended implementation route.
        pub route: AppParityRoute,
        /// Platform feature that should be checked for this surface, when it maps
        /// directly to one capability.
        pub feature: Option<PlatformFeature>,
    }

    impl AppParitySurface {
        /// Create a surface without a direct platform feature probe.
        pub fn new(name: &'static str, route: AppParityRoute) -> Self {
            Self {
                name: name.to_string(),
                route,
                feature: None,
            }
        }

        /// Create a surface backed by a platform feature probe.
        pub fn with_feature(
            name: &'static str,
            route: AppParityRoute,
            feature: PlatformFeature,
        ) -> Self {
            Self {
                name: name.to_string(),
                route,
                feature: Some(feature),
            }
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "app capability surface: route {}, feature {}",
                self.route.as_str(),
                self.feature.is_some()
            )
        }
    }

    /// A reusable recipe for evaluating a desktop app category.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct AppParityRecipe {
        /// App category being planned.
        pub category: DesktopAppCategory,
        /// Surfaces to classify before implementation.
        pub surfaces: Vec<AppParitySurface>,
    }

    impl AppParityRecipe {
        /// Evaluate this recipe against a capability report.
        pub fn evaluate(&self, report: &CapabilityReport) -> AppParityRecipePlan {
            let feature_gap_details = self
                .surfaces
                .iter()
                .filter_map(|surface| surface.feature)
                .filter_map(|feature| {
                    let support = report.support_for(feature);
                    (!support.is_available()).then_some(PlatformFeatureGap::new(feature, support))
                })
                .collect::<Vec<_>>();
            let feature_gaps = feature_gap_details.iter().map(|gap| gap.feature).collect();

            AppParityRecipePlan {
                category: self.category,
                surfaces: self.surfaces.clone(),
                feature_gaps,
                feature_gap_details,
            }
        }

        /// Returns all surfaces for a given route.
        pub fn surfaces_for_route(&self, route: AppParityRoute) -> Vec<&AppParitySurface> {
            self.surfaces
                .iter()
                .filter(|surface| surface.route == route)
                .collect()
        }

        /// Number of surfaces in this recipe.
        pub fn surface_count(&self) -> usize {
            self.surfaces.len()
        }

        /// Number of surfaces for a route.
        pub fn route_count(&self, route: AppParityRoute) -> usize {
            self.surfaces_for_route(route).len()
        }

        /// Feature-backed surfaces, excluding roadmap-only notes.
        pub fn checked_features(&self) -> Vec<PlatformFeature> {
            self.surfaces
                .iter()
                .filter_map(|surface| surface.feature)
                .collect()
        }

        /// Build a preferred capability check for all feature-backed surfaces.
        pub fn capability_check(&self) -> CapabilityCheck {
            self.checked_features()
                .into_iter()
                .fold(CapabilityCheck::new(), |check, feature| {
                    check.prefer_available(feature)
                })
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "app capability recipe: category {}, {} surfaces, {} native-ready, {} native-with-guardrails, {} webview-islands, {} roadmap, {} feature checks",
                self.category.as_str(),
                self.surface_count(),
                self.route_count(AppParityRoute::NativeReady),
                self.route_count(AppParityRoute::NativeWithGuardrails),
                self.route_count(AppParityRoute::WebViewFallback),
                self.route_count(AppParityRoute::Roadmap),
                self.checked_features().len()
            )
        }
    }

    /// Evaluated app-category plan for a desktop capability audit.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct AppParityRecipePlan {
        /// App category being planned.
        pub category: DesktopAppCategory,
        /// Surfaces to classify before implementation.
        pub surfaces: Vec<AppParitySurface>,
        /// Feature-backed surfaces that are unavailable on the evaluated report.
        pub feature_gaps: Vec<PlatformFeature>,
        /// Feature-backed surfaces that are unavailable, with support levels.
        pub feature_gap_details: Vec<PlatformFeatureGap>,
    }

    impl AppParityRecipePlan {
        /// Returns true when all feature-backed surfaces are available.
        pub fn feature_checks_passed(&self) -> bool {
            self.feature_gaps.is_empty()
        }

        /// Returns true when this recipe contains at least one WebView fallback.
        pub fn has_webview_fallbacks(&self) -> bool {
            self.surfaces
                .iter()
                .any(|surface| surface.route.is_webview_fallback())
        }

        /// Returns true when this recipe contains at least one roadmap surface.
        pub fn has_roadmap_surfaces(&self) -> bool {
            self.surfaces
                .iter()
                .any(|surface| surface.route.is_roadmap())
        }

        /// Returns all surfaces for a given route.
        pub fn surfaces_for_route(&self, route: AppParityRoute) -> Vec<&AppParitySurface> {
            self.surfaces
                .iter()
                .filter(|surface| surface.route == route)
                .collect()
        }

        /// Number of surfaces in this plan.
        pub fn surface_count(&self) -> usize {
            self.surfaces.len()
        }

        /// Number of surfaces for a route.
        pub fn route_count(&self, route: AppParityRoute) -> usize {
            self.surfaces_for_route(route).len()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "app capability plan: category {}, {} surfaces, {} native-ready, {} native-with-guardrails, {} webview-islands, {} roadmap, {} feature gaps",
                self.category.as_str(),
                self.surface_count(),
                self.route_count(AppParityRoute::NativeReady),
                self.route_count(AppParityRoute::NativeWithGuardrails),
                self.route_count(AppParityRoute::WebViewFallback),
                self.route_count(AppParityRoute::Roadmap),
                self.feature_gaps.len()
            )
        }
    }

