    /// Builder-facing guidance for implementing one desktop surface area.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceImplementationBrief {
        /// Surface area being described.
        pub area: DesktopSurfaceArea,
        /// Recommended implementation route.
        pub route: AppParityRoute,
        /// Native Kael primitives or API families to consider first.
        pub native_primitives: Vec<String>,
        /// Browser-shaped cases where a WebView island is justified.
        pub webview_when: Vec<String>,
        /// Product gaps that should be stated as roadmap instead of implied parity.
        pub roadmap_items: Vec<String>,
    }

    impl DesktopSurfaceImplementationBrief {
        /// Returns true when this area has native primitives to start from.
        pub fn has_native_primitives(&self) -> bool {
            !self.native_primitives.is_empty()
        }

        /// Returns true when this area has an intentional WebView fallback condition.
        pub fn has_webview_fallback(&self) -> bool {
            !self.webview_when.is_empty()
        }

        /// Returns true when this area has explicit roadmap items.
        pub fn has_roadmap_items(&self) -> bool {
            !self.roadmap_items.is_empty()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface implementation brief: area {}, route {}, {} native primitives, {} webview conditions, {} roadmap items",
                self.area.as_str(),
                self.route.as_str(),
                self.native_primitives.len(),
                self.webview_when.len(),
                self.roadmap_items.len()
            )
        }
    }

