    /// Strategic workstream for bridging Electron-style desktop expectations with
    /// native Kael APIs.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum DesktopCapabilityBridgeTrack {
        /// Headless/component freedom, layout, styling, animation, theming, and
        /// app-chrome variety.
        DesignFreedom,
        /// Canvas, drawing, visual capture, generated assets, and graphics escape hatches.
        CanvasGraphics,
        /// Media playback, capture, audio graphs, recording, and timing.
        MediaAudio,
        /// Windowing, shell, files, input, storage, lifecycle, IPC, hardware, and
        /// other OS-owned desktop API families.
        NativeDesktopApis,
        /// Accessibility, packaging, updates, security policy, crash reporting, and
        /// release readiness.
        ProductionReadiness,
        /// Runtime performance, memory budgets, diagnostics, and long-running app
        /// resource behavior.
        PerformanceMemory,
        /// Developer tools, observability, support evidence, and agent-facing debug
        /// loops.
        AgentDeveloperExperience,
    }

    impl DesktopCapabilityBridgeTrack {
        /// Stable ordering for strategic bridge-track scheduling.
        pub fn all() -> Vec<Self> {
            vec![
                Self::DesignFreedom,
                Self::CanvasGraphics,
                Self::MediaAudio,
                Self::NativeDesktopApis,
                Self::ProductionReadiness,
                Self::PerformanceMemory,
                Self::AgentDeveloperExperience,
            ]
        }

        /// Stable sort priority for replacement-bridge work ordering.
        pub fn priority(self) -> u8 {
            Self::all()
                .into_iter()
                .position(|track| track == self)
                .unwrap_or(usize::MAX) as u8
        }

        /// Stable text label for diagnostics and agent routing.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::DesignFreedom => "design-freedom",
                Self::CanvasGraphics => "canvas-graphics",
                Self::MediaAudio => "media-audio",
                Self::NativeDesktopApis => "native-desktop-apis",
                Self::ProductionReadiness => "production-readiness",
                Self::PerformanceMemory => "performance-memory",
                Self::AgentDeveloperExperience => "agent-developer-experience",
            }
        }
    }

    /// Priority for a bridge workstream item.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum DesktopCapabilityBridgePriority {
        /// Blocks credible "replace Electron" claims for many app classes.
        Critical,
        /// Important for broad app coverage but not always a hard blocker.
        High,
        /// Useful parity work that should follow blockers and high-impact APIs.
        Medium,
        /// Polish, variance, or documentation-depth work.
        Low,
    }

    impl DesktopCapabilityBridgePriority {
        /// Stable text label for diagnostics and agent routing.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::Critical => "critical",
                Self::High => "high",
                Self::Medium => "medium",
                Self::Low => "low",
            }
        }

        /// Stable sort priority. Lower values should be handled first.
        pub fn priority(self) -> u8 {
            match self {
                Self::Critical => 0,
                Self::High => 1,
                Self::Medium => 2,
                Self::Low => 3,
            }
        }
    }

    /// Count-level summary for one strategic bridge track in an app-wide handoff.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityBridgeTrackSummary {
        /// Strategic bridge track being summarized.
        pub track: DesktopCapabilityBridgeTrack,
        /// Requirement packets in this track.
        pub packet_count: usize,
        /// Planned execution kits in this track.
        pub kit_count: usize,
        /// Native/platform blocker kits in this track.
        pub blocker_kit_count: usize,
        /// Ready native primitive kits in this track.
        pub native_kit_count: usize,
        /// Acceptance evidence kits in this track.
        pub evidence_kit_count: usize,
        /// Browser-shaped compatibility island kits in this track.
        pub webview_kit_count: usize,
        /// Roadmap caveat kits in this track.
        pub roadmap_kit_count: usize,
        /// Whether any packet in this track targets native/platform work.
        pub targets_native_or_platform_work: bool,
        /// Highest priority represented by this track, if any packet exists.
        pub highest_priority: Option<DesktopCapabilityBridgePriority>,
    }

    impl DesktopCapabilityBridgeTrackSummary {
        /// Build a track summary from requirement packets.
        pub fn from_packets(
            track: DesktopCapabilityBridgeTrack,
            packets: &[DesktopCapabilityRequirementWorkPacket],
        ) -> Self {
            let matching = packets
                .iter()
                .filter(|packet| packet.bridge_track == track)
                .collect::<Vec<_>>();
            let highest_priority = matching
                .iter()
                .map(|packet| packet.bridge_priority)
                .min_by_key(|priority| priority.priority());

            Self {
                track,
                packet_count: matching.len(),
                kit_count: matching.iter().map(|packet| packet.kit_count).sum(),
                blocker_kit_count: matching.iter().map(|packet| packet.blocker_kit_count).sum(),
                native_kit_count: matching.iter().map(|packet| packet.native_kit_count).sum(),
                evidence_kit_count: matching
                    .iter()
                    .map(|packet| packet.evidence_kit_count)
                    .sum(),
                webview_kit_count: matching.iter().map(|packet| packet.webview_kit_count).sum(),
                roadmap_kit_count: matching.iter().map(|packet| packet.roadmap_kit_count).sum(),
                targets_native_or_platform_work: matching
                    .iter()
                    .any(|packet| packet.targets_native_or_platform_work()),
                highest_priority,
            }
        }

        /// Returns true when this track has at least one packet.
        pub fn has_packets(&self) -> bool {
            self.packet_count > 0
        }

        /// Returns true when this track includes critical bridge work.
        pub fn has_critical_work(&self) -> bool {
            self.highest_priority == Some(DesktopCapabilityBridgePriority::Critical)
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop capability bridge track summary: track {}, {} packets, {} kits, {} blockers, {} native kits, {} evidence kits, {} webview kits, {} roadmap kits, targets native/platform {}, highest priority {}",
                self.track.as_str(),
                self.packet_count,
                self.kit_count,
                self.blocker_kit_count,
                self.native_kit_count,
                self.evidence_kit_count,
                self.webview_kit_count,
                self.roadmap_kit_count,
                self.targets_native_or_platform_work,
                self.highest_priority
                    .map(DesktopCapabilityBridgePriority::as_str)
                    .unwrap_or("none")
            )
        }
    }

