    /// Executable workstream for one strategic bridge track.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityBridgeTrackWorkstream {
        /// Count-level summary for this bridge track.
        pub summary: DesktopCapabilityBridgeTrackSummary,
        /// Requirement packets assigned to this bridge track.
        pub packets: Vec<DesktopCapabilityRequirementWorkPacket>,
        /// Missing-by-default evidence checklists across this bridge track.
        pub evidence_checklists: Vec<DesktopAcceptanceEvidenceChecklist>,
        /// Number of evidence checklists across this bridge track.
        pub evidence_checklist_count: usize,
        /// Number of evidence items across this bridge track.
        pub evidence_item_count: usize,
    }

    impl DesktopCapabilityBridgeTrackWorkstream {
        /// Build a track workstream from requirement packets.
        pub fn from_packets(
            track: DesktopCapabilityBridgeTrack,
            packets: &[DesktopCapabilityRequirementWorkPacket],
        ) -> Self {
            let packets = packets
                .iter()
                .filter(|packet| packet.bridge_track == track)
                .cloned()
                .collect::<Vec<_>>();
            let evidence_checklists = packets
                .iter()
                .flat_map(|packet| packet.kits.iter().map(|kit| kit.evidence_checklist.clone()))
                .collect::<Vec<_>>();
            let evidence_item_count = evidence_checklists
                .iter()
                .map(DesktopAcceptanceEvidenceChecklist::item_count)
                .sum();

            Self {
                summary: DesktopCapabilityBridgeTrackSummary::from_packets(track, &packets),
                evidence_checklist_count: evidence_checklists.len(),
                evidence_item_count,
                packets,
                evidence_checklists,
            }
        }

        /// Returns true when this workstream contains packets.
        pub fn has_packets(&self) -> bool {
            self.summary.has_packets()
        }

        /// Returns true when this workstream contains critical bridge work.
        pub fn has_critical_work(&self) -> bool {
            self.summary.has_critical_work()
        }

        /// Complete every matching packet in the workstream with supplied evidence.
        pub fn complete_with_evidence_checklists(
            &self,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> Vec<DesktopCapabilityGenerationPassOutcome> {
            let evidence = evidence_checklists.into_iter().collect::<Vec<_>>();

            self.packets
                .iter()
                .flat_map(|packet| packet.complete_with_evidence_checklists(evidence.clone()))
                .collect()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop capability bridge track workstream: track {}, {} packets, {} kits, {} evidence checklists, {} evidence items, critical {}, targets native/platform {}",
                self.summary.track.as_str(),
                self.summary.packet_count,
                self.summary.kit_count,
                self.evidence_checklist_count,
                self.evidence_item_count,
                self.has_critical_work(),
                self.summary.targets_native_or_platform_work
            )
        }
    }

