    /// Custom Desktop capability intake for an app that does not fit exactly into
    /// one preset category.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityIntake {
        /// Requested app requirements in the order supplied by the builder/agent.
        pub requirements: Vec<DesktopAppRequirement>,
        /// Deduplicated primitive/API families selected by those requirements.
        pub primitives: Vec<DesktopPrimitive>,
    }

    impl DesktopCapabilityIntake {
        /// Build a custom intake from app requirements.
        pub fn from_requirements(
            requirements: impl IntoIterator<Item = DesktopAppRequirement>,
        ) -> Self {
            let requirements = requirements.into_iter().collect::<Vec<_>>();
            let mut primitives = Vec::new();
            for requirement in &requirements {
                let primitive = requirement.primitive();
                if !primitives.contains(&primitive) {
                    primitives.push(primitive);
                }
            }

            Self {
                requirements,
                primitives,
            }
        }

        /// Number of supplied requirements.
        pub fn requirement_count(&self) -> usize {
            self.requirements.len()
        }

        /// Number of selected primitive/API families.
        pub fn primitive_count(&self) -> usize {
            self.primitives.len()
        }

        /// Returns true when this intake selected at least one primitive family.
        pub fn has_primitives(&self) -> bool {
            !self.primitives.is_empty()
        }

        /// Evaluate this custom intake's primitive/API families.
        pub fn primitive_bridge_audit(
            &self,
            report: &CapabilityReport,
        ) -> DesktopPrimitiveBridgeAudit {
            desktop_primitive_bridge_audit(self.primitives.clone(), report)
        }

        /// Compact capability matrix for this custom intake.
        pub fn capability_matrix(&self, report: &CapabilityReport) -> DesktopCapabilityMatrix {
            self.primitive_bridge_audit(report).capability_matrix()
        }

        /// Native-first work plan for this custom intake.
        pub fn native_first_plan(&self, report: &CapabilityReport) -> DesktopNativeFirstWorkPlan {
            self.capability_matrix(report).native_first_plan()
        }

        /// Count-level generation brief for this custom intake.
        pub fn generation_brief(&self, report: &CapabilityReport) -> DesktopCapabilityIntakeBrief {
            DesktopCapabilityIntakeBrief::from_intake_and_report(self, report)
        }

        /// Single-object generation contract for this custom intake.
        pub fn generation_contract(
            &self,
            report: &CapabilityReport,
        ) -> DesktopCapabilityIntakeContract {
            DesktopCapabilityIntakeContract::from_intake_and_report(self, report)
        }

        /// Readiness decision using the missing-by-default evidence state.
        pub fn ready_readiness_decision(
            &self,
            report: &CapabilityReport,
        ) -> DesktopCapabilityMatrixParityDecision {
            self.capability_matrix(report).ready_readiness_decision()
        }

        /// Readiness decision using supplied evidence checklists.
        pub fn readiness_decision(
            &self,
            report: &CapabilityReport,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopCapabilityMatrixParityDecision {
            self.capability_matrix(report)
                .readiness_decision(evidence_checklists)
        }

        /// Parity-claim decision using the missing-by-default evidence state.
        pub fn ready_parity_claim_decision(
            &self,
            report: &CapabilityReport,
        ) -> DesktopCapabilityMatrixParityDecision {
            self.ready_readiness_decision(report)
        }

        /// Parity-claim decision using supplied evidence checklists.
        pub fn parity_claim_decision(
            &self,
            report: &CapabilityReport,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopCapabilityMatrixParityDecision {
            self.readiness_decision(report, evidence_checklists)
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop capability intake: {} requirements, {} primitives, has primitives {}",
                self.requirement_count(),
                self.primitive_count(),
                self.has_primitives()
            )
        }
    }

    /// Single-object generation contract for a custom Desktop capability intake.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityIntakeContract {
        /// Custom intake being planned.
        pub intake: DesktopCapabilityIntake,
        /// Count-level custom intake brief.
        pub brief: DesktopCapabilityIntakeBrief,
        /// Capability matrix for the selected primitive/API families.
        pub matrix: DesktopCapabilityMatrix,
        /// Native-first work plan derived from the matrix.
        pub native_first_plan: DesktopNativeFirstWorkPlan,
        /// Reviewed backlog evidence state.
        pub review: DesktopCapabilityBacklogReview,
        /// Matrix-level parity decision for the reviewed evidence state.
        pub claim: DesktopCapabilityMatrixParityDecision,
    }

    impl DesktopCapabilityIntakeContract {
        /// Build a generation contract from a custom intake and capability report.
        pub fn from_intake_and_report(
            intake: &DesktopCapabilityIntake,
            report: &CapabilityReport,
        ) -> Self {
            let matrix = intake.capability_matrix(report);
            let native_first_plan = matrix.native_first_plan();
            let review = matrix.ready_backlog_review();
            let claim = DesktopCapabilityMatrixParityDecision::from_plan_and_review(
                &native_first_plan,
                &review,
            );
            Self::from_intake_matrix_plan_review_and_claim(
                intake,
                matrix,
                native_first_plan,
                review,
                claim,
            )
        }

        /// Build a generation contract from already-computed intake planning
        /// surfaces.
        pub fn from_intake_matrix_plan_review_and_claim(
            intake: &DesktopCapabilityIntake,
            matrix: DesktopCapabilityMatrix,
            native_first_plan: DesktopNativeFirstWorkPlan,
            review: DesktopCapabilityBacklogReview,
            claim: DesktopCapabilityMatrixParityDecision,
        ) -> Self {
            let brief = DesktopCapabilityIntakeBrief::from_intake_matrix_plan_and_claim(
                intake,
                &matrix,
                &native_first_plan,
                &claim,
            );

            Self {
                intake: intake.clone(),
                brief,
                matrix,
                native_first_plan,
                review,
                claim,
            }
        }

        /// Return a copy with updated evidence checklists, review, claim, and brief.
        pub fn with_evidence_checklists(
            mut self,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> Self {
            self.review = self.matrix.review_backlog_evidence(evidence_checklists);
            self.claim = DesktopCapabilityMatrixParityDecision::from_plan_and_review(
                &self.native_first_plan,
                &self.review,
            );
            self.brief = DesktopCapabilityIntakeBrief::from_intake_matrix_plan_and_claim(
                &self.intake,
                &self.matrix,
                &self.native_first_plan,
                &self.claim,
            );
            self
        }

        /// Return a copy refreshed from completed generation pass outcomes.
        pub fn with_pass_outcomes(
            self,
            outcomes: impl IntoIterator<Item = DesktopCapabilityGenerationPassOutcome>,
        ) -> Self {
            self.with_evidence_checklists(
                outcomes
                    .into_iter()
                    .map(|outcome| outcome.evidence_checklist().clone()),
            )
        }

        /// Complete a selected execution batch with evidence and return the
        /// refreshed contract plus the next recommended batch.
        pub fn continue_with_execution_batch_evidence(
            self,
            batch: &DesktopCapabilityIntakeExecutionBatch,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopCapabilityIntakeExecutionContinuation {
            let outcomes = batch.complete_with_evidence_checklists(evidence_checklists);
            let outcome_count = outcomes.len();
            let refreshed_contract = self.with_pass_outcomes(outcomes);
            let next_batch = refreshed_contract.recommended_execution_batch();

            DesktopCapabilityIntakeExecutionContinuation {
                contract: refreshed_contract,
                next_batch,
                outcome_count,
            }
        }

        /// Complete an app-wide builder handoff's next batch with evidence and
        /// return the refreshed contract plus the next app-wide handoff.
        pub fn continue_with_builder_handoff_evidence(
            self,
            handoff: &DesktopCapabilityBuilderHandoff,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopCapabilityBuilderContinuation {
            let continuation = self
                .continue_with_execution_batch_evidence(&handoff.next_batch, evidence_checklists);
            DesktopCapabilityBuilderContinuation::from_execution_continuation(continuation)
        }

        /// Complete a strategic bridge-track workstream with evidence and return
        /// the refreshed contract plus the next app-wide handoff.
        pub fn continue_with_bridge_track_workstream_evidence(
            self,
            workstream: &DesktopCapabilityBridgeTrackWorkstream,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopCapabilityBridgeWorkstreamContinuation {
            let outcomes = workstream.complete_with_evidence_checklists(evidence_checklists);
            let outcome_count = outcomes.len();
            let refreshed_contract = self.with_pass_outcomes(outcomes);
            let next_batch = refreshed_contract.recommended_execution_batch();
            let execution_continuation = DesktopCapabilityIntakeExecutionContinuation {
                contract: refreshed_contract,
                next_batch,
                outcome_count,
            };

            DesktopCapabilityBridgeWorkstreamContinuation::from_execution_continuation(
                workstream.summary.track,
                execution_continuation,
            )
        }

        /// Complete a build-ready replacement assignment with evidence and return
        /// the refreshed contract plus the next app-wide handoff.
        pub fn continue_with_replacement_assignment_evidence(
            self,
            assignment: &DesktopCapabilityReplacementAssignmentPacket,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopCapabilityReplacementAssignmentContinuation {
            let outcomes = assignment.complete_with_evidence_checklists(evidence_checklists);
            let outcome_count = outcomes.len();
            let refreshed_contract = self.with_pass_outcomes(outcomes);
            let next_batch = refreshed_contract.recommended_execution_batch();
            let execution_continuation = DesktopCapabilityIntakeExecutionContinuation {
                contract: refreshed_contract,
                next_batch,
                outcome_count,
            };

            DesktopCapabilityReplacementAssignmentContinuation::from_execution_continuation(
                assignment.clone(),
                execution_continuation,
            )
        }

        /// Complete multiple build-ready replacement assignments with evidence and
        /// return one refreshed app-wide handoff.
        pub fn continue_with_replacement_assignment_batch_evidence(
            self,
            assignment_evidence: impl IntoIterator<
                Item = (
                    DesktopCapabilityReplacementAssignmentPacket,
                    Vec<DesktopAcceptanceEvidenceChecklist>,
                ),
            >,
        ) -> DesktopCapabilityReplacementAssignmentBatchContinuation {
            let returned_assignments = assignment_evidence.into_iter().collect::<Vec<_>>();
            let mut outcomes = Vec::new();
            let assignments = returned_assignments
                .into_iter()
                .map(|(assignment, evidence)| {
                    outcomes.extend(assignment.complete_with_evidence_checklists(evidence));
                    assignment
                })
                .collect::<Vec<_>>();
            let outcome_count = outcomes.len();
            let refreshed_contract = self.with_pass_outcomes(outcomes);
            let next_batch = refreshed_contract.recommended_execution_batch();
            let execution_continuation = DesktopCapabilityIntakeExecutionContinuation {
                contract: refreshed_contract,
                next_batch,
                outcome_count,
            };

            DesktopCapabilityReplacementAssignmentBatchContinuation::from_execution_continuation(
                assignments,
                execution_continuation,
            )
        }

        /// Run a bounded sequence of batch evidence submissions.
        pub fn run_execution_evidence_loop(
            self,
            evidence_batches: impl IntoIterator<Item = Vec<DesktopAcceptanceEvidenceChecklist>>,
            max_steps: usize,
        ) -> DesktopCapabilityIntakeExecutionLoop {
            let mut contract = self;
            let mut continuations = Vec::new();
            let mut stop_reason = DesktopCapabilityExecutionLoopStopReason::EvidenceExhausted;

            for evidence in evidence_batches.into_iter().take(max_steps) {
                let batch = contract.recommended_execution_batch();
                if contract.can_claim_parity() {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::ParityClaimed;
                    break;
                }
                if !batch.has_kits() {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    break;
                }

                let continuation =
                    contract.continue_with_execution_batch_evidence(&batch, evidence);
                let should_continue = continuation.should_continue();
                contract = continuation.contract.clone();
                continuations.push(continuation);

                if !should_continue {
                    stop_reason = if contract.can_claim_parity() {
                        DesktopCapabilityExecutionLoopStopReason::ParityClaimed
                    } else {
                        DesktopCapabilityExecutionLoopStopReason::NoNextBatch
                    };
                    break;
                }
            }

            if continuations.len() >= max_steps && !contract.can_claim_parity() {
                stop_reason = DesktopCapabilityExecutionLoopStopReason::StepLimitReached;
            }

            DesktopCapabilityIntakeExecutionLoop::from_contract_and_continuations(
                contract,
                continuations,
                max_steps,
                stop_reason,
            )
        }

        /// Run a bounded sequence of app-wide builder handoff evidence submissions.
        pub fn run_builder_handoff_loop(
            self,
            evidence_batches: impl IntoIterator<Item = Vec<DesktopAcceptanceEvidenceChecklist>>,
            max_steps: usize,
        ) -> DesktopCapabilityBuilderLoop {
            let mut contract = self;
            let mut continuations = Vec::new();
            let mut stop_reason = DesktopCapabilityExecutionLoopStopReason::EvidenceExhausted;

            for evidence in evidence_batches.into_iter().take(max_steps) {
                let handoff = contract.builder_handoff();
                if handoff.can_claim_parity {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::ParityClaimed;
                    break;
                }
                if !handoff.has_next_batch() {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    break;
                }

                let continuation =
                    contract.continue_with_builder_handoff_evidence(&handoff, evidence);
                let should_continue = continuation.should_continue;
                contract = continuation.continuation.contract.clone();
                continuations.push(continuation);

                if !should_continue {
                    stop_reason = if contract.can_claim_parity() {
                        DesktopCapabilityExecutionLoopStopReason::ParityClaimed
                    } else {
                        DesktopCapabilityExecutionLoopStopReason::NoNextBatch
                    };
                    break;
                }
            }

            if continuations.len() >= max_steps && !contract.can_claim_parity() {
                stop_reason = DesktopCapabilityExecutionLoopStopReason::StepLimitReached;
            }

            DesktopCapabilityBuilderLoop::from_contract_and_continuations(
                contract,
                continuations,
                max_steps,
                stop_reason,
            )
        }

        /// Run a bounded sequence of strategic bridge-track workstream evidence
        /// submissions and return the final app-wide handoff.
        pub fn run_bridge_track_workstream_loop(
            self,
            evidence_batches: impl IntoIterator<
                Item = (
                    DesktopCapabilityBridgeTrack,
                    Vec<DesktopAcceptanceEvidenceChecklist>,
                ),
            >,
            max_steps: usize,
        ) -> DesktopCapabilityBridgeWorkstreamLoop {
            let mut contract = self;
            let mut continuations = Vec::new();
            let mut stop_reason = DesktopCapabilityExecutionLoopStopReason::EvidenceExhausted;

            for (track, evidence) in evidence_batches.into_iter().take(max_steps) {
                let handoff = contract.builder_handoff();
                if handoff.can_claim_parity {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::ParityClaimed;
                    break;
                }

                let workstream = handoff.bridge_track_workstream(track);
                if !workstream.has_packets() {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    break;
                }

                let continuation =
                    contract.continue_with_bridge_track_workstream_evidence(&workstream, evidence);
                let should_continue = continuation.should_continue;
                contract = continuation.continuation.contract.clone();
                continuations.push(continuation);

                if !should_continue {
                    stop_reason = if contract.can_claim_parity() {
                        DesktopCapabilityExecutionLoopStopReason::ParityClaimed
                    } else {
                        DesktopCapabilityExecutionLoopStopReason::NoNextBatch
                    };
                    break;
                }
            }

            if continuations.len() >= max_steps && !contract.can_claim_parity() {
                stop_reason = DesktopCapabilityExecutionLoopStopReason::StepLimitReached;
            }

            DesktopCapabilityBridgeWorkstreamLoop::from_contract_and_continuations(
                contract,
                continuations,
                max_steps,
                stop_reason,
            )
        }

        /// Run a bounded sequence of build-ready replacement assignment evidence
        /// submissions, always using the refreshed first replacement assignment.
        pub fn run_replacement_assignment_loop(
            self,
            evidence_batches: impl IntoIterator<Item = Vec<DesktopAcceptanceEvidenceChecklist>>,
            max_steps: usize,
        ) -> DesktopCapabilityReplacementAssignmentLoop {
            let mut contract = self;
            let mut continuations = Vec::new();
            let mut stop_reason = DesktopCapabilityExecutionLoopStopReason::EvidenceExhausted;

            for evidence in evidence_batches.into_iter().take(max_steps) {
                let handoff = contract.builder_handoff();
                if handoff.can_claim_parity {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::ParityClaimed;
                    break;
                }

                let Some(assignment) = handoff.first_replacement_assignment_packet() else {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    break;
                };

                let continuation =
                    contract.continue_with_replacement_assignment_evidence(&assignment, evidence);
                let should_continue = continuation.should_continue;
                contract = continuation.continuation.contract.clone();
                continuations.push(continuation);

                if !should_continue {
                    stop_reason = if contract.can_claim_parity() {
                        DesktopCapabilityExecutionLoopStopReason::ParityClaimed
                    } else {
                        DesktopCapabilityExecutionLoopStopReason::NoNextBatch
                    };
                    break;
                }
            }

            if continuations.len() >= max_steps && !contract.can_claim_parity() {
                stop_reason = DesktopCapabilityExecutionLoopStopReason::StepLimitReached;
            }

            DesktopCapabilityReplacementAssignmentLoop::from_contract_and_continuations(
                contract,
                continuations,
                max_steps,
                stop_reason,
            )
        }

        /// Run a bounded sequence of parallel replacement assignment evidence
        /// submissions, pairing each evidence group with the refreshed immediate
        /// assignment packets.
        pub fn run_replacement_assignment_batch_loop(
            self,
            evidence_batches: impl IntoIterator<Item = Vec<Vec<DesktopAcceptanceEvidenceChecklist>>>,
            max_steps: usize,
        ) -> DesktopCapabilityReplacementAssignmentBatchLoop {
            let mut contract = self;
            let mut continuations = Vec::new();
            let mut stop_reason = DesktopCapabilityExecutionLoopStopReason::EvidenceExhausted;

            for evidence_group in evidence_batches.into_iter().take(max_steps) {
                let handoff = contract.builder_handoff();
                if handoff.can_claim_parity {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::ParityClaimed;
                    break;
                }

                let assignments = handoff.replacement_assignment_packets();
                if assignments.is_empty() {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    break;
                }

                let assignment_evidence = assignments
                    .into_iter()
                    .zip(evidence_group)
                    .collect::<Vec<_>>();
                if assignment_evidence.is_empty() {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::EvidenceExhausted;
                    break;
                }

                let continuation = contract
                    .continue_with_replacement_assignment_batch_evidence(assignment_evidence);
                let should_continue = continuation.should_continue;
                contract = continuation.continuation.contract.clone();
                continuations.push(continuation);

                if !should_continue {
                    stop_reason = if contract.can_claim_parity() {
                        DesktopCapabilityExecutionLoopStopReason::ParityClaimed
                    } else {
                        DesktopCapabilityExecutionLoopStopReason::NoNextBatch
                    };
                    break;
                }
            }

            if continuations.len() >= max_steps && !contract.can_claim_parity() {
                stop_reason = DesktopCapabilityExecutionLoopStopReason::StepLimitReached;
            }

            DesktopCapabilityReplacementAssignmentBatchLoop::from_contract_and_continuations(
                contract,
                continuations,
                max_steps,
                stop_reason,
            )
        }

        /// Returns true when native generation can start without blocker tickets.
        pub fn can_generate_native_now(&self) -> bool {
            self.native_first_plan.can_generate_native_now()
        }

        /// Returns true when this custom scope may mark ready now.
        pub fn can_claim_parity(&self) -> bool {
            self.claim.can_claim_parity
        }

        /// Focused generation pass for the first open reviewed ticket.
        pub fn current_generation_pass(&self) -> Option<DesktopCapabilityGenerationPass> {
            self.review.current_generation_pass()
        }

        /// Generation passes for every open reviewed ticket in backlog order.
        pub fn open_generation_passes(&self) -> Vec<DesktopCapabilityGenerationPass> {
            self.review.open_generation_passes()
        }

        /// Count-level brief for the current focused generation pass.
        pub fn current_pass_brief(&self) -> Option<DesktopCapabilityGenerationPassBrief> {
            self.current_generation_pass().map(|pass| pass.brief())
        }

        /// Concrete execution kits for every open reviewed ticket in backlog order.
        pub fn open_execution_kits(&self) -> Vec<DesktopCapabilityIntakeExecutionKit> {
            self.open_generation_passes()
                .into_iter()
                .map(|pass| {
                    let mut kit = DesktopCapabilityIntakeExecutionKit::from_pass(&pass);
                    kit.action = self.next_action();
                    kit
                })
                .collect()
        }

        /// Concrete execution kits for every planned ticket, regardless of the
        /// current evidence-review state.
        pub fn planned_execution_kits(&self) -> Vec<DesktopCapabilityIntakeExecutionKit> {
            self.native_first_plan
                .blocker_tickets
                .iter()
                .chain(self.native_first_plan.native_tickets.iter())
                .chain(self.native_first_plan.evidence_tickets.iter())
                .chain(self.native_first_plan.deferred_webview_tickets.iter())
                .chain(self.native_first_plan.roadmap_tickets.iter())
                .map(|ticket| {
                    DesktopCapabilityIntakeExecutionKit::from_ticket_and_action(
                        ticket,
                        self.next_action(),
                    )
                })
                .collect()
        }

        /// Per-requested-requirement coverage rows that keep every app surface
        /// visible beside the recommended next batch.
        pub fn requirement_coverage(&self) -> Vec<DesktopCapabilityRequirementCoverage> {
            self.intake
                .requirements
                .iter()
                .copied()
                .map(|requirement| {
                    DesktopCapabilityRequirementCoverage::from_contract_and_requirement(
                        self,
                        requirement,
                    )
                })
                .collect()
        }

        /// Per-requirement coverage for the first matching requested requirement.
        pub fn requirement_coverage_for(
            &self,
            requirement: DesktopAppRequirement,
        ) -> Option<DesktopCapabilityRequirementCoverage> {
            self.intake.requirements.contains(&requirement).then(|| {
                DesktopCapabilityRequirementCoverage::from_contract_and_requirement(
                    self,
                    requirement,
                )
            })
        }

        /// Per-requested-requirement work packets with coverage plus concrete kits.
        pub fn requirement_work_packets(&self) -> Vec<DesktopCapabilityRequirementWorkPacket> {
            self.intake
                .requirements
                .iter()
                .copied()
                .map(|requirement| {
                    DesktopCapabilityRequirementWorkPacket::from_contract_and_requirement(
                        self,
                        requirement,
                    )
                })
                .collect()
        }

        /// Work packet for the first matching requested requirement.
        pub fn requirement_work_packet_for(
            &self,
            requirement: DesktopAppRequirement,
        ) -> Option<DesktopCapabilityRequirementWorkPacket> {
            self.intake.requirements.contains(&requirement).then(|| {
                DesktopCapabilityRequirementWorkPacket::from_contract_and_requirement(
                    self,
                    requirement,
                )
            })
        }

        /// Execution kits for native/platform blockers.
        pub fn blocker_execution_kits(&self) -> Vec<DesktopCapabilityIntakeExecutionKit> {
            self.planned_execution_kits()
                .into_iter()
                .filter(|kit| kit.kind == DesktopCapabilityBacklogKind::ResolveNativeCapabilityGap)
                .collect()
        }

        /// Execution kits for ready native primitive work.
        pub fn native_execution_kits(&self) -> Vec<DesktopCapabilityIntakeExecutionKit> {
            self.planned_execution_kits()
                .into_iter()
                .filter(|kit| kit.kind == DesktopCapabilityBacklogKind::BuildReadyNativePrimitive)
                .collect()
        }

        /// Execution kits for browser-shaped compatibility islands.
        pub fn webview_execution_kits(&self) -> Vec<DesktopCapabilityIntakeExecutionKit> {
            self.planned_execution_kits()
                .into_iter()
                .filter(|kit| kit.kind == DesktopCapabilityBacklogKind::IsolateBrowserDependency)
                .collect()
        }

        /// Execution kits for roadmap caveats that must be briefed.
        pub fn roadmap_execution_kits(&self) -> Vec<DesktopCapabilityIntakeExecutionKit> {
            self.planned_execution_kits()
                .into_iter()
                .filter(|kit| kit.kind == DesktopCapabilityBacklogKind::StateRoadmapCaveat)
                .collect()
        }

        /// Count-level coverage summary across planned and open execution kits.
        pub fn execution_coverage(&self) -> DesktopCapabilityIntakeExecutionCoverage {
            DesktopCapabilityIntakeExecutionCoverage::from_contract(self)
        }

        /// Execution kits selected by the current coverage recommendation.
        pub fn recommended_execution_kits(&self) -> Vec<DesktopCapabilityIntakeExecutionKit> {
            let recommendation = self.execution_coverage().recommendation();
            self.execution_kits_for_recommendation(&recommendation)
        }

        /// Single handoff containing the current recommendation and selected kits.
        pub fn recommended_execution_batch(&self) -> DesktopCapabilityIntakeExecutionBatch {
            let recommendation = self.execution_coverage().recommendation();
            let kits = self.execution_kits_for_recommendation(&recommendation);
            DesktopCapabilityIntakeExecutionBatch::from_recommendation_and_kits(
                recommendation,
                kits,
            )
        }

        /// App-wide builder handoff with the next batch and per-surface packets.
        pub fn builder_handoff(&self) -> DesktopCapabilityBuilderHandoff {
            DesktopCapabilityBuilderHandoff::from_contract(self)
        }

        /// Execution kits selected by a supplied coverage recommendation.
        pub fn execution_kits_for_recommendation(
            &self,
            recommendation: &DesktopCapabilityIntakeExecutionRecommendation,
        ) -> Vec<DesktopCapabilityIntakeExecutionKit> {
            match recommendation.focus {
                DesktopCapabilityExecutionFocus::NativeBlockers => self.blocker_execution_kits(),
                DesktopCapabilityExecutionFocus::NativeWork => self.native_execution_kits(),
                DesktopCapabilityExecutionFocus::FailedEvidence
                | DesktopCapabilityExecutionFocus::Evidence => self.open_execution_kits(),
                DesktopCapabilityExecutionFocus::BrowserIslands => self.webview_execution_kits(),
                DesktopCapabilityExecutionFocus::RoadmapCaveats => self.roadmap_execution_kits(),
                DesktopCapabilityExecutionFocus::ParityClaim => Vec::new(),
            }
        }

        /// Evidence checklist for the current focused generation pass.
        pub fn current_evidence_checklist(&self) -> Option<&DesktopAcceptanceEvidenceChecklist> {
            self.review.current_evidence_checklist()
        }

        /// Recommended next-step summary for the custom intake contract.
        pub fn next_step(&self) -> DesktopCapabilityIntakeNextStep {
            DesktopCapabilityIntakeNextStep::for_contract(self)
        }

        /// Current worker handoff combining the next-step summary and focused pass.
        pub fn current_work_order(&self) -> DesktopCapabilityIntakeWorkOrder {
            DesktopCapabilityIntakeWorkOrder::for_contract(self)
        }

        /// Recommended next action for the custom intake's current evidence state.
        pub fn next_action(&self) -> DesktopGenerationNextAction {
            if self.native_first_plan.blocker_count() > 0 {
                DesktopGenerationNextAction::ResolveGenerationBlockers
            } else if self.claim.evidence_failed_count > 0 {
                DesktopGenerationNextAction::FixFailedEvidence
            } else if self.claim.evidence_missing_count > 0 && self.claim.evidence_passed_count == 0
            {
                DesktopGenerationNextAction::GenerateReadyNativeWork
            } else if self.claim.evidence_missing_count > 0 {
                DesktopGenerationNextAction::CollectReadyEvidence
            } else if self.claim.status == DesktopParityClaimStatus::RequiresBriefing {
                DesktopGenerationNextAction::BriefCaveats
            } else if self.claim.status == DesktopParityClaimStatus::Allowed {
                DesktopGenerationNextAction::ClaimParity
            } else {
                DesktopGenerationNextAction::CollectReadyEvidence
            }
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop capability intake contract: {} requirements, {} primitives, can generate native now {}, can mark ready {}, claim status {}, next action {}, {} reviewed tickets, {} open tickets, {} evidence items",
                self.intake.requirement_count(),
                self.intake.primitive_count(),
                self.can_generate_native_now(),
                self.can_claim_parity(),
                self.claim.status.as_str(),
                self.next_action().as_str(),
                self.review.review_count(),
                self.review.open_count(),
                self.review.evidence_item_count()
            )
        }
    }

    /// Result of running a bounded builder-handoff evidence loop.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityBuilderLoop {
        /// Final refreshed contract after the loop.
        pub contract: DesktopCapabilityIntakeContract,
        /// Builder continuations produced by each applied evidence batch.
        pub continuations: Vec<DesktopCapabilityBuilderContinuation>,
        /// Final app-wide builder handoff after the loop.
        pub final_handoff: DesktopCapabilityBuilderHandoff,
        /// Maximum steps allowed for this loop.
        pub max_steps: usize,
        /// Reason the loop stopped.
        pub stop_reason: DesktopCapabilityExecutionLoopStopReason,
    }

    impl DesktopCapabilityBuilderLoop {
        /// Build a builder loop result from the final contract and continuations.
        pub fn from_contract_and_continuations(
            contract: DesktopCapabilityIntakeContract,
            continuations: Vec<DesktopCapabilityBuilderContinuation>,
            max_steps: usize,
            stop_reason: DesktopCapabilityExecutionLoopStopReason,
        ) -> Self {
            let final_handoff = contract.builder_handoff();

            Self {
                contract,
                continuations,
                final_handoff,
                max_steps,
                stop_reason,
            }
        }

        /// Number of builder continuations that ran.
        pub fn step_count(&self) -> usize {
            self.continuations.len()
        }

        /// Returns true when the loop stopped because it reached the step cap.
        pub fn reached_step_limit(&self) -> bool {
            self.stop_reason == DesktopCapabilityExecutionLoopStopReason::StepLimitReached
        }

        /// Returns true when the final handoff still has executable work.
        pub fn should_continue(&self) -> bool {
            self.final_handoff.has_next_batch() && !self.final_handoff.can_claim_parity
        }

        /// Returns true when the final contract can mark ready.
        pub fn can_claim_parity(&self) -> bool {
            self.final_handoff.can_claim_parity
        }

        /// Count-level report for the builder loop.
        pub fn final_report(&self) -> DesktopCapabilityBuilderLoopReport {
            DesktopCapabilityBuilderLoopReport::from_loop(self)
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop capability builder loop: {} steps, max steps {}, stop reason {}, reached limit {}, should continue {}, can mark ready {}, {} final next kits",
                self.step_count(),
                self.max_steps,
                self.stop_reason.as_str(),
                self.reached_step_limit(),
                self.should_continue(),
                self.can_claim_parity(),
                self.final_handoff.next_batch.kit_count
            )
        }
    }

