    /// Content-safe acceptance criteria for one Desktop primitive/API family.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopPrimitiveAcceptanceCriteria {
        /// Desktop primitive/API family being verified.
        pub primitive: DesktopPrimitive,
        /// Desktop surface area that owns this primitive family.
        pub area: DesktopSurfaceArea,
        /// Fast checks that prove the surface is wired and usable.
        pub smoke_checks: Vec<String>,
        /// Behavior checks that verify the native path against app requirements.
        pub parity_checks: Vec<String>,
        /// Resource or performance checks needed before claiming better defaults.
        pub resource_checks: Vec<String>,
    }

    impl DesktopPrimitiveAcceptanceCriteria {
        /// Number of smoke checks.
        pub fn smoke_check_count(&self) -> usize {
            self.smoke_checks.len()
        }

        /// Number of behavior checks.
        pub fn parity_check_count(&self) -> usize {
            self.parity_checks.len()
        }

        /// Number of resource checks.
        pub fn resource_check_count(&self) -> usize {
            self.resource_checks.len()
        }

        /// Total acceptance criteria count.
        pub fn criterion_count(&self) -> usize {
            self.smoke_check_count() + self.parity_check_count() + self.resource_check_count()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop primitive acceptance criteria: primitive {}, area {}, {} smoke checks, {} behavior checks, {} resource checks",
                self.primitive.as_str(),
                self.area.as_str(),
                self.smoke_check_count(),
                self.parity_check_count(),
                self.resource_check_count()
            )
        }

        /// Build a missing-by-default evidence checklist for these criteria.
        pub fn evidence_checklist(&self) -> DesktopAcceptanceEvidenceChecklist {
            DesktopAcceptanceEvidenceChecklist::from_criteria(self)
        }
    }

    /// Acceptance criterion category.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum DesktopAcceptanceCriterionKind {
        /// Fast wiring/usability check.
        Smoke,
        /// Behavior/readiness check against app requirements.
        Parity,
        /// Resource or performance evidence check.
        Resource,
    }

    impl DesktopAcceptanceCriterionKind {
        /// Stable text label for diagnostics and UI.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::Smoke => "smoke",
                Self::Parity => "behavior",
                Self::Resource => "resource",
            }
        }

        /// Content-safe description of the evidence artifact expected for this
        /// acceptance criterion kind.
        pub fn expected_evidence_artifact(self) -> &'static str {
            match self {
                Self::Smoke => {
                    "smoke proof: command output, runtime event, screenshot, or checked API result"
                }
                Self::Parity => {
                    "readiness proof: desktop-behavior comparison, requirement checklist, or user-flow result"
                }
                Self::Resource => {
                    "resource proof: runtime snapshot, budget evaluation, benchmark, or bounded telemetry"
                }
            }
        }
    }

    /// Evidence status for one acceptance criterion.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum DesktopAcceptanceEvidenceStatus {
        /// Criterion has not been verified yet.
        Missing,
        /// Criterion has been verified successfully.
        Passed,
        /// Criterion was checked and did not pass.
        Failed,
    }

    impl DesktopAcceptanceEvidenceStatus {
        /// Stable text label for diagnostics and UI.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::Missing => "missing",
                Self::Passed => "passed",
                Self::Failed => "failed",
            }
        }
    }

    /// One content-safe evidence item for a static acceptance criterion.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopAcceptanceEvidenceItem {
        /// Criterion category.
        pub kind: DesktopAcceptanceCriterionKind,
        /// Static criterion text from `DesktopPrimitiveAcceptanceCriteria`.
        pub criterion: String,
        /// Current evidence status.
        pub status: DesktopAcceptanceEvidenceStatus,
    }

    impl DesktopAcceptanceEvidenceItem {
        /// Create a missing evidence item for a static criterion.
        pub fn missing(kind: DesktopAcceptanceCriterionKind, criterion: impl Into<String>) -> Self {
            Self {
                kind,
                criterion: criterion.into(),
                status: DesktopAcceptanceEvidenceStatus::Missing,
            }
        }

        /// Return a copy with an updated evidence status.
        pub fn with_status(mut self, status: DesktopAcceptanceEvidenceStatus) -> Self {
            self.status = status;
            self
        }

        /// Returns true when this item is passed.
        pub fn passed(&self) -> bool {
            self.status == DesktopAcceptanceEvidenceStatus::Passed
        }

        /// Returns true when this item failed.
        pub fn failed(&self) -> bool {
            self.status == DesktopAcceptanceEvidenceStatus::Failed
        }

        /// Returns true when this item has not been verified.
        pub fn missing_evidence(&self) -> bool {
            self.status == DesktopAcceptanceEvidenceStatus::Missing
        }

        /// Content-safe proof artifact guidance for this item.
        pub fn expected_evidence_artifact(&self) -> &'static str {
            self.kind.expected_evidence_artifact()
        }

        /// Whether this item has a proof artifact guidance string.
        pub fn has_expected_evidence_artifact(&self) -> bool {
            !self.expected_evidence_artifact().is_empty()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop acceptance evidence item: kind {}, status {}, criterion set {}, expected artifact {}",
                self.kind.as_str(),
                self.status.as_str(),
                !self.criterion.is_empty(),
                self.has_expected_evidence_artifact()
            )
        }
    }

    /// Evidence checklist for one Desktop primitive/API family.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopAcceptanceEvidenceChecklist {
        /// Desktop primitive/API family being verified.
        pub primitive: DesktopPrimitive,
        /// Desktop surface area that owns this primitive family.
        pub area: DesktopSurfaceArea,
        /// Evidence items for all static acceptance criteria.
        pub items: Vec<DesktopAcceptanceEvidenceItem>,
    }

    impl DesktopAcceptanceEvidenceChecklist {
        /// Build a missing-by-default checklist from static acceptance criteria.
        pub fn from_criteria(criteria: &DesktopPrimitiveAcceptanceCriteria) -> Self {
            let mut items = Vec::new();
            items.extend(criteria.smoke_checks.iter().map(|criterion| {
                DesktopAcceptanceEvidenceItem::missing(
                    DesktopAcceptanceCriterionKind::Smoke,
                    criterion.clone(),
                )
            }));
            items.extend(criteria.parity_checks.iter().map(|criterion| {
                DesktopAcceptanceEvidenceItem::missing(
                    DesktopAcceptanceCriterionKind::Parity,
                    criterion.clone(),
                )
            }));
            items.extend(criteria.resource_checks.iter().map(|criterion| {
                DesktopAcceptanceEvidenceItem::missing(
                    DesktopAcceptanceCriterionKind::Resource,
                    criterion.clone(),
                )
            }));

            Self {
                primitive: criteria.primitive,
                area: criteria.area,
                items,
            }
        }

        /// Number of evidence items.
        pub fn item_count(&self) -> usize {
            self.items.len()
        }

        /// Content-safe expected proof artifact guidance for every evidence item.
        pub fn expected_evidence_artifacts(&self) -> Vec<&'static str> {
            self.items
                .iter()
                .map(DesktopAcceptanceEvidenceItem::expected_evidence_artifact)
                .collect()
        }

        /// Number of evidence items that carry expected proof artifact guidance.
        pub fn expected_evidence_artifact_count(&self) -> usize {
            self.items
                .iter()
                .filter(|item| item.has_expected_evidence_artifact())
                .count()
        }

        /// Number of evidence items with a status.
        pub fn status_count(&self, status: DesktopAcceptanceEvidenceStatus) -> usize {
            self.items
                .iter()
                .filter(|item| item.status == status)
                .count()
        }

        /// Number of passed items.
        pub fn passed_count(&self) -> usize {
            self.status_count(DesktopAcceptanceEvidenceStatus::Passed)
        }

        /// Number of failed items.
        pub fn failed_count(&self) -> usize {
            self.status_count(DesktopAcceptanceEvidenceStatus::Failed)
        }

        /// Number of missing items.
        pub fn missing_count(&self) -> usize {
            self.status_count(DesktopAcceptanceEvidenceStatus::Missing)
        }

        /// Returns true when every evidence item passed.
        pub fn is_complete(&self) -> bool {
            self.item_count() > 0 && self.passed_count() == self.item_count()
        }

        /// Returns true when any evidence item failed.
        pub fn has_failures(&self) -> bool {
            self.failed_count() > 0
        }

        /// Return a copy with one matching criterion status updated.
        pub fn with_status(
            mut self,
            kind: DesktopAcceptanceCriterionKind,
            criterion: &str,
            status: DesktopAcceptanceEvidenceStatus,
        ) -> Self {
            if let Some(item) = self
                .items
                .iter_mut()
                .find(|item| item.kind == kind && item.criterion == criterion)
            {
                item.status = status;
            }
            self
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop acceptance evidence checklist: primitive {}, area {}, {} items, {} expected artifacts, {} passed, {} failed, {} missing, complete {}",
                self.primitive.as_str(),
                self.area.as_str(),
                self.item_count(),
                self.expected_evidence_artifact_count(),
                self.passed_count(),
                self.failed_count(),
                self.missing_count(),
                self.is_complete()
            )
        }
    }

    /// Aggregate evidence report for one or more Desktop primitive/API families.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopAcceptanceEvidenceReport {
        /// Evidence checklists included in this report.
        pub checklists: Vec<DesktopAcceptanceEvidenceChecklist>,
    }

    impl DesktopAcceptanceEvidenceReport {
        /// Build an aggregate evidence report from checklists.
        pub fn from_checklists(
            checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> Self {
            Self {
                checklists: checklists.into_iter().collect(),
            }
        }

        /// Number of primitive checklists in this report.
        pub fn checklist_count(&self) -> usize {
            self.checklists.len()
        }

        /// Number of evidence items across all checklists.
        pub fn item_count(&self) -> usize {
            self.checklists
                .iter()
                .map(DesktopAcceptanceEvidenceChecklist::item_count)
                .sum()
        }

        /// Number of evidence items with a status across all checklists.
        pub fn status_count(&self, status: DesktopAcceptanceEvidenceStatus) -> usize {
            self.checklists
                .iter()
                .map(|checklist| checklist.status_count(status))
                .sum()
        }

        /// Number of passed evidence items.
        pub fn passed_count(&self) -> usize {
            self.status_count(DesktopAcceptanceEvidenceStatus::Passed)
        }

        /// Number of failed evidence items.
        pub fn failed_count(&self) -> usize {
            self.status_count(DesktopAcceptanceEvidenceStatus::Failed)
        }

        /// Number of missing evidence items.
        pub fn missing_count(&self) -> usize {
            self.status_count(DesktopAcceptanceEvidenceStatus::Missing)
        }

        /// Returns true when all included checklists are complete.
        pub fn is_complete(&self) -> bool {
            self.checklist_count() > 0
                && self
                    .checklists
                    .iter()
                    .all(DesktopAcceptanceEvidenceChecklist::is_complete)
        }

        /// Returns true when any included checklist has failures.
        pub fn has_failures(&self) -> bool {
            self.checklists
                .iter()
                .any(DesktopAcceptanceEvidenceChecklist::has_failures)
        }

        /// Returns true when this report is sufficient to mark ready for its scope.
        pub fn can_claim_parity(&self) -> bool {
            self.is_complete() && !self.has_failures()
        }

        /// Primitive families that still have missing or failed evidence.
        pub fn blocked_primitives(&self) -> Vec<DesktopPrimitive> {
            self.checklists
                .iter()
                .filter(|checklist| !checklist.is_complete() || checklist.has_failures())
                .map(|checklist| checklist.primitive)
                .collect()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop acceptance evidence report: {} checklists, {} items, {} passed, {} failed, {} missing, complete {}, can mark ready {}, {} blocked primitives",
                self.checklist_count(),
                self.item_count(),
                self.passed_count(),
                self.failed_count(),
                self.missing_count(),
                self.is_complete(),
                self.can_claim_parity(),
                self.blocked_primitives().len()
            )
        }
    }

    /// Final readiness status after generation readiness and evidence checks.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum DesktopParityClaimStatus {
        /// Readiness can be marked for the evaluated scope.
        Allowed,
        /// Generation is blocked by unavailable required capabilities.
        BlockedByGeneration,
        /// Evidence was checked and at least one criterion failed.
        BlockedByFailedEvidence,
        /// Evidence is absent or incomplete.
        BlockedByMissingEvidence,
        /// Evidence passed, but WebView islands, roadmap items, or caveats must be
        /// stated before claiming full readiness.
        RequiresBriefing,
    }

    impl DesktopParityClaimStatus {
        /// Stable text label for diagnostics and UI.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::Allowed => "allowed",
                Self::BlockedByGeneration => "blocked-by-generation",
                Self::BlockedByFailedEvidence => "blocked-by-failed-evidence",
                Self::BlockedByMissingEvidence => "blocked-by-missing-evidence",
                Self::RequiresBriefing => "requires-briefing",
            }
        }
    }

    /// Content-safe decision for whether a desktop capability readiness decision is allowed.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopParityClaimDecision {
        /// App category being evaluated.
        pub category: DesktopAppCategory,
        /// Final claim status.
        pub status: DesktopParityClaimStatus,
        /// Whether this scope may mark ready now.
        pub can_claim_parity: bool,
        /// Whether generation is allowed by feature readiness.
        pub can_generate: bool,
        /// Whether caveats must be shown before marking readiness.
        pub needs_briefing: bool,
        /// Generation blockers in the current queue.
        pub generation_blocker_count: usize,
        /// Evidence checklists evaluated.
        pub evidence_checklist_count: usize,
        /// Evidence items evaluated.
        pub evidence_item_count: usize,
        /// Passed evidence items.
        pub evidence_passed_count: usize,
        /// Failed evidence items.
        pub evidence_failed_count: usize,
        /// Missing evidence items.
        pub evidence_missing_count: usize,
        /// Primitive families blocked by missing or failed evidence.
        pub blocked_primitive_count: usize,
    }

    impl DesktopParityClaimDecision {
        /// Build a readiness decision from a generation queue and an evidence report.
        pub fn from_queue_and_evidence(
            queue: &DesktopCategoryGenerationQueue,
            evidence: &DesktopAcceptanceEvidenceReport,
        ) -> Self {
            let generation_blocker_count = queue
                .blocking_phase()
                .map(DesktopCategoryGenerationQueuePhase::entry_count)
                .unwrap_or(0);
            let status = if queue.is_blocked() || !queue.can_generate {
                DesktopParityClaimStatus::BlockedByGeneration
            } else if evidence.failed_count() > 0 {
                DesktopParityClaimStatus::BlockedByFailedEvidence
            } else if !evidence.is_complete() || evidence.missing_count() > 0 {
                DesktopParityClaimStatus::BlockedByMissingEvidence
            } else if queue.needs_briefing {
                DesktopParityClaimStatus::RequiresBriefing
            } else {
                DesktopParityClaimStatus::Allowed
            };

            Self {
                category: queue.category,
                status,
                can_claim_parity: status == DesktopParityClaimStatus::Allowed,
                can_generate: queue.can_generate && !queue.is_blocked(),
                needs_briefing: queue.needs_briefing,
                generation_blocker_count,
                evidence_checklist_count: evidence.checklist_count(),
                evidence_item_count: evidence.item_count(),
                evidence_passed_count: evidence.passed_count(),
                evidence_failed_count: evidence.failed_count(),
                evidence_missing_count: evidence.missing_count(),
                blocked_primitive_count: evidence.blocked_primitives().len(),
            }
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop readiness decision: category {}, status {}, can mark ready {}, can generate {}, needs briefing {}, {} generation blockers, {} evidence checklists, {} evidence items, {} passed, {} failed, {} missing, {} blocked primitives",
                self.category.as_str(),
                self.status.as_str(),
                self.can_claim_parity,
                self.can_generate,
                self.needs_briefing,
                self.generation_blocker_count,
                self.evidence_checklist_count,
                self.evidence_item_count,
                self.evidence_passed_count,
                self.evidence_failed_count,
                self.evidence_missing_count,
                self.blocked_primitive_count
            )
        }
    }

    /// Recommended next action for a desktop capability generation contract.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum DesktopGenerationNextAction {
        /// Required primitive/API blockers must be resolved before generation.
        ResolveGenerationBlockers,
        /// Ready native work can be generated from scaffold hints and criteria.
        GenerateReadyNativeWork,
        /// At least one checked criterion failed and needs implementation work.
        FixFailedEvidence,
        /// Some ready-work criteria still need evidence before a claim is allowed.
        CollectReadyEvidence,
        /// Evidence passed, but caveats must be briefed before marking readiness.
        BriefCaveats,
        /// The evaluated ready-work scope can mark ready now.
        ClaimParity,
    }

    impl DesktopGenerationNextAction {
        /// Stable text label for diagnostics and UI.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::ResolveGenerationBlockers => "resolve-generation-blockers",
                Self::GenerateReadyNativeWork => "generate-ready-native-work",
                Self::FixFailedEvidence => "fix-failed-evidence",
                Self::CollectReadyEvidence => "collect-ready-evidence",
                Self::BriefCaveats => "brief-caveats",
                Self::ClaimParity => "mark-ready",
            }
        }

        /// Stable portfolio priority. Lower values should be handled first.
        pub fn priority(self) -> u8 {
            match self {
                Self::ResolveGenerationBlockers => 0,
                Self::FixFailedEvidence => 1,
                Self::GenerateReadyNativeWork => 2,
                Self::CollectReadyEvidence => 3,
                Self::BriefCaveats => 4,
                Self::ClaimParity => 5,
            }
        }
    }

    /// Content-safe next-step summary for category-driven Desktop capability
    /// generation.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopGenerationNextStep {
        /// App category being evaluated.
        pub category: DesktopAppCategory,
        /// Recommended next action.
        pub action: DesktopGenerationNextAction,
        /// Whether native generation is currently allowed.
        pub can_generate_ready_work: bool,
        /// Whether readiness can be marked for the ready-work scope.
        pub can_claim_ready_parity: bool,
        /// Ready native entries available to generate.
        pub ready_entry_count: usize,
        /// Generation blockers in the current queue.
        pub generation_blocker_count: usize,
        /// Evidence items evaluated.
        pub evidence_item_count: usize,
        /// Passed evidence items.
        pub evidence_passed_count: usize,
        /// Failed evidence items.
        pub evidence_failed_count: usize,
        /// Missing evidence items.
        pub evidence_missing_count: usize,
        /// Whether caveats must be briefed before readiness is marked.
        pub needs_briefing: bool,
    }

    impl DesktopGenerationNextStep {
        /// Build the next-step recommendation for a generation contract.
        pub fn for_contract(contract: &DesktopCategoryGenerationContract) -> Self {
            let ready_claim = &contract.ready_claim;
            let action = if !contract.can_generate_ready_work() || contract.queue.is_blocked() {
                DesktopGenerationNextAction::ResolveGenerationBlockers
            } else if ready_claim.evidence_failed_count > 0 {
                DesktopGenerationNextAction::FixFailedEvidence
            } else if ready_claim.evidence_missing_count > 0
                && ready_claim.evidence_passed_count == 0
            {
                DesktopGenerationNextAction::GenerateReadyNativeWork
            } else if ready_claim.evidence_missing_count > 0 {
                DesktopGenerationNextAction::CollectReadyEvidence
            } else if ready_claim.status == DesktopParityClaimStatus::RequiresBriefing {
                DesktopGenerationNextAction::BriefCaveats
            } else if ready_claim.status == DesktopParityClaimStatus::Allowed {
                DesktopGenerationNextAction::ClaimParity
            } else {
                DesktopGenerationNextAction::CollectReadyEvidence
            };

            Self {
                category: contract.category,
                action,
                can_generate_ready_work: contract.can_generate_ready_work(),
                can_claim_ready_parity: contract.can_claim_ready_parity(),
                ready_entry_count: contract.ready_entry_count(),
                generation_blocker_count: ready_claim.generation_blocker_count,
                evidence_item_count: ready_claim.evidence_item_count,
                evidence_passed_count: ready_claim.evidence_passed_count,
                evidence_failed_count: ready_claim.evidence_failed_count,
                evidence_missing_count: ready_claim.evidence_missing_count,
                needs_briefing: ready_claim.needs_briefing,
            }
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop generation next step: category {}, action {}, can generate ready work {}, can mark ready {}, needs briefing {}, {} ready entries, {} generation blockers, {} evidence items, {} passed, {} failed, {} missing",
                self.category.as_str(),
                self.action.as_str(),
                self.can_generate_ready_work,
                self.can_claim_ready_parity,
                self.needs_briefing,
                self.ready_entry_count,
                self.generation_blocker_count,
                self.evidence_item_count,
                self.evidence_passed_count,
                self.evidence_failed_count,
                self.evidence_missing_count
            )
        }
    }

