    /// Actionable handoff for the recommended category in a cross-category
    /// Desktop capability portfolio audit.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityPortfolioHandoff {
        /// Content-safe focus summary.
        pub focus: DesktopCapabilityPortfolioFocus,
        /// Single-category generation contract for the focused category.
        pub contract: DesktopCategoryGenerationContract,
        /// Manifest entries relevant to the focus action.
        pub entries: Vec<DesktopCategoryGenerationManifestEntry>,
    }

    impl DesktopCapabilityPortfolioHandoff {
        /// Build an actionable handoff from a portfolio entry.
        pub fn from_entry(entry: &DesktopCapabilityPortfolioEntry) -> Self {
            let focus = DesktopCapabilityPortfolioFocus::from_entry(entry);
            let entries = match focus.action {
                DesktopGenerationNextAction::ResolveGenerationBlockers => entry
                    .contract
                    .manifest
                    .blocker_entries()
                    .into_iter()
                    .cloned()
                    .collect::<Vec<_>>(),
                DesktopGenerationNextAction::BriefCaveats => entry
                    .contract
                    .manifest
                    .webview_entries()
                    .into_iter()
                    .chain(entry.contract.manifest.roadmap_entries())
                    .cloned()
                    .collect::<Vec<_>>(),
                DesktopGenerationNextAction::GenerateReadyNativeWork
                | DesktopGenerationNextAction::FixFailedEvidence
                | DesktopGenerationNextAction::CollectReadyEvidence
                | DesktopGenerationNextAction::ClaimParity => entry
                    .contract
                    .queue
                    .ready_entries()
                    .into_iter()
                    .cloned()
                    .collect::<Vec<_>>(),
            };

            let entries = if entries.is_empty() {
                entry
                    .contract
                    .queue
                    .current_phase()
                    .map(|phase| phase.entries.clone())
                    .unwrap_or_default()
            } else {
                entries
            };

            Self {
                focus,
                contract: entry.contract.clone(),
                entries,
            }
        }

        /// Number of action entries in the handoff.
        pub fn entry_count(&self) -> usize {
            self.entries.len()
        }

        /// Total feature gaps across handoff entries.
        pub fn feature_gap_count(&self) -> usize {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::feature_gap_count)
                .sum()
        }

        /// Total native starters across handoff entries.
        pub fn native_starter_count(&self) -> usize {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::native_starter_count)
                .sum()
        }

        /// Total setup checks across handoff entries.
        pub fn setup_check_count(&self) -> usize {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::setup_check_count)
                .sum()
        }

        /// Total WebView-island starters across handoff entries.
        pub fn webview_island_count(&self) -> usize {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::webview_island_count)
                .sum()
        }

        /// Total roadmap items across handoff entries.
        pub fn roadmap_item_count(&self) -> usize {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::roadmap_item_count)
                .sum()
        }

        /// Scaffold hints for handoff entries.
        pub fn scaffold_hints(&self) -> Vec<&DesktopPrimitiveScaffoldHint> {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::scaffold_hint)
                .collect()
        }

        /// Acceptance criteria for handoff entries.
        pub fn acceptance_criteria(&self) -> Vec<&DesktopPrimitiveAcceptanceCriteria> {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::acceptance_criteria)
                .collect()
        }

        /// Total acceptance criteria across handoff entries.
        pub fn acceptance_criterion_count(&self) -> usize {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::acceptance_criterion_count)
                .sum()
        }

        /// Missing-by-default evidence checklists for handoff entries.
        pub fn acceptance_evidence_checklists(&self) -> Vec<DesktopAcceptanceEvidenceChecklist> {
            self.entries
                .iter()
                .map(DesktopCategoryGenerationManifestEntry::acceptance_evidence_checklist)
                .collect()
        }

        /// Aggregate evidence report for handoff entries.
        pub fn acceptance_evidence_report(&self) -> DesktopAcceptanceEvidenceReport {
            DesktopAcceptanceEvidenceReport::from_checklists(self.acceptance_evidence_checklists())
        }

        /// Current native-first execution batch for the focused category.
        pub fn current_execution_batch(&self) -> Option<DesktopNativeFirstExecutionBatch> {
            self.contract.current_execution_batch()
        }

        /// Current native-first phase assignment for the focused category.
        pub fn current_phase_assignment(&self) -> Option<DesktopNativeFirstPhaseAssignment> {
            self.contract.current_phase_assignment()
        }

        /// Current native-first execution kit for the focused category.
        pub fn current_execution_kit(&self) -> Option<DesktopCapabilityIntakeExecutionKit> {
            self.contract.current_execution_kit()
        }

        /// Continue the focused category's native-first batch with submitted
        /// evidence and preserve the portfolio focus wrapper.
        pub fn continue_with_execution_batch_evidence(
            &self,
            batch: &DesktopNativeFirstExecutionBatch,
            evidence_checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopCapabilityPortfolioContinuation {
            let continuation = self
                .contract
                .clone()
                .continue_with_execution_batch_evidence(batch, evidence_checklists);
            DesktopCapabilityPortfolioContinuation {
                focus: self.focus.clone(),
                continuation,
            }
        }

        /// Parity-claim decision for the handoff evidence scope.
        pub fn parity_claim_decision(
            &self,
            evidence: &DesktopAcceptanceEvidenceReport,
        ) -> DesktopParityClaimDecision {
            self.contract.queue.parity_claim_decision(evidence)
        }

        /// Review supplied evidence and derive the next action for this handoff.
        pub fn review_evidence(
            &self,
            evidence: DesktopAcceptanceEvidenceReport,
        ) -> DesktopCapabilityPortfolioEvidenceReview {
            DesktopCapabilityPortfolioEvidenceReview::from_handoff_and_evidence(self, evidence)
        }

        /// Review supplied evidence checklists and derive the next action for this
        /// handoff.
        pub fn review_evidence_checklists(
            &self,
            checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopCapabilityPortfolioEvidenceReview {
            self.review_evidence(DesktopAcceptanceEvidenceReport::from_checklists(checklists))
        }

        /// Review the missing-by-default evidence report for this handoff.
        pub fn ready_evidence_review(&self) -> DesktopCapabilityPortfolioEvidenceReview {
            self.review_evidence(self.acceptance_evidence_report())
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop capability portfolio handoff: category {}, action {}, {} entries, {} feature gaps, {} native starters, {} setup checks, {} webview islands, {} roadmap items, {} acceptance criteria, {} evidence items, current execution batch {}",
                self.focus.category.as_str(),
                self.focus.action.as_str(),
                self.entry_count(),
                self.feature_gap_count(),
                self.native_starter_count(),
                self.setup_check_count(),
                self.webview_island_count(),
                self.roadmap_item_count(),
                self.acceptance_criterion_count(),
                self.acceptance_evidence_report().item_count(),
                self.current_execution_batch().is_some()
            )
        }
    }

