    /// Evidence review for an actionable Desktop capability portfolio handoff.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityPortfolioEvidenceReview {
        /// Handoff focus being reviewed.
        pub focus: DesktopCapabilityPortfolioFocus,
        /// Evidence report that was reviewed.
        pub evidence: DesktopAcceptanceEvidenceReport,
        /// Parity claim decision derived from the evidence.
        pub claim: DesktopParityClaimDecision,
        /// Recommended next action after reviewing the evidence.
        pub next_action: DesktopGenerationNextAction,
        /// Number of manifest entries covered by the handoff.
        pub entry_count: usize,
    }

    impl DesktopCapabilityPortfolioEvidenceReview {
        /// Build a reviewed-evidence result for a handoff.
        pub fn from_handoff_and_evidence(
            handoff: &DesktopCapabilityPortfolioHandoff,
            evidence: DesktopAcceptanceEvidenceReport,
        ) -> Self {
            let claim = handoff.parity_claim_decision(&evidence);
            let next_action = if claim.status == DesktopParityClaimStatus::BlockedByGeneration {
                DesktopGenerationNextAction::ResolveGenerationBlockers
            } else if claim.evidence_failed_count > 0 {
                DesktopGenerationNextAction::FixFailedEvidence
            } else if claim.evidence_missing_count > 0 && claim.evidence_passed_count == 0 {
                DesktopGenerationNextAction::GenerateReadyNativeWork
            } else if claim.evidence_missing_count > 0 {
                DesktopGenerationNextAction::CollectReadyEvidence
            } else if claim.status == DesktopParityClaimStatus::RequiresBriefing {
                DesktopGenerationNextAction::BriefCaveats
            } else if claim.status == DesktopParityClaimStatus::Allowed {
                DesktopGenerationNextAction::ClaimParity
            } else {
                DesktopGenerationNextAction::CollectReadyEvidence
            };

            Self {
                focus: handoff.focus.clone(),
                evidence,
                claim,
                next_action,
                entry_count: handoff.entry_count(),
            }
        }

        /// Returns true when the reviewed evidence allows a readiness decision.
        pub fn can_claim_parity(&self) -> bool {
            self.claim.can_claim_parity
        }

        /// Returns true when any reviewed evidence failed.
        pub fn has_failures(&self) -> bool {
            self.evidence.has_failures()
        }

        /// Returns true when reviewed evidence is complete.
        pub fn is_complete(&self) -> bool {
            self.evidence.is_complete()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop capability portfolio evidence review: category {}, action {}, claim status {}, can mark ready {}, {} entries, {} evidence checklists, {} evidence items, {} passed, {} failed, {} missing",
                self.focus.category.as_str(),
                self.next_action.as_str(),
                self.claim.status.as_str(),
                self.can_claim_parity(),
                self.entry_count,
                self.evidence.checklist_count(),
                self.evidence.item_count(),
                self.evidence.passed_count(),
                self.evidence.failed_count(),
                self.evidence.missing_count()
            )
        }
    }

