    /// Cross-category audit for how Kael covers common desktop app shapes.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityPortfolioAudit {
        /// Category entries included in this audit.
        pub entries: Vec<DesktopCapabilityPortfolioEntry>,
    }

    impl DesktopCapabilityPortfolioAudit {
        /// Audit every standard desktop-app app category.
        pub fn all(report: &CapabilityReport) -> Self {
            Self::from_categories(DesktopAppCategory::all(), report)
        }

        /// Audit a selected set of app categories.
        pub fn from_categories(
            categories: impl IntoIterator<Item = DesktopAppCategory>,
            report: &CapabilityReport,
        ) -> Self {
            Self {
                entries: categories
                    .into_iter()
                    .map(|category| DesktopCapabilityPortfolioEntry::for_category(category, report))
                    .collect(),
            }
        }

        /// Number of categories audited.
        pub fn entry_count(&self) -> usize {
            self.entries.len()
        }

        /// Number of categories with a given next action.
        pub fn action_count(&self, action: DesktopGenerationNextAction) -> usize {
            self.entries
                .iter()
                .filter(|entry| entry.next_action() == action)
                .count()
        }

        /// Categories with a given next action.
        pub fn entries_for_action(
            &self,
            action: DesktopGenerationNextAction,
        ) -> Vec<&DesktopCapabilityPortfolioEntry> {
            self.entries
                .iter()
                .filter(|entry| entry.next_action() == action)
                .collect()
        }

        /// Entries ordered by the recommended portfolio work sequence.
        pub fn prioritized_entries(&self) -> Vec<&DesktopCapabilityPortfolioEntry> {
            let mut entries: Vec<_> = self.entries.iter().collect();
            entries.sort_by_key(|entry| {
                (
                    entry.next_action().priority(),
                    std::cmp::Reverse(entry.next_step.generation_blocker_count),
                    std::cmp::Reverse(entry.next_step.evidence_failed_count),
                    std::cmp::Reverse(entry.next_step.ready_entry_count),
                    std::cmp::Reverse(entry.next_step.evidence_missing_count),
                    entry.category.as_str(),
                )
            });
            entries
        }

        /// Highest-priority category entry for the portfolio, when any category was
        /// audited.
        pub fn recommended_entry(&self) -> Option<&DesktopCapabilityPortfolioEntry> {
            self.prioritized_entries().into_iter().next()
        }

        /// Content-safe focus recommendation for the highest-priority category.
        pub fn recommended_focus(&self) -> Option<DesktopCapabilityPortfolioFocus> {
            self.recommended_entry()
                .map(DesktopCapabilityPortfolioFocus::from_entry)
        }

        /// Actionable handoff for the highest-priority category.
        pub fn recommended_handoff(&self) -> Option<DesktopCapabilityPortfolioHandoff> {
            self.recommended_entry()
                .map(DesktopCapabilityPortfolioEntry::handoff)
        }

        /// Native-first execution batch for the recommended portfolio handoff.
        pub fn recommended_execution_batch(&self) -> Option<DesktopNativeFirstExecutionBatch> {
            self.recommended_handoff()
                .and_then(|handoff| handoff.current_execution_batch())
        }

        /// Native-first phase assignment for the recommended portfolio handoff.
        pub fn recommended_phase_assignment(&self) -> Option<DesktopNativeFirstPhaseAssignment> {
            self.recommended_handoff()
                .and_then(|handoff| handoff.current_phase_assignment())
        }

        /// Categories blocked by generation feature gaps.
        pub fn blocked_entries(&self) -> Vec<&DesktopCapabilityPortfolioEntry> {
            self.entries
                .iter()
                .filter(|entry| entry.is_blocked())
                .collect()
        }

        /// Categories where native work can be generated now.
        pub fn ready_entries(&self) -> Vec<&DesktopCapabilityPortfolioEntry> {
            self.entries
                .iter()
                .filter(|entry| entry.can_generate_ready_work())
                .collect()
        }

        /// Categories whose ready-work readiness decision is currently allowed.
        pub fn mark_ready_entries(&self) -> Vec<&DesktopCapabilityPortfolioEntry> {
            self.entries
                .iter()
                .filter(|entry| entry.can_claim_ready_parity())
                .collect()
        }

        /// Categories whose ready-work readiness decision is currently allowed.
        ///
        /// Prefer [`DesktopCapabilityPortfolioAudit::mark_ready_entries`] in new code.
        pub fn claimable_entries(&self) -> Vec<&DesktopCapabilityPortfolioEntry> {
            self.mark_ready_entries()
        }

        /// Categories requiring caveats before readiness is marked.
        pub fn briefing_entries(&self) -> Vec<&DesktopCapabilityPortfolioEntry> {
            self.entries
                .iter()
                .filter(|entry| entry.next_step.needs_briefing)
                .collect()
        }

        /// Total feature gaps across all category manifests.
        pub fn feature_gap_count(&self) -> usize {
            self.entries
                .iter()
                .map(|entry| entry.contract.manifest.feature_gap_count())
                .sum()
        }

        /// Total ready native entries across all categories.
        pub fn ready_entry_count(&self) -> usize {
            self.entries
                .iter()
                .map(|entry| entry.next_step.ready_entry_count)
                .sum()
        }

        /// Total ready-work evidence items across all categories.
        pub fn evidence_item_count(&self) -> usize {
            self.entries
                .iter()
                .map(|entry| entry.next_step.evidence_item_count)
                .sum()
        }

        /// Total missing ready-work evidence items across all categories.
        pub fn evidence_missing_count(&self) -> usize {
            self.entries
                .iter()
                .map(|entry| entry.next_step.evidence_missing_count)
                .sum()
        }

        /// Returns true when every audited category can generate ready native work.
        pub fn can_generate_all_ready_work(&self) -> bool {
            self.entry_count() > 0
                && self
                    .entries
                    .iter()
                    .all(DesktopCapabilityPortfolioEntry::can_generate_ready_work)
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            let focus = self
                .recommended_focus()
                .map(|focus| focus.action.as_str())
                .unwrap_or("none");
            format!(
                "desktop capability portfolio audit: {} categories, {} ready, {} blocked, {} mark-ready, {} need briefing, recommended action {}, {} generate-native actions, {} resolve-blocker actions, {} fix-evidence actions, {} collect-evidence actions, {} brief-caveat actions, {} mark-ready actions, {} feature gaps, {} ready entries, {} evidence items, {} missing evidence",
                self.entry_count(),
                self.ready_entries().len(),
                self.blocked_entries().len(),
                self.mark_ready_entries().len(),
                self.briefing_entries().len(),
                focus,
                self.action_count(DesktopGenerationNextAction::GenerateReadyNativeWork),
                self.action_count(DesktopGenerationNextAction::ResolveGenerationBlockers),
                self.action_count(DesktopGenerationNextAction::FixFailedEvidence),
                self.action_count(DesktopGenerationNextAction::CollectReadyEvidence),
                self.action_count(DesktopGenerationNextAction::BriefCaveats),
                self.action_count(DesktopGenerationNextAction::ClaimParity),
                self.feature_gap_count(),
                self.ready_entry_count(),
                self.evidence_item_count(),
                self.evidence_missing_count()
            )
        }
    }

    /// Evaluated readiness for one desktop surface area.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAreaPlan {
        /// Surface area being audited.
        pub area: DesktopSurfaceArea,
        /// Recommended implementation route.
        pub route: AppParityRoute,
        /// Feature-backed checks for this area.
        pub checked_features: Vec<PlatformFeature>,
        /// Feature-backed checks that are unavailable on the evaluated report.
        pub feature_gaps: Vec<PlatformFeature>,
        /// Feature-backed checks that are unavailable, with support levels.
        pub feature_gap_details: Vec<PlatformFeatureGap>,
    }

    impl DesktopSurfaceAreaPlan {
        /// Evaluate one desktop surface area against a capability report.
        pub fn evaluate(area: DesktopSurfaceArea, report: &CapabilityReport) -> Self {
            let checked_features = area.checked_features();
            let feature_gap_details = checked_features
                .iter()
                .copied()
                .filter_map(|feature| {
                    let support = report.support_for(feature);
                    (!support.is_available()).then_some(PlatformFeatureGap::new(feature, support))
                })
                .collect::<Vec<_>>();
            let feature_gaps = feature_gap_details.iter().map(|gap| gap.feature).collect();

            Self {
                area,
                route: area.default_route(),
                checked_features,
                feature_gaps,
                feature_gap_details,
            }
        }

        /// Returns true when every feature-backed check is available.
        pub fn feature_checks_passed(&self) -> bool {
            self.feature_gaps.is_empty()
        }

        /// Returns true when builders should expose platform caveats or setup.
        pub fn needs_guardrails(&self) -> bool {
            self.route == AppParityRoute::NativeWithGuardrails || !self.feature_gaps.is_empty()
        }

        /// Returns true when this area should be a WebView compatibility island.
        pub fn is_webview_fallback(&self) -> bool {
            self.route.is_webview_fallback()
        }

        /// Returns true when this area is still a roadmap gap.
        pub fn is_roadmap(&self) -> bool {
            self.route.is_roadmap()
        }

        /// Builder-facing implementation brief for this evaluated area.
        pub fn implementation_brief(&self) -> DesktopSurfaceImplementationBrief {
            self.area.implementation_brief()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface area: area {}, route {}, {} feature checks, {} feature gaps",
                self.area.as_str(),
                self.route.as_str(),
                self.checked_features.len(),
                self.feature_gaps.len()
            )
        }
    }

    /// Broad evaluated surface-area audit for a desktop capability app.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditPlan {
        /// Optional app category that selected the audited surface areas.
        pub category: Option<DesktopAppCategory>,
        /// Evaluated surface areas.
        pub areas: Vec<DesktopSurfaceAreaPlan>,
    }

    impl DesktopSurfaceAuditPlan {
        /// Evaluate all standard desktop surface areas.
        pub fn all(report: &CapabilityReport) -> Self {
            desktop_surface_audit(None, DesktopSurfaceArea::all(), report)
        }

        /// Evaluate the standard surface areas for an app category.
        pub fn for_category(category: DesktopAppCategory, report: &CapabilityReport) -> Self {
            desktop_surface_audit(
                Some(category),
                desktop_surface_areas_for_category(category),
                report,
            )
        }

        /// Number of audited surface areas.
        pub fn area_count(&self) -> usize {
            self.areas.len()
        }

        /// Number of areas for a route.
        pub fn route_count(&self, route: AppParityRoute) -> usize {
            self.areas.iter().filter(|area| area.route == route).count()
        }

        /// Total feature gaps across all audited areas.
        pub fn feature_gap_count(&self) -> usize {
            self.areas.iter().map(|area| area.feature_gaps.len()).sum()
        }

        /// Returns true when any audited area has feature gaps.
        pub fn has_feature_gaps(&self) -> bool {
            self.feature_gap_count() > 0
        }

        /// Returns true when any audited area is a WebView compatibility island.
        pub fn has_webview_fallbacks(&self) -> bool {
            self.route_count(AppParityRoute::WebViewFallback) > 0
        }

        /// Returns true when any audited area is still roadmap.
        pub fn has_roadmap_gaps(&self) -> bool {
            self.route_count(AppParityRoute::Roadmap) > 0
        }

        /// Surface areas that need feature fallback, setup, or caveats.
        pub fn areas_with_feature_gaps(&self) -> Vec<&DesktopSurfaceAreaPlan> {
            self.areas
                .iter()
                .filter(|area| !area.feature_checks_passed())
                .collect()
        }

        /// Builder-facing implementation briefs for every audited surface area.
        pub fn implementation_briefs(&self) -> Vec<DesktopSurfaceImplementationBrief> {
            self.areas
                .iter()
                .map(DesktopSurfaceAreaPlan::implementation_brief)
                .collect()
        }

        /// Prioritized broad-surface actions agents should handle before claiming
        /// desktop replacement coverage.
        pub fn action_items(&self) -> Vec<DesktopCapabilityActionItem> {
            let mut items = Vec::new();

            for area in &self.areas {
                let brief = area.implementation_brief();
                if !area.feature_checks_passed() {
                    items.push(DesktopCapabilityActionItem::area(
                        DesktopCapabilityActionKind::ResolveFeatureGaps,
                        area,
                        &brief,
                    ));
                }

                if area.is_roadmap() {
                    items.push(DesktopCapabilityActionItem::area(
                        DesktopCapabilityActionKind::StateRoadmapGap,
                        area,
                        &brief,
                    ));
                } else if area.is_webview_fallback() {
                    items.push(DesktopCapabilityActionItem::area(
                        DesktopCapabilityActionKind::IsolateWebViewIsland,
                        area,
                        &brief,
                    ));
                } else if area.needs_guardrails() {
                    items.push(DesktopCapabilityActionItem::area(
                        DesktopCapabilityActionKind::ApplyNativeGuardrails,
                        area,
                        &brief,
                    ));
                }
            }

            items.sort_by_key(|item| item.priority());
            items
        }

        /// Action items that block broad desktop coverage claims.
        pub fn blocking_action_items(&self) -> Vec<DesktopCapabilityActionItem> {
            self.action_items()
                .into_iter()
                .filter(DesktopCapabilityActionItem::blocks_generation)
                .collect()
        }

        /// Highest-priority broad-surface action item.
        pub fn recommended_action_item(&self) -> Option<DesktopCapabilityActionItem> {
            self.action_items().into_iter().next()
        }

        /// Actionable handoff for the highest-priority broad-surface action.
        pub fn recommended_handoff(&self) -> Option<DesktopSurfaceAuditHandoff> {
            self.recommended_action_item()
                .and_then(|action| DesktopSurfaceAuditHandoff::from_audit_and_action(self, action))
        }

        /// Serializable queue of broad-surface work handoffs for agents and builders.
        pub fn work_queue(&self) -> DesktopSurfaceAuditWorkQueue {
            DesktopSurfaceAuditWorkQueue::from_audit(self)
        }

        /// Continue a broad-surface audit after reviewing evidence for a handoff.
        pub fn continue_with_handoff_evidence(
            &self,
            handoff: &DesktopSurfaceAuditHandoff,
            evidence: DesktopAcceptanceEvidenceReport,
        ) -> DesktopSurfaceAuditContinuation {
            let review = handoff.review_evidence(evidence);
            DesktopSurfaceAuditContinuation::from_audit_and_review(self, review)
        }

        /// Continue a broad-surface audit after reviewing evidence checklists.
        pub fn continue_with_handoff_evidence_checklists(
            &self,
            handoff: &DesktopSurfaceAuditHandoff,
            checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopSurfaceAuditContinuation {
            self.continue_with_handoff_evidence(
                handoff,
                DesktopAcceptanceEvidenceReport::from_checklists(checklists),
            )
        }

        /// Continue a broad-surface audit after completing an execution batch.
        pub fn continue_with_execution_batch_evidence(
            &self,
            batch: &DesktopSurfaceAuditExecutionBatch,
            checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopSurfaceAuditBatchContinuation {
            let continuation =
                self.continue_with_handoff_evidence_checklists(&batch.handoff, checklists);
            DesktopSurfaceAuditBatchContinuation::from_continuation(continuation)
        }

        /// Continue a broad-surface audit after completing a worker packet.
        pub fn continue_with_worker_packet_evidence(
            &self,
            packet: &DesktopSurfaceAuditWorkerPacket,
            checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopSurfaceAuditBatchContinuation {
            let continuation =
                self.continue_with_handoff_evidence_checklists(&packet.handoff(), checklists);
            DesktopSurfaceAuditBatchContinuation::from_continuation(continuation)
        }

        /// Run a bounded broad-surface evidence loop from the current recommended
        /// handoff.
        pub fn run_handoff_evidence_loop(
            &self,
            evidence_batches: impl IntoIterator<Item = Vec<DesktopAcceptanceEvidenceChecklist>>,
            max_steps: usize,
        ) -> DesktopSurfaceAuditLoop {
            let mut continuations = Vec::new();
            let mut closed_actions =
                Vec::<(DesktopCapabilityActionKind, DesktopSurfaceArea)>::new();
            let mut current_handoff = self.recommended_handoff();
            let mut stop_reason = DesktopCapabilityExecutionLoopStopReason::EvidenceExhausted;

            for evidence in evidence_batches.into_iter() {
                if continuations.len() >= max_steps {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::StepLimitReached;
                    break;
                }

                let Some(handoff) = current_handoff.clone() else {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    break;
                };

                let review = handoff
                    .review_evidence(DesktopAcceptanceEvidenceReport::from_checklists(evidence));
                if review.can_close_handoff {
                    closed_actions.push((handoff.action, handoff.area));
                }

                let continuation =
                    DesktopSurfaceAuditContinuation::from_audit_review_and_closed_actions(
                        self,
                        review,
                        &closed_actions,
                    );
                current_handoff = continuation.next_handoff.clone();

                if continuation.next_action() == DesktopGenerationNextAction::ClaimParity {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::ParityClaimed;
                    continuations.push(continuation);
                    break;
                }

                if !continuation.has_next_handoff() {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    continuations.push(continuation);
                    break;
                }

                continuations.push(continuation);
            }

            DesktopSurfaceAuditLoop::from_audit_and_continuations(
                self.clone(),
                continuations,
                max_steps,
                stop_reason,
            )
        }

        /// Run a bounded broad-surface evidence loop from the current work-queue batch.
        pub fn run_execution_batch_loop(
            &self,
            evidence_batches: impl IntoIterator<Item = Vec<DesktopAcceptanceEvidenceChecklist>>,
            max_steps: usize,
        ) -> DesktopSurfaceAuditLoop {
            let mut continuations = Vec::new();
            let mut closed_actions =
                Vec::<(DesktopCapabilityActionKind, DesktopSurfaceArea)>::new();
            let mut current_batch = self.work_queue().current_batch();
            let mut stop_reason = DesktopCapabilityExecutionLoopStopReason::EvidenceExhausted;

            for evidence in evidence_batches.into_iter() {
                if continuations.len() >= max_steps {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::StepLimitReached;
                    break;
                }

                let Some(batch) = current_batch.clone() else {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    break;
                };

                let review = batch.complete_with_evidence_checklists(evidence);
                if review.can_close_handoff {
                    closed_actions.push((batch.handoff.action, batch.handoff.area));
                }

                let continuation =
                    DesktopSurfaceAuditContinuation::from_audit_review_and_closed_actions(
                        self,
                        review,
                        &closed_actions,
                    );
                current_batch = continuation
                    .next_handoff
                    .as_ref()
                    .map(DesktopSurfaceAuditExecutionBatch::from_handoff);

                if continuation.next_action() == DesktopGenerationNextAction::ClaimParity {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::ParityClaimed;
                    continuations.push(continuation);
                    break;
                }

                if !continuation.has_next_handoff() {
                    stop_reason = DesktopCapabilityExecutionLoopStopReason::NoNextBatch;
                    continuations.push(continuation);
                    break;
                }

                continuations.push(continuation);
            }

            DesktopSurfaceAuditLoop::from_audit_and_continuations(
                self.clone(),
                continuations,
                max_steps,
                stop_reason,
            )
        }

        /// Run a bounded broad-surface evidence loop with the recommended lane's
        /// missing-by-default evidence batches.
        pub fn run_recommended_lane_evidence_loop(
            &self,
            max_steps: usize,
        ) -> DesktopSurfaceAuditLoop {
            let evidence_batches = self.work_queue().recommended_lane_evidence_batches();
            self.run_execution_batch_loop(evidence_batches, max_steps)
        }

        /// Serializable recommended-lane handoff with evidence and a dry-run loop.
        pub fn recommended_lane_handoff(
            &self,
            max_steps: usize,
        ) -> DesktopSurfaceAuditRecommendedLaneHandoff {
            DesktopSurfaceAuditRecommendedLaneHandoff::from_audit(self, max_steps)
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            let category = self
                .category
                .map(DesktopAppCategory::as_str)
                .unwrap_or("all desktop surfaces");

            format!(
                "desktop surface audit: category {}, {} areas, {} native-ready, {} native-with-guardrails, {} webview-fallback, {} roadmap, {} feature gaps",
                category,
                self.area_count(),
                self.route_count(AppParityRoute::NativeReady),
                self.route_count(AppParityRoute::NativeWithGuardrails),
                self.route_count(AppParityRoute::WebViewFallback),
                self.route_count(AppParityRoute::Roadmap),
                self.feature_gap_count()
            )
        }
    }

    /// Actionable handoff for one broad desktop surface audit item.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditHandoff {
        /// Optional app category that selected the audited surface areas.
        pub category: Option<DesktopAppCategory>,
        /// Recommended action for this surface.
        pub action: DesktopCapabilityActionKind,
        /// Surface area to handle next.
        pub area: DesktopSurfaceArea,
        /// Evaluated area plan.
        pub area_plan: DesktopSurfaceAreaPlan,
        /// Builder-facing implementation brief.
        pub implementation_brief: DesktopSurfaceImplementationBrief,
        /// Unavailable feature-backed checks with support levels.
        pub feature_gap_details: Vec<PlatformFeatureGap>,
        /// Native Kael primitives or API families to consider first.
        pub native_primitives: Vec<String>,
        /// Browser-shaped cases where a WebView island is justified.
        pub webview_when: Vec<String>,
        /// Product gaps that should be stated as roadmap instead of implied parity.
        pub roadmap_items: Vec<String>,
    }

    impl DesktopSurfaceAuditHandoff {
        /// Build a handoff from a broad surface audit action.
        pub fn from_audit_and_action(
            audit: &DesktopSurfaceAuditPlan,
            action: DesktopCapabilityActionItem,
        ) -> Option<Self> {
            let area = action.area?;
            let area_plan = audit.areas.iter().find(|plan| plan.area == area)?.clone();
            let implementation_brief = area_plan.implementation_brief();

            Some(Self {
                category: audit.category,
                action: action.kind,
                area,
                feature_gap_details: area_plan.feature_gap_details.clone(),
                native_primitives: implementation_brief.native_primitives.clone(),
                webview_when: implementation_brief.webview_when.clone(),
                roadmap_items: implementation_brief.roadmap_items.clone(),
                area_plan,
                implementation_brief,
            })
        }

        /// Returns true when this handoff blocks broad desktop coverage claims.
        pub fn blocks_generation(&self) -> bool {
            self.action == DesktopCapabilityActionKind::ResolveFeatureGaps
                && !self.feature_gap_details.is_empty()
        }

        /// Returns true when the handoff points at native or platform work.
        pub fn targets_native_work(&self) -> bool {
            matches!(
                self.action,
                DesktopCapabilityActionKind::ResolveFeatureGaps
                    | DesktopCapabilityActionKind::ApplyNativeGuardrails
            )
        }

        /// Returns true when the handoff is intentionally browser-shaped.
        pub fn targets_webview_island(&self) -> bool {
            self.action == DesktopCapabilityActionKind::IsolateWebViewIsland
        }

        /// Returns true when the handoff should be represented as roadmap work.
        pub fn targets_roadmap(&self) -> bool {
            self.action == DesktopCapabilityActionKind::StateRoadmapGap
        }

        /// Acceptance criteria for primitives owned by this surface area.
        pub fn acceptance_criteria(&self) -> Vec<DesktopPrimitiveAcceptanceCriteria> {
            DesktopPrimitive::all()
                .into_iter()
                .filter(|primitive| primitive.surface_area() == self.area)
                .map(DesktopPrimitive::acceptance_criteria)
                .collect()
        }

        /// Missing-by-default evidence checklists for this surface handoff.
        pub fn evidence_checklists(&self) -> Vec<DesktopAcceptanceEvidenceChecklist> {
            self.acceptance_criteria()
                .into_iter()
                .map(|criteria| criteria.evidence_checklist())
                .collect()
        }

        /// Missing-by-default evidence report for this surface handoff.
        pub fn evidence_report(&self) -> DesktopAcceptanceEvidenceReport {
            DesktopAcceptanceEvidenceReport::from_checklists(self.evidence_checklists())
        }

        /// Review supplied evidence and derive the next broad-surface action.
        pub fn review_evidence(
            &self,
            evidence: DesktopAcceptanceEvidenceReport,
        ) -> DesktopSurfaceAuditEvidenceReview {
            DesktopSurfaceAuditEvidenceReview::from_handoff_and_evidence(self, evidence)
        }

        /// Review supplied evidence checklists and derive the next broad-surface action.
        pub fn review_evidence_checklists(
            &self,
            checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopSurfaceAuditEvidenceReview {
            self.review_evidence(DesktopAcceptanceEvidenceReport::from_checklists(checklists))
        }

        /// Review this handoff's missing-by-default evidence.
        pub fn ready_evidence_review(&self) -> DesktopSurfaceAuditEvidenceReview {
            self.review_evidence(self.evidence_report())
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            let category = self
                .category
                .map(DesktopAppCategory::as_str)
                .unwrap_or("all desktop surfaces");

            format!(
                "desktop surface audit handoff: category {}, action {}, area {}, blocks generation {}, targets native {}, targets webview {}, targets roadmap {}, {} feature gaps, {} native primitives, {} webview conditions, {} roadmap items",
                category,
                self.action.as_str(),
                self.area.as_str(),
                self.blocks_generation(),
                self.targets_native_work(),
                self.targets_webview_island(),
                self.targets_roadmap(),
                self.feature_gap_details.len(),
                self.native_primitives.len(),
                self.webview_when.len(),
                self.roadmap_items.len()
            )
        }
    }

    /// Serializable work queue for a broad desktop surface audit.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditWorkQueue {
        /// Optional app category that selected the audited surface areas.
        pub category: Option<DesktopAppCategory>,
        /// Prioritized broad-surface handoffs.
        pub handoffs: Vec<DesktopSurfaceAuditHandoff>,
        /// Number of handoffs that block generation/readiness claims.
        pub blocker_count: usize,
        /// Number of handoffs targeting native/platform work.
        pub native_work_count: usize,
        /// Number of intentionally browser-shaped WebView island handoffs.
        pub webview_island_count: usize,
        /// Number of roadmap/caveat handoffs.
        pub roadmap_count: usize,
        /// Total acceptance-evidence checklists attached to the queue.
        pub evidence_checklist_count: usize,
        /// Total acceptance-evidence items attached to the queue.
        pub evidence_item_count: usize,
    }

    impl DesktopSurfaceAuditWorkQueue {
        /// Build a prioritized broad-surface work queue from an audit.
        pub fn from_audit(audit: &DesktopSurfaceAuditPlan) -> Self {
            let handoffs = audit
                .action_items()
                .into_iter()
                .filter_map(|action| {
                    DesktopSurfaceAuditHandoff::from_audit_and_action(audit, action)
                })
                .collect::<Vec<_>>();
            let blocker_count = handoffs
                .iter()
                .filter(|handoff| handoff.blocks_generation())
                .count();
            let native_work_count = handoffs
                .iter()
                .filter(|handoff| handoff.targets_native_work())
                .count();
            let webview_island_count = handoffs
                .iter()
                .filter(|handoff| handoff.targets_webview_island())
                .count();
            let roadmap_count = handoffs
                .iter()
                .filter(|handoff| handoff.targets_roadmap())
                .count();
            let evidence_checklist_count = handoffs
                .iter()
                .map(|handoff| handoff.evidence_checklists().len())
                .sum();
            let evidence_item_count = handoffs
                .iter()
                .flat_map(DesktopSurfaceAuditHandoff::evidence_checklists)
                .map(|checklist| checklist.item_count())
                .sum();

            Self {
                category: audit.category,
                handoffs,
                blocker_count,
                native_work_count,
                webview_island_count,
                roadmap_count,
                evidence_checklist_count,
                evidence_item_count,
            }
        }

        /// Number of queued handoffs.
        pub fn handoff_count(&self) -> usize {
            self.handoffs.len()
        }

        /// Returns true when no work remains in the queue.
        pub fn is_empty(&self) -> bool {
            self.handoffs.is_empty()
        }

        /// Highest-priority handoff in the queue.
        pub fn current_handoff(&self) -> Option<&DesktopSurfaceAuditHandoff> {
            self.handoffs.first()
        }

        /// Count-level assignment for the highest-priority handoff.
        pub fn current_assignment(&self) -> Option<DesktopSurfaceAuditAssignment> {
            self.current_handoff()
                .map(DesktopSurfaceAuditAssignment::from_handoff)
        }

        /// Executable batch for the highest-priority handoff.
        pub fn current_batch(&self) -> Option<DesktopSurfaceAuditExecutionBatch> {
            self.current_handoff()
                .map(DesktopSurfaceAuditExecutionBatch::from_handoff)
        }

        /// Executable batches for every queued handoff.
        pub fn execution_batches(&self) -> Vec<DesktopSurfaceAuditExecutionBatch> {
            self.handoffs
                .iter()
                .map(DesktopSurfaceAuditExecutionBatch::from_handoff)
                .collect()
        }

        /// Executable batches that currently block generation/readiness claims.
        pub fn blocking_batches(&self) -> Vec<DesktopSurfaceAuditExecutionBatch> {
            self.blocking_handoffs()
                .into_iter()
                .map(DesktopSurfaceAuditExecutionBatch::from_handoff)
                .collect()
        }

        /// Executable batches that target native/platform work.
        pub fn native_batches(&self) -> Vec<DesktopSurfaceAuditExecutionBatch> {
            self.native_handoffs()
                .into_iter()
                .map(DesktopSurfaceAuditExecutionBatch::from_handoff)
                .collect()
        }

        /// Executable batches that target explicit WebView islands.
        pub fn webview_batches(&self) -> Vec<DesktopSurfaceAuditExecutionBatch> {
            self.webview_handoffs()
                .into_iter()
                .map(DesktopSurfaceAuditExecutionBatch::from_handoff)
                .collect()
        }

        /// Executable batches that target roadmap/caveat briefing.
        pub fn roadmap_batches(&self) -> Vec<DesktopSurfaceAuditExecutionBatch> {
            self.roadmap_handoffs()
                .into_iter()
                .map(DesktopSurfaceAuditExecutionBatch::from_handoff)
                .collect()
        }

        /// Count-level lane summaries for scheduler allocation.
        pub fn lane_summaries(&self) -> Vec<DesktopSurfaceAuditLaneSummary> {
            let mut summaries = Vec::new();
            let blocking_batches = self.blocking_batches();
            let native_batches = self
                .native_batches()
                .into_iter()
                .filter(|batch| !batch.blocks_generation())
                .collect::<Vec<_>>();
            let webview_batches = self.webview_batches();
            let roadmap_batches = self.roadmap_batches();

            for (focus, batches) in [
                (
                    DesktopCapabilityExecutionFocus::NativeBlockers,
                    blocking_batches,
                ),
                (DesktopCapabilityExecutionFocus::NativeWork, native_batches),
                (
                    DesktopCapabilityExecutionFocus::BrowserIslands,
                    webview_batches,
                ),
                (
                    DesktopCapabilityExecutionFocus::RoadmapCaveats,
                    roadmap_batches,
                ),
            ] {
                let summary = DesktopSurfaceAuditLaneSummary::from_batches(focus, batches);
                if summary.has_batches() {
                    summaries.push(summary);
                }
            }

            summaries
        }

        /// Recommended lane to run next.
        pub fn recommended_lane_summary(&self) -> Option<DesktopSurfaceAuditLaneSummary> {
            self.lane_summaries().into_iter().next()
        }

        /// Executable batches for the recommended lane.
        pub fn recommended_lane_batches(&self) -> Vec<DesktopSurfaceAuditExecutionBatch> {
            let Some(lane) = self.recommended_lane_summary() else {
                return Vec::new();
            };

            match lane.focus {
                DesktopCapabilityExecutionFocus::NativeBlockers => self.blocking_batches(),
                DesktopCapabilityExecutionFocus::NativeWork => self
                    .native_batches()
                    .into_iter()
                    .filter(|batch| !batch.blocks_generation())
                    .collect(),
                DesktopCapabilityExecutionFocus::BrowserIslands => self.webview_batches(),
                DesktopCapabilityExecutionFocus::RoadmapCaveats => self.roadmap_batches(),
                DesktopCapabilityExecutionFocus::FailedEvidence
                | DesktopCapabilityExecutionFocus::Evidence
                | DesktopCapabilityExecutionFocus::ParityClaim => Vec::new(),
            }
        }

        /// Missing-by-default evidence checklists grouped by recommended-lane batch.
        pub fn recommended_lane_evidence_batches(
            &self,
        ) -> Vec<Vec<DesktopAcceptanceEvidenceChecklist>> {
            self.recommended_lane_batches()
                .into_iter()
                .map(|batch| batch.evidence_checklists)
                .collect()
        }

        /// Missing-by-default evidence checklists for the recommended lane.
        pub fn recommended_lane_evidence_checklists(
            &self,
        ) -> Vec<DesktopAcceptanceEvidenceChecklist> {
            self.recommended_lane_evidence_batches()
                .into_iter()
                .flatten()
                .collect()
        }

        /// Aggregate evidence report for the recommended lane.
        pub fn recommended_lane_evidence_report(&self) -> DesktopAcceptanceEvidenceReport {
            DesktopAcceptanceEvidenceReport::from_checklists(
                self.recommended_lane_evidence_checklists(),
            )
        }

        /// Dispatch/readiness decision for the recommended lane.
        pub fn recommended_lane_decision(&self) -> DesktopSurfaceAuditLaneDecision {
            DesktopSurfaceAuditLaneDecision::from_work_queue(self)
        }

        /// Handoffs that currently block generation/readiness claims.
        pub fn blocking_handoffs(&self) -> Vec<&DesktopSurfaceAuditHandoff> {
            self.handoffs
                .iter()
                .filter(|handoff| handoff.blocks_generation())
                .collect()
        }

        /// Handoffs that target native/platform work.
        pub fn native_handoffs(&self) -> Vec<&DesktopSurfaceAuditHandoff> {
            self.handoffs
                .iter()
                .filter(|handoff| handoff.targets_native_work())
                .collect()
        }

        /// Handoffs that target explicit WebView islands.
        pub fn webview_handoffs(&self) -> Vec<&DesktopSurfaceAuditHandoff> {
            self.handoffs
                .iter()
                .filter(|handoff| handoff.targets_webview_island())
                .collect()
        }

        /// Handoffs that target roadmap/caveat briefing.
        pub fn roadmap_handoffs(&self) -> Vec<&DesktopSurfaceAuditHandoff> {
            self.handoffs
                .iter()
                .filter(|handoff| handoff.targets_roadmap())
                .collect()
        }

        /// Returns true when queued native/platform work exists.
        pub fn has_native_work(&self) -> bool {
            self.native_work_count > 0
        }

        /// Returns true when queued work includes any explicit WebView island.
        pub fn has_webview_islands(&self) -> bool {
            self.webview_island_count > 0
        }

        /// Returns true when queued work includes roadmap/caveat items.
        pub fn has_roadmap_items(&self) -> bool {
            self.roadmap_count > 0
        }

        /// Missing-by-default evidence checklists for every queued handoff.
        pub fn evidence_checklists(&self) -> Vec<DesktopAcceptanceEvidenceChecklist> {
            self.handoffs
                .iter()
                .flat_map(DesktopSurfaceAuditHandoff::evidence_checklists)
                .collect()
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            let category = self
                .category
                .map(DesktopAppCategory::as_str)
                .unwrap_or("all desktop surfaces");
            let current_area = self
                .current_handoff()
                .map(|handoff| handoff.area.as_str())
                .unwrap_or("none");
            let current_action = self
                .current_handoff()
                .map(|handoff| handoff.action.as_str())
                .unwrap_or("none");

            format!(
                "desktop surface audit work queue: category {}, {} handoffs, current area {}, current action {}, {} blockers, {} native work, {} webview islands, {} roadmap items, {} evidence checklists, {} evidence items",
                category,
                self.handoff_count(),
                current_area,
                current_action,
                self.blocker_count,
                self.native_work_count,
                self.webview_island_count,
                self.roadmap_count,
                self.evidence_checklist_count,
                self.evidence_item_count
            )
        }
    }

    /// Count-level worker assignment for one broad desktop surface audit handoff.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditAssignment {
        /// Optional app category that selected the audited surface areas.
        pub category: Option<DesktopAppCategory>,
        /// Recommended action for this surface.
        pub action: DesktopCapabilityActionKind,
        /// Surface area to handle.
        pub area: DesktopSurfaceArea,
        /// Worker focus bucket for schedulers.
        pub focus: DesktopCapabilityExecutionFocus,
        /// Whether this assignment blocks generation/readiness claims.
        pub blocks_generation: bool,
        /// Whether this assignment targets native/platform work.
        pub targets_native_work: bool,
        /// Whether this assignment is an explicit WebView island.
        pub targets_webview_island: bool,
        /// Whether this assignment is roadmap/caveat work.
        pub targets_roadmap: bool,
        /// Feature-backed native/platform gaps.
        pub feature_gap_count: usize,
        /// Native Kael primitive/API starter count.
        pub native_primitive_count: usize,
        /// WebView island condition count.
        pub webview_condition_count: usize,
        /// Roadmap/caveat item count.
        pub roadmap_item_count: usize,
        /// Acceptance-evidence checklist count.
        pub evidence_checklist_count: usize,
        /// Acceptance-evidence item count.
        pub evidence_item_count: usize,
    }

    impl DesktopSurfaceAuditAssignment {
        /// Build a count-level assignment from a broad surface handoff.
        pub fn from_handoff(handoff: &DesktopSurfaceAuditHandoff) -> Self {
            let evidence_checklists = handoff.evidence_checklists();
            let focus = if handoff.blocks_generation() {
                DesktopCapabilityExecutionFocus::NativeBlockers
            } else if handoff.targets_native_work() {
                DesktopCapabilityExecutionFocus::NativeWork
            } else if handoff.targets_webview_island() {
                DesktopCapabilityExecutionFocus::BrowserIslands
            } else if handoff.targets_roadmap() {
                DesktopCapabilityExecutionFocus::RoadmapCaveats
            } else {
                DesktopCapabilityExecutionFocus::Evidence
            };

            Self {
                category: handoff.category,
                action: handoff.action,
                area: handoff.area,
                focus,
                blocks_generation: handoff.blocks_generation(),
                targets_native_work: handoff.targets_native_work(),
                targets_webview_island: handoff.targets_webview_island(),
                targets_roadmap: handoff.targets_roadmap(),
                feature_gap_count: handoff.feature_gap_details.len(),
                native_primitive_count: handoff.native_primitives.len(),
                webview_condition_count: handoff.webview_when.len(),
                roadmap_item_count: handoff.roadmap_items.len(),
                evidence_checklist_count: evidence_checklists.len(),
                evidence_item_count: evidence_checklists
                    .iter()
                    .map(DesktopAcceptanceEvidenceChecklist::item_count)
                    .sum(),
            }
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            let category = self
                .category
                .map(DesktopAppCategory::as_str)
                .unwrap_or("all desktop surfaces");

            format!(
                "desktop surface audit assignment: category {}, action {}, area {}, focus {}, blocks generation {}, targets native {}, targets webview {}, targets roadmap {}, {} feature gaps, {} native primitives, {} webview conditions, {} roadmap items, {} evidence checklists, {} evidence items",
                category,
                self.action.as_str(),
                self.area.as_str(),
                self.focus.as_str(),
                self.blocks_generation,
                self.targets_native_work,
                self.targets_webview_island,
                self.targets_roadmap,
                self.feature_gap_count,
                self.native_primitive_count,
                self.webview_condition_count,
                self.roadmap_item_count,
                self.evidence_checklist_count,
                self.evidence_item_count
            )
        }
    }

    /// Count-level scheduler summary for one broad desktop surface audit lane.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditLaneSummary {
        /// Worker focus bucket for the lane.
        pub focus: DesktopCapabilityExecutionFocus,
        /// Number of executable batches in the lane.
        pub batch_count: usize,
        /// Feature-backed native/platform gaps across batches.
        pub feature_gap_count: usize,
        /// Native Kael primitive/API starter count across batches.
        pub native_primitive_count: usize,
        /// WebView island condition count across batches.
        pub webview_condition_count: usize,
        /// Roadmap/caveat item count across batches.
        pub roadmap_item_count: usize,
        /// Acceptance-evidence checklist count across batches.
        pub evidence_checklist_count: usize,
        /// Acceptance-evidence item count across batches.
        pub evidence_item_count: usize,
        /// Whether this lane targets native/platform work.
        pub targets_native_work: bool,
        /// Whether this lane targets explicit WebView islands.
        pub targets_webview_island: bool,
        /// Whether this lane targets roadmap/caveat work.
        pub targets_roadmap: bool,
    }

    impl DesktopSurfaceAuditLaneSummary {
        /// Build a lane summary from executable batches.
        pub fn from_batches(
            focus: DesktopCapabilityExecutionFocus,
            batches: Vec<DesktopSurfaceAuditExecutionBatch>,
        ) -> Self {
            Self {
                focus,
                batch_count: batches.len(),
                feature_gap_count: batches
                    .iter()
                    .map(|batch| batch.assignment.feature_gap_count)
                    .sum(),
                native_primitive_count: batches
                    .iter()
                    .map(|batch| batch.assignment.native_primitive_count)
                    .sum(),
                webview_condition_count: batches
                    .iter()
                    .map(|batch| batch.assignment.webview_condition_count)
                    .sum(),
                roadmap_item_count: batches
                    .iter()
                    .map(|batch| batch.assignment.roadmap_item_count)
                    .sum(),
                evidence_checklist_count: batches
                    .iter()
                    .map(DesktopSurfaceAuditExecutionBatch::evidence_checklist_count)
                    .sum(),
                evidence_item_count: batches
                    .iter()
                    .map(DesktopSurfaceAuditExecutionBatch::evidence_item_count)
                    .sum(),
                targets_native_work: batches
                    .iter()
                    .any(DesktopSurfaceAuditExecutionBatch::targets_native_work),
                targets_webview_island: batches
                    .iter()
                    .any(|batch| batch.assignment.targets_webview_island),
                targets_roadmap: batches.iter().any(|batch| batch.assignment.targets_roadmap),
            }
        }

        /// Returns true when this lane has executable batches.
        pub fn has_batches(&self) -> bool {
            self.batch_count > 0
        }

        /// Returns true when this lane resolves native/platform blockers.
        pub fn is_blocker_lane(&self) -> bool {
            self.focus == DesktopCapabilityExecutionFocus::NativeBlockers
        }

        /// Returns true when this lane is native/platform implementation work.
        pub fn is_native_work_lane(&self) -> bool {
            self.focus == DesktopCapabilityExecutionFocus::NativeWork
        }

        /// Returns true when this lane is explicit WebView-island work.
        pub fn is_webview_lane(&self) -> bool {
            self.focus == DesktopCapabilityExecutionFocus::BrowserIslands
        }

        /// Returns true when this lane is roadmap/caveat briefing.
        pub fn is_roadmap_lane(&self) -> bool {
            self.focus == DesktopCapabilityExecutionFocus::RoadmapCaveats
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit lane summary: focus {}, {} batches, {} feature gaps, {} native primitives, {} webview conditions, {} roadmap items, {} evidence checklists, {} evidence items, targets native {}, targets webview {}, targets roadmap {}",
                self.focus.as_str(),
                self.batch_count,
                self.feature_gap_count,
                self.native_primitive_count,
                self.webview_condition_count,
                self.roadmap_item_count,
                self.evidence_checklist_count,
                self.evidence_item_count,
                self.targets_native_work,
                self.targets_webview_island,
                self.targets_roadmap
            )
        }
    }

    /// Dispatch/readiness decision for one broad desktop surface audit lane.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditLaneDecision {
        /// Recommended lane summary, if broad-surface work remains.
        pub lane: Option<DesktopSurfaceAuditLaneSummary>,
        /// Recommended next action for the lane.
        pub next_action: DesktopGenerationNextAction,
        /// Readiness status for the lane.
        pub status: DesktopParityClaimStatus,
        /// Whether the broad-surface scope can mark ready now.
        pub can_claim_parity: bool,
        /// Whether a worker should be dispatched for this lane.
        pub should_dispatch: bool,
        /// Number of executable batches in the lane.
        pub batch_count: usize,
        /// Acceptance-evidence checklist count in the lane.
        pub evidence_checklist_count: usize,
        /// Acceptance-evidence item count in the lane.
        pub evidence_item_count: usize,
        /// Passed evidence items in the lane.
        pub evidence_passed_count: usize,
        /// Failed evidence items in the lane.
        pub evidence_failed_count: usize,
        /// Missing evidence items in the lane.
        pub evidence_missing_count: usize,
        /// Whether this lane targets native/platform work.
        pub targets_native_work: bool,
        /// Whether this lane targets explicit WebView islands.
        pub targets_webview_island: bool,
        /// Whether this lane targets roadmap/caveat work.
        pub targets_roadmap: bool,
    }

    impl DesktopSurfaceAuditLaneDecision {
        /// Build a dispatch/readiness decision from the recommended work-queue lane.
        pub fn from_work_queue(queue: &DesktopSurfaceAuditWorkQueue) -> Self {
            let lane = queue.recommended_lane_summary();
            let evidence = queue.recommended_lane_evidence_report();
            let (next_action, status) = lane
                .as_ref()
                .map(|lane| {
                    if lane.is_blocker_lane() {
                        (
                            DesktopGenerationNextAction::ResolveGenerationBlockers,
                            DesktopParityClaimStatus::BlockedByGeneration,
                        )
                    } else if evidence.has_failures() {
                        (
                            DesktopGenerationNextAction::FixFailedEvidence,
                            DesktopParityClaimStatus::BlockedByFailedEvidence,
                        )
                    } else if lane.is_webview_lane() || lane.is_roadmap_lane() {
                        (
                            DesktopGenerationNextAction::BriefCaveats,
                            DesktopParityClaimStatus::RequiresBriefing,
                        )
                    } else if evidence.can_claim_parity() {
                        (
                            DesktopGenerationNextAction::ClaimParity,
                            DesktopParityClaimStatus::Allowed,
                        )
                    } else if lane.is_native_work_lane() {
                        (
                            DesktopGenerationNextAction::GenerateReadyNativeWork,
                            DesktopParityClaimStatus::BlockedByMissingEvidence,
                        )
                    } else {
                        (
                            DesktopGenerationNextAction::CollectReadyEvidence,
                            DesktopParityClaimStatus::BlockedByMissingEvidence,
                        )
                    }
                })
                .unwrap_or((
                    DesktopGenerationNextAction::ClaimParity,
                    DesktopParityClaimStatus::Allowed,
                ));
            let can_claim_parity = status == DesktopParityClaimStatus::Allowed;

            Self {
                next_action,
                status,
                can_claim_parity,
                should_dispatch: lane
                    .as_ref()
                    .map(DesktopSurfaceAuditLaneSummary::has_batches)
                    .unwrap_or(false)
                    && !can_claim_parity,
                batch_count: lane.as_ref().map(|lane| lane.batch_count).unwrap_or(0),
                evidence_checklist_count: evidence.checklist_count(),
                evidence_item_count: evidence.item_count(),
                evidence_passed_count: evidence.passed_count(),
                evidence_failed_count: evidence.failed_count(),
                evidence_missing_count: evidence.missing_count(),
                targets_native_work: lane
                    .as_ref()
                    .map(|lane| lane.targets_native_work)
                    .unwrap_or(false),
                targets_webview_island: lane
                    .as_ref()
                    .map(|lane| lane.targets_webview_island)
                    .unwrap_or(false),
                targets_roadmap: lane
                    .as_ref()
                    .map(|lane| lane.targets_roadmap)
                    .unwrap_or(false),
                lane,
            }
        }

        /// Returns true when this decision points to native/platform work.
        pub fn targets_native_work(&self) -> bool {
            self.targets_native_work
        }

        /// Returns true when this decision points to caveat or browser-island work.
        pub fn targets_caveat_briefing(&self) -> bool {
            self.targets_webview_island || self.targets_roadmap
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            let focus = self
                .lane
                .as_ref()
                .map(|lane| lane.focus.as_str())
                .unwrap_or("none");

            format!(
                "desktop surface audit lane decision: focus {}, next action {}, status {}, can mark ready {}, should dispatch {}, {} batches, {} evidence checklists, {} evidence items, {} passed, {} failed, {} missing, targets native {}, targets webview {}, targets roadmap {}",
                focus,
                self.next_action.as_str(),
                self.status.as_str(),
                self.can_claim_parity,
                self.should_dispatch,
                self.batch_count,
                self.evidence_checklist_count,
                self.evidence_item_count,
                self.evidence_passed_count,
                self.evidence_failed_count,
                self.evidence_missing_count,
                self.targets_native_work,
                self.targets_webview_island,
                self.targets_roadmap
            )
        }
    }

    /// Serializable package for dispatching the recommended broad-surface audit lane.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditRecommendedLaneHandoff {
        /// Recommended lane dispatch/readiness decision.
        pub decision: DesktopSurfaceAuditLaneDecision,
        /// Executable batches in the recommended lane.
        pub batches: Vec<DesktopSurfaceAuditExecutionBatch>,
        /// Worker-ready packets in the recommended lane.
        pub worker_packets: Vec<DesktopSurfaceAuditWorkerPacket>,
        /// Missing-by-default evidence grouped one bundle per batch.
        pub evidence_batches: Vec<Vec<DesktopAcceptanceEvidenceChecklist>>,
        /// Aggregate evidence report for the recommended lane.
        pub evidence_report: DesktopAcceptanceEvidenceReport,
        /// Dry-run loop using the recommended lane's default evidence batches.
        pub loop_result: DesktopSurfaceAuditLoop,
        /// Builder-facing final dossier from the dry-run loop.
        pub final_dossier: DesktopSurfaceAuditDossier,
        /// Maximum steps used for the dry-run loop.
        pub max_steps: usize,
    }

    impl DesktopSurfaceAuditRecommendedLaneHandoff {
        /// Build a recommended-lane handoff package from a broad surface audit.
        pub fn from_audit(audit: &DesktopSurfaceAuditPlan, max_steps: usize) -> Self {
            let work_queue = audit.work_queue();
            let decision = work_queue.recommended_lane_decision();
            let batches = work_queue.recommended_lane_batches();
            let worker_packets = batches
                .iter()
                .map(DesktopSurfaceAuditWorkerPacket::from_batch)
                .collect();
            let evidence_batches = work_queue.recommended_lane_evidence_batches();
            let evidence_report = work_queue.recommended_lane_evidence_report();
            let loop_result = audit.run_execution_batch_loop(evidence_batches.clone(), max_steps);
            let final_dossier = loop_result.final_dossier();

            Self {
                decision,
                batches,
                worker_packets,
                evidence_batches,
                evidence_report,
                loop_result,
                final_dossier,
                max_steps,
            }
        }

        /// Returns true when a worker should be dispatched for this lane.
        pub fn should_dispatch(&self) -> bool {
            self.decision.should_dispatch
        }

        /// Returns true when this handoff targets native/platform work.
        pub fn targets_native_work(&self) -> bool {
            self.decision.targets_native_work()
        }

        /// Returns true when this handoff targets caveat or browser-island work.
        pub fn targets_caveat_briefing(&self) -> bool {
            self.decision.targets_caveat_briefing()
        }

        /// Number of executable batches in this handoff.
        pub fn batch_count(&self) -> usize {
            self.batches.len()
        }

        /// Number of worker-ready packets in this handoff.
        pub fn worker_packet_count(&self) -> usize {
            self.worker_packets.len()
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit recommended lane handoff: action {}, status {}, should dispatch {}, {} batches, {} worker packets, {} evidence bundles, {} evidence items, final action {}, can mark ready {}, targets native {}, targets caveats {}",
                self.decision.next_action.as_str(),
                self.decision.status.as_str(),
                self.should_dispatch(),
                self.batch_count(),
                self.worker_packet_count(),
                self.evidence_batches.len(),
                self.evidence_report.item_count(),
                self.final_dossier.final_action.as_str(),
                self.final_dossier.can_claim_parity,
                self.targets_native_work(),
                self.targets_caveat_briefing()
            )
        }
    }

    /// Worker-ready payload for one broad desktop surface audit execution batch.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditWorkerPacket {
        /// Count-level assignment for the worker.
        pub assignment: DesktopSurfaceAuditAssignment,
        /// Surface area to implement, verify, isolate, or brief.
        pub area: DesktopSurfaceArea,
        /// Evaluated area plan for this packet.
        pub area_plan: DesktopSurfaceAreaPlan,
        /// Recommended action for this packet.
        pub action: DesktopCapabilityActionKind,
        /// Feature-backed native/platform gaps for the worker.
        pub feature_gap_details: Vec<PlatformFeatureGap>,
        /// Builder-facing implementation brief for this surface area.
        pub implementation_brief: DesktopSurfaceImplementationBrief,
        /// Native Kael primitives or API families to consider first.
        pub native_primitives: Vec<String>,
        /// Primitive-level starter recipes owned by this surface area.
        pub starter_recipes: Vec<DesktopPrimitiveStarterRecipe>,
        /// Primitive-level scaffold hints owned by this surface area.
        pub scaffold_hints: Vec<DesktopPrimitiveScaffoldHint>,
        /// Minimal code-generation moves agents should try first.
        pub quick_start_steps: Vec<String>,
        /// Validation/setup checks agents should run before mutating native state.
        pub setup_checks: Vec<String>,
        /// Browser-shaped cases where a WebView island is justified.
        pub webview_when: Vec<String>,
        /// Product gaps that should be stated as roadmap instead of implied parity.
        pub roadmap_items: Vec<String>,
        /// Acceptance criteria owned by this surface area.
        pub acceptance_criteria: Vec<DesktopPrimitiveAcceptanceCriteria>,
        /// Missing-by-default evidence checklists for the worker.
        pub evidence_checklists: Vec<DesktopAcceptanceEvidenceChecklist>,
    }

    impl DesktopSurfaceAuditWorkerPacket {
        /// Build a worker-ready payload from an execution batch.
        pub fn from_batch(batch: &DesktopSurfaceAuditExecutionBatch) -> Self {
            let primitives = DesktopPrimitive::all()
                .into_iter()
                .filter(|primitive| primitive.surface_area() == batch.handoff.area)
                .collect::<Vec<_>>();
            let starter_recipes = primitives
                .iter()
                .copied()
                .map(DesktopPrimitive::starter_recipe)
                .collect::<Vec<_>>();
            let scaffold_hints = primitives
                .iter()
                .copied()
                .map(DesktopPrimitive::scaffold_hint)
                .collect::<Vec<_>>();
            let quick_start_steps = starter_recipes
                .iter()
                .flat_map(|recipe| recipe.quick_start_steps.iter().cloned())
                .collect::<Vec<_>>();
            let setup_checks = starter_recipes
                .iter()
                .flat_map(|recipe| recipe.setup_checks.iter().cloned())
                .collect::<Vec<_>>();

            Self {
                assignment: batch.assignment.clone(),
                area: batch.handoff.area,
                area_plan: batch.handoff.area_plan.clone(),
                action: batch.handoff.action,
                feature_gap_details: batch.handoff.feature_gap_details.clone(),
                implementation_brief: batch.handoff.implementation_brief.clone(),
                native_primitives: batch.handoff.native_primitives.clone(),
                starter_recipes,
                scaffold_hints,
                quick_start_steps,
                setup_checks,
                webview_when: batch.handoff.webview_when.clone(),
                roadmap_items: batch.handoff.roadmap_items.clone(),
                acceptance_criteria: batch.handoff.acceptance_criteria(),
                evidence_checklists: batch.evidence_checklists.clone(),
            }
        }

        /// Returns true when this packet targets native/platform work.
        pub fn targets_native_work(&self) -> bool {
            self.assignment.targets_native_work
        }

        /// Returns true when this packet blocks generation/readiness claims.
        pub fn blocks_generation(&self) -> bool {
            self.assignment.blocks_generation
        }

        /// Number of acceptance criteria attached to the worker packet.
        pub fn acceptance_criteria_count(&self) -> usize {
            self.acceptance_criteria.len()
        }

        /// Number of evidence checklists attached to the worker packet.
        pub fn evidence_checklist_count(&self) -> usize {
            self.evidence_checklists.len()
        }

        /// Number of primitive starter recipes attached to the worker packet.
        pub fn starter_recipe_count(&self) -> usize {
            self.starter_recipes.len()
        }

        /// Number of scaffold hints attached to the worker packet.
        pub fn scaffold_hint_count(&self) -> usize {
            self.scaffold_hints.len()
        }

        /// Reconstruct the broad-surface handoff represented by this worker packet.
        pub fn handoff(&self) -> DesktopSurfaceAuditHandoff {
            DesktopSurfaceAuditHandoff {
                category: self.assignment.category,
                action: self.action,
                area: self.area,
                area_plan: self.area_plan.clone(),
                implementation_brief: self.implementation_brief.clone(),
                feature_gap_details: self.feature_gap_details.clone(),
                native_primitives: self.native_primitives.clone(),
                webview_when: self.webview_when.clone(),
                roadmap_items: self.roadmap_items.clone(),
            }
        }

        /// Review supplied evidence checklists for this worker packet.
        pub fn review_evidence_checklists(
            &self,
            checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopSurfaceAuditEvidenceReview {
            self.handoff().review_evidence_checklists(checklists)
        }

        /// Review this packet with its missing-by-default evidence state.
        pub fn ready_evidence_review(&self) -> DesktopSurfaceAuditEvidenceReview {
            self.review_evidence_checklists(self.evidence_checklists.clone())
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit worker packet: action {}, area {}, route {}, focus {}, targets native {}, blocks generation {}, {} feature gaps, {} native primitives, {} starter recipes, {} scaffold hints, {} quick starts, {} setup checks, {} webview conditions, {} roadmap items, {} acceptance criteria, {} evidence checklists",
                self.action.as_str(),
                self.area.as_str(),
                self.implementation_brief.route.as_str(),
                self.assignment.focus.as_str(),
                self.targets_native_work(),
                self.blocks_generation(),
                self.feature_gap_details.len(),
                self.native_primitives.len(),
                self.starter_recipe_count(),
                self.scaffold_hint_count(),
                self.quick_start_steps.len(),
                self.setup_checks.len(),
                self.webview_when.len(),
                self.roadmap_items.len(),
                self.acceptance_criteria_count(),
                self.evidence_checklist_count()
            )
        }
    }

    /// Executable worker batch for one broad desktop surface audit handoff.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditExecutionBatch {
        /// Count-level assignment for the handoff.
        pub assignment: DesktopSurfaceAuditAssignment,
        /// Handoff to execute.
        pub handoff: DesktopSurfaceAuditHandoff,
        /// Missing-by-default evidence checklists for this handoff.
        pub evidence_checklists: Vec<DesktopAcceptanceEvidenceChecklist>,
    }

    impl DesktopSurfaceAuditExecutionBatch {
        /// Build an executable batch from a broad surface handoff.
        pub fn from_handoff(handoff: &DesktopSurfaceAuditHandoff) -> Self {
            Self {
                assignment: DesktopSurfaceAuditAssignment::from_handoff(handoff),
                handoff: handoff.clone(),
                evidence_checklists: handoff.evidence_checklists(),
            }
        }

        /// Returns true when this batch targets native/platform work.
        pub fn targets_native_work(&self) -> bool {
            self.assignment.targets_native_work
        }

        /// Returns true when this batch blocks generation/readiness claims.
        pub fn blocks_generation(&self) -> bool {
            self.assignment.blocks_generation
        }

        /// Number of evidence checklists in the batch.
        pub fn evidence_checklist_count(&self) -> usize {
            self.evidence_checklists.len()
        }

        /// Number of evidence items in the batch.
        pub fn evidence_item_count(&self) -> usize {
            self.evidence_checklists
                .iter()
                .map(DesktopAcceptanceEvidenceChecklist::item_count)
                .sum()
        }

        /// Worker-ready packet for this execution batch.
        pub fn worker_packet(&self) -> DesktopSurfaceAuditWorkerPacket {
            DesktopSurfaceAuditWorkerPacket::from_batch(self)
        }

        /// Complete the batch by reviewing supplied evidence checklists.
        pub fn complete_with_evidence_checklists(
            &self,
            checklists: impl IntoIterator<Item = DesktopAcceptanceEvidenceChecklist>,
        ) -> DesktopSurfaceAuditEvidenceReview {
            self.handoff.review_evidence_checklists(checklists)
        }

        /// Review the batch with its missing-by-default evidence state.
        pub fn ready_evidence_review(&self) -> DesktopSurfaceAuditEvidenceReview {
            self.handoff
                .review_evidence_checklists(self.evidence_checklists.clone())
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit execution batch: action {}, area {}, focus {}, targets native {}, blocks generation {}, {} evidence checklists, {} evidence items",
                self.assignment.action.as_str(),
                self.assignment.area.as_str(),
                self.assignment.focus.as_str(),
                self.targets_native_work(),
                self.blocks_generation(),
                self.evidence_checklist_count(),
                self.evidence_item_count()
            )
        }
    }

    /// Evidence review for an actionable broad desktop surface audit handoff.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditEvidenceReview {
        /// Handoff that was reviewed.
        pub handoff: DesktopSurfaceAuditHandoff,
        /// Evidence report that was reviewed.
        pub evidence: DesktopAcceptanceEvidenceReport,
        /// Recommended next action after reviewing evidence.
        pub next_action: DesktopGenerationNextAction,
        /// Whether this surface handoff can be treated as proven for its scope.
        pub can_close_handoff: bool,
    }

    impl DesktopSurfaceAuditEvidenceReview {
        /// Build a surface evidence review from a handoff and evidence report.
        pub fn from_handoff_and_evidence(
            handoff: &DesktopSurfaceAuditHandoff,
            evidence: DesktopAcceptanceEvidenceReport,
        ) -> Self {
            let next_action = if handoff.blocks_generation() {
                DesktopGenerationNextAction::ResolveGenerationBlockers
            } else if evidence.has_failures() {
                DesktopGenerationNextAction::FixFailedEvidence
            } else if handoff.targets_webview_island() || handoff.targets_roadmap() {
                DesktopGenerationNextAction::BriefCaveats
            } else if !evidence.is_complete() {
                DesktopGenerationNextAction::CollectReadyEvidence
            } else {
                DesktopGenerationNextAction::ClaimParity
            };
            let can_close_handoff = !handoff.blocks_generation()
                && !handoff.targets_webview_island()
                && !handoff.targets_roadmap()
                && evidence.can_claim_parity();

            Self {
                handoff: handoff.clone(),
                evidence,
                next_action,
                can_close_handoff,
            }
        }

        /// Returns true when the reviewed evidence failed.
        pub fn has_failures(&self) -> bool {
            self.evidence.has_failures()
        }

        /// Returns true when the reviewed evidence is still missing.
        pub fn has_missing_evidence(&self) -> bool {
            self.evidence.missing_count() > 0 || !self.evidence.is_complete()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit evidence review: action {}, area {}, next action {}, can close handoff {}, {} checklists, {} evidence items, {} passed, {} failed, {} missing",
                self.handoff.action.as_str(),
                self.handoff.area.as_str(),
                self.next_action.as_str(),
                self.can_close_handoff,
                self.evidence.checklist_count(),
                self.evidence.item_count(),
                self.evidence.passed_count(),
                self.evidence.failed_count(),
                self.evidence.missing_count()
            )
        }
    }

    /// Result of applying evidence to one broad desktop surface audit handoff.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditContinuation {
        /// Audit being continued.
        pub audit: DesktopSurfaceAuditPlan,
        /// Evidence review for the completed or still-open handoff.
        pub review: DesktopSurfaceAuditEvidenceReview,
        /// Next handoff to run, if broad surface work remains.
        pub next_handoff: Option<DesktopSurfaceAuditHandoff>,
        /// Remaining action items after the reviewed handoff is closed.
        pub remaining_action_count: usize,
    }

    impl DesktopSurfaceAuditContinuation {
        /// Build a continuation from a broad audit and a reviewed handoff.
        pub fn from_audit_and_review(
            audit: &DesktopSurfaceAuditPlan,
            review: DesktopSurfaceAuditEvidenceReview,
        ) -> Self {
            let closed_actions = if review.can_close_handoff {
                vec![(review.handoff.action, review.handoff.area)]
            } else {
                Vec::new()
            };
            Self::from_audit_review_and_closed_actions(audit, review, &closed_actions)
        }

        /// Build a continuation while preserving action pairs already closed by a
        /// longer broad-surface evidence loop.
        pub fn from_audit_review_and_closed_actions(
            audit: &DesktopSurfaceAuditPlan,
            review: DesktopSurfaceAuditEvidenceReview,
            closed_actions: &[(DesktopCapabilityActionKind, DesktopSurfaceArea)],
        ) -> Self {
            let remaining_actions = if review.can_close_handoff {
                audit
                    .action_items()
                    .into_iter()
                    .filter(|action| {
                        let Some(area) = action.area else {
                            return true;
                        };
                        !closed_actions
                            .iter()
                            .any(|(kind, closed_area)| *kind == action.kind && *closed_area == area)
                    })
                    .collect::<Vec<_>>()
            } else {
                vec![DesktopCapabilityActionItem::area(
                    review.handoff.action,
                    &review.handoff.area_plan,
                    &review.handoff.implementation_brief,
                )]
            };
            let next_handoff = remaining_actions.first().cloned().and_then(|action| {
                DesktopSurfaceAuditHandoff::from_audit_and_action(audit, action)
            });

            Self {
                audit: audit.clone(),
                review,
                next_handoff,
                remaining_action_count: remaining_actions.len(),
            }
        }

        /// Returns true when another broad-surface handoff is available.
        pub fn has_next_handoff(&self) -> bool {
            self.next_handoff.is_some()
        }

        /// Returns true when broad-surface work should continue.
        pub fn should_continue(&self) -> bool {
            self.has_next_handoff()
                && self.next_action() != DesktopGenerationNextAction::ClaimParity
        }

        /// Recommended next action for the broad-surface audit loop.
        pub fn next_action(&self) -> DesktopGenerationNextAction {
            if !self.review.can_close_handoff {
                return self.review.next_action;
            }

            self.next_handoff
                .as_ref()
                .map(|handoff| match handoff.action {
                    DesktopCapabilityActionKind::ResolveFeatureGaps => {
                        DesktopGenerationNextAction::ResolveGenerationBlockers
                    }
                    DesktopCapabilityActionKind::ApplyNativeGuardrails => {
                        DesktopGenerationNextAction::GenerateReadyNativeWork
                    }
                    DesktopCapabilityActionKind::IsolateWebViewIsland
                    | DesktopCapabilityActionKind::StateRoadmapGap => {
                        DesktopGenerationNextAction::BriefCaveats
                    }
                })
                .unwrap_or(DesktopGenerationNextAction::ClaimParity)
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit continuation: next action {}, should continue {}, has next handoff {}, can close reviewed handoff {}, {} remaining actions",
                self.next_action().as_str(),
                self.should_continue(),
                self.has_next_handoff(),
                self.review.can_close_handoff,
                self.remaining_action_count
            )
        }
    }

    /// Result of applying evidence to one broad desktop surface audit execution batch.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditBatchContinuation {
        /// Lower-level handoff continuation.
        pub continuation: DesktopSurfaceAuditContinuation,
        /// Next count-level assignment, if work remains.
        pub next_assignment: Option<DesktopSurfaceAuditAssignment>,
        /// Next executable batch, if work remains.
        pub next_batch: Option<DesktopSurfaceAuditExecutionBatch>,
    }

    impl DesktopSurfaceAuditBatchContinuation {
        /// Build a batch continuation from a lower-level handoff continuation.
        pub fn from_continuation(continuation: DesktopSurfaceAuditContinuation) -> Self {
            let next_assignment = continuation
                .next_handoff
                .as_ref()
                .map(DesktopSurfaceAuditAssignment::from_handoff);
            let next_batch = continuation
                .next_handoff
                .as_ref()
                .map(DesktopSurfaceAuditExecutionBatch::from_handoff);

            Self {
                continuation,
                next_assignment,
                next_batch,
            }
        }

        /// Recommended next action for the broad-surface audit loop.
        pub fn next_action(&self) -> DesktopGenerationNextAction {
            self.continuation.next_action()
        }

        /// Returns true when broad-surface work should continue.
        pub fn should_continue(&self) -> bool {
            self.continuation.should_continue()
        }

        /// Returns true when another execution batch is available.
        pub fn has_next_batch(&self) -> bool {
            self.next_batch.is_some()
        }

        /// Count of remaining broad-surface action items.
        pub fn remaining_action_count(&self) -> usize {
            self.continuation.remaining_action_count
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            let next_area = self
                .next_assignment
                .as_ref()
                .map(|assignment| assignment.area.as_str())
                .unwrap_or("none");
            let next_focus = self
                .next_assignment
                .as_ref()
                .map(|assignment| assignment.focus.as_str())
                .unwrap_or("none");

            format!(
                "desktop surface audit batch continuation: next action {}, should continue {}, has next batch {}, next area {}, next focus {}, can close reviewed handoff {}, {} remaining actions",
                self.next_action().as_str(),
                self.should_continue(),
                self.has_next_batch(),
                next_area,
                next_focus,
                self.continuation.review.can_close_handoff,
                self.remaining_action_count()
            )
        }
    }

    /// Result of running a bounded broad-surface audit evidence loop.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditLoop {
        /// Audit being looped over.
        pub audit: DesktopSurfaceAuditPlan,
        /// Continuations produced by each applied evidence batch.
        pub continuations: Vec<DesktopSurfaceAuditContinuation>,
        /// Final continuation, when at least one evidence batch ran.
        pub final_continuation: Option<DesktopSurfaceAuditContinuation>,
        /// Maximum steps allowed for this loop.
        pub max_steps: usize,
        /// Reason the loop stopped.
        pub stop_reason: DesktopCapabilityExecutionLoopStopReason,
    }

    impl DesktopSurfaceAuditLoop {
        /// Build a loop result from a broad audit and continuations.
        pub fn from_audit_and_continuations(
            audit: DesktopSurfaceAuditPlan,
            continuations: Vec<DesktopSurfaceAuditContinuation>,
            max_steps: usize,
            stop_reason: DesktopCapabilityExecutionLoopStopReason,
        ) -> Self {
            let final_continuation = continuations.last().cloned();

            Self {
                audit,
                continuations,
                final_continuation,
                max_steps,
                stop_reason,
            }
        }

        /// Number of continuations that ran.
        pub fn step_count(&self) -> usize {
            self.continuations.len()
        }

        /// Returns true when the loop stopped because it reached the step cap.
        pub fn reached_step_limit(&self) -> bool {
            self.stop_reason == DesktopCapabilityExecutionLoopStopReason::StepLimitReached
        }

        /// Recommended final action after the loop.
        pub fn final_action(&self) -> DesktopGenerationNextAction {
            self.final_continuation
                .as_ref()
                .map(DesktopSurfaceAuditContinuation::next_action)
                .unwrap_or_else(|| {
                    self.audit
                        .recommended_handoff()
                        .map(|handoff| match handoff.action {
                            DesktopCapabilityActionKind::ResolveFeatureGaps => {
                                DesktopGenerationNextAction::ResolveGenerationBlockers
                            }
                            DesktopCapabilityActionKind::ApplyNativeGuardrails => {
                                DesktopGenerationNextAction::GenerateReadyNativeWork
                            }
                            DesktopCapabilityActionKind::IsolateWebViewIsland
                            | DesktopCapabilityActionKind::StateRoadmapGap => {
                                DesktopGenerationNextAction::BriefCaveats
                            }
                        })
                        .unwrap_or(DesktopGenerationNextAction::ClaimParity)
                })
        }

        /// Final handoff after the loop, if more broad-surface work remains.
        pub fn final_handoff(&self) -> Option<&DesktopSurfaceAuditHandoff> {
            self.final_continuation
                .as_ref()
                .and_then(|continuation| continuation.next_handoff.as_ref())
        }

        /// Returns true when broad-surface work should continue.
        pub fn should_continue(&self) -> bool {
            self.final_continuation
                .as_ref()
                .map(DesktopSurfaceAuditContinuation::should_continue)
                .unwrap_or_else(|| self.audit.recommended_handoff().is_some())
        }

        /// Count-level final report for the loop.
        pub fn final_report(&self) -> DesktopSurfaceAuditLoopReport {
            DesktopSurfaceAuditLoopReport::from_loop(self)
        }

        /// Readiness decision for the broad-surface loop result.
        pub fn readiness_decision(&self) -> DesktopSurfaceAuditReadinessDecision {
            DesktopSurfaceAuditReadinessDecision::from_loop(self)
        }

        /// Serializable final handoff for the loop.
        pub fn final_loop_handoff(&self) -> DesktopSurfaceAuditLoopHandoff {
            DesktopSurfaceAuditLoopHandoff::from_loop(self)
        }

        /// Builder-facing final dossier for the loop.
        pub fn final_dossier(&self) -> DesktopSurfaceAuditDossier {
            DesktopSurfaceAuditDossier::from_loop(self)
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit loop: {} steps, max steps {}, stop reason {}, final action {}, reached limit {}, should continue {}, has final handoff {}",
                self.step_count(),
                self.max_steps,
                self.stop_reason.as_str(),
                self.final_action().as_str(),
                self.reached_step_limit(),
                self.should_continue(),
                self.final_handoff().is_some()
            )
        }
    }

    /// Count-level final report for a bounded broad-surface audit evidence loop.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditLoopReport {
        /// Number of continuations that ran.
        pub step_count: usize,
        /// Maximum steps allowed for this loop.
        pub max_steps: usize,
        /// Reason the loop stopped.
        pub stop_reason: DesktopCapabilityExecutionLoopStopReason,
        /// Recommended final action.
        pub final_action: DesktopGenerationNextAction,
        /// Whether broad-surface work should continue.
        pub should_continue: bool,
        /// Whether the loop reached the configured step cap.
        pub reached_step_limit: bool,
        /// Whether another handoff remains.
        pub has_final_handoff: bool,
        /// Failed evidence items in the final continuation.
        pub evidence_failed_count: usize,
        /// Missing evidence items in the final continuation.
        pub evidence_missing_count: usize,
    }

    impl DesktopSurfaceAuditLoopReport {
        /// Build a final report from a broad-surface audit loop.
        pub fn from_loop(loop_result: &DesktopSurfaceAuditLoop) -> Self {
            let evidence = loop_result
                .final_continuation
                .as_ref()
                .map(|continuation| &continuation.review.evidence);

            Self {
                step_count: loop_result.step_count(),
                max_steps: loop_result.max_steps,
                stop_reason: loop_result.stop_reason,
                final_action: loop_result.final_action(),
                should_continue: loop_result.should_continue(),
                reached_step_limit: loop_result.reached_step_limit(),
                has_final_handoff: loop_result.final_handoff().is_some(),
                evidence_failed_count: evidence
                    .map(DesktopAcceptanceEvidenceReport::failed_count)
                    .unwrap_or(0),
                evidence_missing_count: evidence
                    .map(DesktopAcceptanceEvidenceReport::missing_count)
                    .unwrap_or(0),
            }
        }

        /// Returns true when the final action targets native or platform work.
        pub fn targets_native_work(&self) -> bool {
            matches!(
                self.final_action,
                DesktopGenerationNextAction::ResolveGenerationBlockers
                    | DesktopGenerationNextAction::GenerateReadyNativeWork
                    | DesktopGenerationNextAction::FixFailedEvidence
                    | DesktopGenerationNextAction::CollectReadyEvidence
            )
        }

        /// Returns true when the final action targets browser-island or roadmap caveats.
        pub fn targets_caveat_briefing(&self) -> bool {
            self.final_action == DesktopGenerationNextAction::BriefCaveats
        }

        /// Returns true when the final action is a readiness claim.
        pub fn targets_parity_claim(&self) -> bool {
            self.final_action == DesktopGenerationNextAction::ClaimParity
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit loop report: {} steps, max steps {}, stop reason {}, final action {}, targets native {}, targets caveats {}, targets parity {}, should continue {}, reached limit {}, has final handoff {}, {} failed evidence, {} missing evidence",
                self.step_count,
                self.max_steps,
                self.stop_reason.as_str(),
                self.final_action.as_str(),
                self.targets_native_work(),
                self.targets_caveat_briefing(),
                self.targets_parity_claim(),
                self.should_continue,
                self.reached_step_limit,
                self.has_final_handoff,
                self.evidence_failed_count,
                self.evidence_missing_count
            )
        }
    }

    /// Readiness decision for a broad desktop surface audit loop.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditReadinessDecision {
        /// Final claim status for the broad surface scope.
        pub status: DesktopParityClaimStatus,
        /// Whether broad desktop surface readiness may be claimed now.
        pub can_claim_parity: bool,
        /// Whether more worker actions remain.
        pub should_continue: bool,
        /// Whether another handoff remains.
        pub has_final_handoff: bool,
        /// Whether feature-backed blocker actions remain.
        pub has_generation_blockers: bool,
        /// Whether caveat briefing remains.
        pub needs_briefing: bool,
        /// Failed evidence items in the final loop state.
        pub evidence_failed_count: usize,
        /// Missing evidence items in the final loop state.
        pub evidence_missing_count: usize,
        /// Number of loop steps that ran.
        pub step_count: usize,
        /// Reason the loop stopped.
        pub stop_reason: DesktopCapabilityExecutionLoopStopReason,
    }

    impl DesktopSurfaceAuditReadinessDecision {
        /// Build a broad-surface readiness decision from a loop result.
        pub fn from_loop(loop_result: &DesktopSurfaceAuditLoop) -> Self {
            let report = loop_result.final_report();
            let has_generation_blockers = loop_result
                .final_handoff()
                .map(DesktopSurfaceAuditHandoff::blocks_generation)
                .unwrap_or_else(|| !loop_result.audit.blocking_action_items().is_empty());
            let needs_briefing = report.targets_caveat_briefing()
                || loop_result
                    .final_handoff()
                    .map(|handoff| handoff.targets_webview_island() || handoff.targets_roadmap())
                    .unwrap_or(false);
            let status = if has_generation_blockers
                || report.final_action == DesktopGenerationNextAction::ResolveGenerationBlockers
            {
                DesktopParityClaimStatus::BlockedByGeneration
            } else if report.evidence_failed_count > 0
                || report.final_action == DesktopGenerationNextAction::FixFailedEvidence
            {
                DesktopParityClaimStatus::BlockedByFailedEvidence
            } else if report.evidence_missing_count > 0
                || report.final_action == DesktopGenerationNextAction::CollectReadyEvidence
            {
                DesktopParityClaimStatus::BlockedByMissingEvidence
            } else if needs_briefing {
                DesktopParityClaimStatus::RequiresBriefing
            } else if !report.should_continue && !report.has_final_handoff {
                DesktopParityClaimStatus::Allowed
            } else {
                DesktopParityClaimStatus::BlockedByMissingEvidence
            };

            Self {
                status,
                can_claim_parity: status == DesktopParityClaimStatus::Allowed,
                should_continue: report.should_continue,
                has_final_handoff: report.has_final_handoff,
                has_generation_blockers,
                needs_briefing,
                evidence_failed_count: report.evidence_failed_count,
                evidence_missing_count: report.evidence_missing_count,
                step_count: report.step_count,
                stop_reason: report.stop_reason,
            }
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit readiness decision: status {}, can mark ready {}, should continue {}, has final handoff {}, generation blockers {}, needs briefing {}, {} failed evidence, {} missing evidence, {} steps, stop reason {}",
                self.status.as_str(),
                self.can_claim_parity,
                self.should_continue,
                self.has_final_handoff,
                self.has_generation_blockers,
                self.needs_briefing,
                self.evidence_failed_count,
                self.evidence_missing_count,
                self.step_count,
                self.stop_reason.as_str()
            )
        }
    }

    /// Serializable final handoff for a bounded broad-surface audit evidence loop.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditLoopHandoff {
        /// Count-level final report.
        pub report: DesktopSurfaceAuditLoopReport,
        /// Readiness decision for the loop result.
        pub readiness: DesktopSurfaceAuditReadinessDecision,
        /// Next broad-surface handoff, if work remains.
        pub next_handoff: Option<DesktopSurfaceAuditHandoff>,
        /// Whether a next handoff exists.
        pub has_next_handoff: bool,
        /// Whether a scheduler should continue with the next handoff.
        pub should_continue: bool,
    }

    impl DesktopSurfaceAuditLoopHandoff {
        /// Build a final handoff from a bounded broad-surface loop.
        pub fn from_loop(loop_result: &DesktopSurfaceAuditLoop) -> Self {
            let report = loop_result.final_report();
            let readiness = loop_result.readiness_decision();
            let next_handoff = loop_result.final_handoff().cloned();
            let has_next_handoff = next_handoff.is_some();

            Self {
                should_continue: readiness.should_continue && has_next_handoff,
                report,
                readiness,
                next_handoff,
                has_next_handoff,
            }
        }

        /// Returns true when the final action targets native or platform work.
        pub fn targets_native_work(&self) -> bool {
            self.report.targets_native_work()
        }

        /// Returns true when the final action targets caveat briefing.
        pub fn targets_caveat_briefing(&self) -> bool {
            self.report.targets_caveat_briefing()
        }

        /// Returns true when the final action is a readiness claim.
        pub fn targets_parity_claim(&self) -> bool {
            self.report.targets_parity_claim()
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            let next_area = self
                .next_handoff
                .as_ref()
                .map(|handoff| handoff.area.as_str())
                .unwrap_or("none");

            format!(
                "desktop surface audit loop handoff: stop reason {}, final action {}, readiness {}, next area {}, targets native {}, targets caveats {}, targets parity {}, should continue {}, has next handoff {}",
                self.report.stop_reason.as_str(),
                self.report.final_action.as_str(),
                self.readiness.status.as_str(),
                next_area,
                self.targets_native_work(),
                self.targets_caveat_briefing(),
                self.targets_parity_claim(),
                self.should_continue,
                self.has_next_handoff
            )
        }
    }

    /// Builder-facing count-level dossier for a broad desktop surface audit loop.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopSurfaceAuditDossier {
        /// Final readiness decision.
        pub readiness: DesktopSurfaceAuditReadinessDecision,
        /// Count-level loop report.
        pub report: DesktopSurfaceAuditLoopReport,
        /// Final recommended action.
        pub final_action: DesktopGenerationNextAction,
        /// Next broad-surface area, if work remains.
        pub next_area: Option<DesktopSurfaceArea>,
        /// Next broad-surface action, if work remains.
        pub next_action: Option<DesktopCapabilityActionKind>,
        /// Whether a scheduler should continue.
        pub should_continue: bool,
        /// Whether broad desktop readiness can be claimed now.
        pub can_claim_parity: bool,
        /// Whether final work targets native/platform implementation.
        pub targets_native_work: bool,
        /// Whether final work targets WebView/roadmap caveat briefing.
        pub targets_caveat_briefing: bool,
        /// Whether final work targets a readiness claim.
        pub targets_parity_claim: bool,
        /// Number of audited surface areas.
        pub audited_area_count: usize,
        /// Number of feature gaps across the broad audit.
        pub feature_gap_count: usize,
    }

    impl DesktopSurfaceAuditDossier {
        /// Build a builder-facing dossier from a broad-surface loop result.
        pub fn from_loop(loop_result: &DesktopSurfaceAuditLoop) -> Self {
            let report = loop_result.final_report();
            let readiness = loop_result.readiness_decision();
            let final_handoff = loop_result.final_handoff();

            Self {
                final_action: report.final_action,
                next_area: final_handoff.map(|handoff| handoff.area),
                next_action: final_handoff.map(|handoff| handoff.action),
                should_continue: readiness.should_continue,
                can_claim_parity: readiness.can_claim_parity,
                targets_native_work: report.targets_native_work(),
                targets_caveat_briefing: report.targets_caveat_briefing(),
                targets_parity_claim: report.targets_parity_claim(),
                audited_area_count: loop_result.audit.area_count(),
                feature_gap_count: loop_result.audit.feature_gap_count(),
                readiness,
                report,
            }
        }

        /// Returns true when another surface handoff remains.
        pub fn has_next_area(&self) -> bool {
            self.next_area.is_some()
        }

        /// Content-safe summary for logs, dashboards, and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop surface audit dossier: status {}, can mark ready {}, final action {}, next area {}, next action {}, should continue {}, targets native {}, targets caveats {}, targets parity {}, {} audited areas, {} feature gaps, {} failed evidence, {} missing evidence",
                self.readiness.status.as_str(),
                self.can_claim_parity,
                self.final_action.as_str(),
                self.next_area
                    .map(DesktopSurfaceArea::as_str)
                    .unwrap_or("none"),
                self.next_action
                    .map(DesktopCapabilityActionKind::as_str)
                    .unwrap_or("none"),
                self.should_continue,
                self.targets_native_work,
                self.targets_caveat_briefing,
                self.targets_parity_claim,
                self.audited_area_count,
                self.feature_gap_count,
                self.report.evidence_failed_count,
                self.report.evidence_missing_count
            )
        }
    }

    /// Combined app-category, surface-area, and implementation-brief plan for an
    /// Desktop capability audit.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityPlan {
        /// App category being planned.
        pub category: DesktopAppCategory,
        /// App-category capability recipe evaluation.
        pub recipe: AppParityRecipePlan,
        /// Broad desktop surface audit.
        pub surface_audit: DesktopSurfaceAuditPlan,
        /// Builder-facing implementation briefs for audited surface areas.
        pub implementation_briefs: Vec<DesktopSurfaceImplementationBrief>,
    }

    /// Content-safe pre-generation brief derived from a desktop capability plan.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityBrief {
        /// App category being planned.
        pub category: DesktopAppCategory,
        /// Overall readiness.
        pub readiness: DesktopCapabilityReadiness,
        /// Whether code generation can proceed without a blocking readiness failure.
        pub can_generate: bool,
        /// Whether caveats should be stated before implementation.
        pub needs_briefing: bool,
        /// Number of app-category recipe surfaces.
        pub recipe_surface_count: usize,
        /// Number of audited desktop surface areas.
        pub audited_area_count: usize,
        /// Number of implementation briefs available.
        pub implementation_brief_count: usize,
        /// Number of prioritized action items.
        pub action_item_count: usize,
        /// Number of blocking action items.
        pub blocking_action_count: usize,
        /// Total feature gaps across the plan.
        pub feature_gap_count: usize,
        /// Remediation count summary across blocking feature gaps.
        pub remediation: PlatformFeatureGapRemediationSummary,
        /// Whether WebView compatibility islands are present.
        pub has_webview_fallbacks: bool,
        /// Whether roadmap gaps are present.
        pub has_roadmap_gaps: bool,
    }

    impl DesktopCapabilityBrief {
        /// Create a content-safe brief from a capability plan.
        pub fn from_plan(plan: &DesktopCapabilityPlan) -> Self {
            Self {
                category: plan.category,
                readiness: plan.readiness(),
                can_generate: plan.can_generate(),
                needs_briefing: plan.needs_briefing(),
                recipe_surface_count: plan.recipe.surface_count(),
                audited_area_count: plan.surface_audit.area_count(),
                implementation_brief_count: plan.implementation_brief_count(),
                action_item_count: plan.action_item_count(),
                blocking_action_count: plan.blocking_action_items().len(),
                feature_gap_count: plan.feature_gap_count(),
                remediation: plan.remediation_summary(),
                has_webview_fallbacks: plan.has_webview_fallbacks(),
                has_roadmap_gaps: plan.has_roadmap_gaps(),
            }
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            format!(
                "desktop capability brief: category {}, readiness {}, can generate {}, needs briefing {}, {} recipe surfaces, {} audited areas, {} implementation briefs, {} action items, {} blocking actions, {} feature gaps, {} remediation entries, webview {}, roadmap {}",
                self.category.as_str(),
                self.readiness.as_str(),
                self.can_generate,
                self.needs_briefing,
                self.recipe_surface_count,
                self.audited_area_count,
                self.implementation_brief_count,
                self.action_item_count,
                self.blocking_action_count,
                self.feature_gap_count,
                self.remediation.total(),
                self.has_webview_fallbacks,
                self.has_roadmap_gaps
            )
        }
    }

    /// Overall readiness for using Kael as the capability path for a desktop app
    /// category.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum DesktopCapabilityReadiness {
        /// The plan can proceed on native surfaces without feature gaps.
        NativeReady,
        /// The plan can proceed, but setup, permission, platform, or fallback
        /// guardrails should be exposed.
        NativeWithGuardrails,
        /// The plan intentionally needs one or more WebView compatibility islands.
        WebViewIsland,
        /// The plan depends on roadmap work and should not imply full readiness.
        RoadmapGap,
        /// One or more required or selected feature-backed surfaces are unavailable.
        BlockedByFeatureGaps,
    }

    impl DesktopCapabilityReadiness {
        /// Stable text label for diagnostics and UI.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::NativeReady => "native-ready",
                Self::NativeWithGuardrails => "native-with-guardrails",
                Self::WebViewIsland => "webview-island",
                Self::RoadmapGap => "roadmap-gap",
                Self::BlockedByFeatureGaps => "blocked-by-feature-gaps",
            }
        }

        /// Returns true when code generation should proceed without a blocking
        /// readiness failure.
        pub fn can_generate(self) -> bool {
            !matches!(self, Self::BlockedByFeatureGaps)
        }

        /// Returns true when the app brief should call out caveats before
        /// implementation.
        pub fn needs_briefing(self) -> bool {
            !matches!(self, Self::NativeReady)
        }
    }

    /// One prioritized action an agent or builder should take before generating or
    /// implementing a desktop capability app.
    #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
    pub enum DesktopCapabilityActionKind {
        /// Resolve unavailable feature-backed surfaces before marking readiness.
        ResolveFeatureGaps,
        /// State a roadmap gap explicitly in the app brief.
        StateRoadmapGap,
        /// Keep a browser-shaped dependency in an isolated WebView island.
        IsolateWebViewIsland,
        /// Proceed with native APIs while exposing platform/setup caveats.
        ApplyNativeGuardrails,
    }

    impl DesktopCapabilityActionKind {
        /// Stable text label for diagnostics and UI.
        pub fn as_str(self) -> &'static str {
            match self {
                Self::ResolveFeatureGaps => "resolve-feature-gaps",
                Self::StateRoadmapGap => "state-roadmap-gap",
                Self::IsolateWebViewIsland => "isolate-webview-island",
                Self::ApplyNativeGuardrails => "apply-native-guardrails",
            }
        }

        /// Stable sort priority. Lower values should be handled first.
        pub fn priority(self) -> u8 {
            match self {
                Self::ResolveFeatureGaps => 0,
                Self::StateRoadmapGap => 1,
                Self::IsolateWebViewIsland => 2,
                Self::ApplyNativeGuardrails => 3,
            }
        }
    }

    /// Prioritized action item derived from a desktop capability plan.
    #[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
    pub struct DesktopCapabilityActionItem {
        /// Action kind.
        pub kind: DesktopCapabilityActionKind,
        /// Optional desktop surface area this action applies to.
        pub area: Option<DesktopSurfaceArea>,
        /// Unavailable feature-backed checks attached to this action.
        pub feature_gaps: Vec<PlatformFeature>,
        /// Unavailable feature-backed checks with support levels.
        pub feature_gap_details: Vec<PlatformFeatureGap>,
        /// Number of suggested native primitives attached to this action.
        pub native_primitive_count: usize,
        /// Number of WebView conditions attached to this action.
        pub webview_condition_count: usize,
        /// Number of roadmap items attached to this action.
        pub roadmap_item_count: usize,
    }

    impl DesktopCapabilityActionItem {
        /// Create a category-level action item.
        pub fn category(
            kind: DesktopCapabilityActionKind,
            feature_gaps: Vec<PlatformFeature>,
            feature_gap_details: Vec<PlatformFeatureGap>,
        ) -> Self {
            Self {
                kind,
                area: None,
                feature_gaps,
                feature_gap_details,
                native_primitive_count: 0,
                webview_condition_count: 0,
                roadmap_item_count: 0,
            }
        }

        /// Create a surface-area action item.
        pub fn area(
            kind: DesktopCapabilityActionKind,
            area: &DesktopSurfaceAreaPlan,
            brief: &DesktopSurfaceImplementationBrief,
        ) -> Self {
            Self {
                kind,
                area: Some(area.area),
                feature_gaps: area.feature_gaps.clone(),
                feature_gap_details: area.feature_gap_details.clone(),
                native_primitive_count: brief.native_primitives.len(),
                webview_condition_count: brief.webview_when.len(),
                roadmap_item_count: brief.roadmap_items.len(),
            }
        }

        /// Number of unavailable feature-backed checks attached to this action.
        pub fn feature_gap_count(&self) -> usize {
            self.feature_gaps.len()
        }

        /// Number of feature gap detail records attached to this action.
        pub fn feature_gap_detail_count(&self) -> usize {
            self.feature_gap_details.len()
        }

        /// Number of feature gaps for a remediation class.
        pub fn remediation_count(&self, remediation: PlatformFeatureGapRemediation) -> usize {
            self.feature_gap_details
                .iter()
                .filter(|gap| gap.remediation() == remediation)
                .count()
        }

        /// Count summary of remediation classes in this action.
        pub fn remediation_summary(&self) -> PlatformFeatureGapRemediationSummary {
            let mut summary = PlatformFeatureGapRemediationSummary::default();
            for gap in &self.feature_gap_details {
                summary.add(gap.remediation());
            }
            summary
        }

        /// Returns true when any gap needs initialization, permission, or metadata.
        pub fn needs_initialization_or_permission(&self) -> bool {
            self.remediation_count(PlatformFeatureGapRemediation::InitializeOrRequestPermission) > 0
        }

        /// Returns true when any gap needs policy/configuration changes.
        pub fn needs_policy_change(&self) -> bool {
            self.remediation_count(PlatformFeatureGapRemediation::ChangePolicyOrConfiguration) > 0
        }

        /// Returns true when any gap needs a fallback, scope reduction, or roadmap callout.
        pub fn needs_fallback_or_roadmap(&self) -> bool {
            self.remediation_count(PlatformFeatureGapRemediation::UseFallbackOrRoadmap) > 0
        }

        /// Stable sort priority. Lower values should be handled first.
        pub fn priority(&self) -> u8 {
            self.kind.priority()
        }

        /// Returns true when this action blocks code generation.
        pub fn blocks_generation(&self) -> bool {
            self.kind == DesktopCapabilityActionKind::ResolveFeatureGaps
                && self.feature_gap_count() > 0
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            let area = self
                .area
                .map(DesktopSurfaceArea::as_str)
                .unwrap_or("category recipe");

            format!(
                "desktop capability action: kind {}, area {}, {} feature gaps, {} native primitives, {} webview conditions, {} roadmap items",
                self.kind.as_str(),
                area,
                self.feature_gap_count(),
                self.native_primitive_count,
                self.webview_condition_count,
                self.roadmap_item_count
            )
        }
    }

    impl DesktopCapabilityPlan {
        /// Build a combined capability plan for an app category.
        pub fn for_category(category: DesktopAppCategory, report: &CapabilityReport) -> Self {
            let recipe = category.recipe().evaluate(report);
            let surface_audit = DesktopSurfaceAuditPlan::for_category(category, report);
            let implementation_briefs = surface_audit
                .areas
                .iter()
                .map(DesktopSurfaceAreaPlan::implementation_brief)
                .collect();

            Self {
                category,
                recipe,
                surface_audit,
                implementation_briefs,
            }
        }

        /// Total feature gaps across the recipe and broad surface audit.
        pub fn feature_gap_count(&self) -> usize {
            self.recipe.feature_gaps.len() + self.surface_audit.feature_gap_count()
        }

        /// Returns true when any recipe or surface feature gap remains.
        pub fn has_feature_gaps(&self) -> bool {
            self.feature_gap_count() > 0
        }

        /// Returns true when both the recipe and broad surface audit have no
        /// feature-backed gaps.
        pub fn feature_checks_passed(&self) -> bool {
            !self.has_feature_gaps()
        }

        /// Returns true when either the category recipe or broad surface audit
        /// contains a WebView compatibility island.
        pub fn has_webview_fallbacks(&self) -> bool {
            self.recipe.has_webview_fallbacks() || self.surface_audit.has_webview_fallbacks()
        }

        /// Returns true when either the category recipe or broad surface audit
        /// contains a roadmap gap.
        pub fn has_roadmap_gaps(&self) -> bool {
            self.recipe.has_roadmap_surfaces() || self.surface_audit.has_roadmap_gaps()
        }

        /// Number of implementation briefs attached to this plan.
        pub fn implementation_brief_count(&self) -> usize {
            self.implementation_briefs.len()
        }

        /// Implementation briefs with a given route.
        pub fn implementation_briefs_for_route(
            &self,
            route: AppParityRoute,
        ) -> Vec<&DesktopSurfaceImplementationBrief> {
            self.implementation_briefs
                .iter()
                .filter(|brief| brief.route == route)
                .collect()
        }

        /// Implementation briefs that include roadmap items.
        pub fn implementation_briefs_with_roadmap_items(
            &self,
        ) -> Vec<&DesktopSurfaceImplementationBrief> {
            self.implementation_briefs
                .iter()
                .filter(|brief| brief.has_roadmap_items())
                .collect()
        }

        /// Highest-priority readiness state for this capability plan.
        pub fn readiness(&self) -> DesktopCapabilityReadiness {
            if self.has_feature_gaps() {
                DesktopCapabilityReadiness::BlockedByFeatureGaps
            } else if self.has_roadmap_gaps() {
                DesktopCapabilityReadiness::RoadmapGap
            } else if self.has_webview_fallbacks() {
                DesktopCapabilityReadiness::WebViewIsland
            } else if self
                .surface_audit
                .route_count(AppParityRoute::NativeWithGuardrails)
                > 0
            {
                DesktopCapabilityReadiness::NativeWithGuardrails
            } else {
                DesktopCapabilityReadiness::NativeReady
            }
        }

        /// Returns true when the plan should continue to implementation.
        pub fn can_generate(&self) -> bool {
            self.readiness().can_generate()
        }

        /// Returns true when the builder should state caveats before generating the app.
        pub fn needs_briefing(&self) -> bool {
            self.readiness().needs_briefing()
        }

        /// Prioritized actions an agent or builder should handle before claiming
        /// Desktop capability readiness.
        pub fn action_items(&self) -> Vec<DesktopCapabilityActionItem> {
            let mut items = Vec::new();

            if !self.recipe.feature_gaps.is_empty() {
                items.push(DesktopCapabilityActionItem::category(
                    DesktopCapabilityActionKind::ResolveFeatureGaps,
                    self.recipe.feature_gaps.clone(),
                    self.recipe.feature_gap_details.clone(),
                ));
            }

            if self.recipe.has_roadmap_surfaces() {
                items.push(DesktopCapabilityActionItem::category(
                    DesktopCapabilityActionKind::StateRoadmapGap,
                    Vec::new(),
                    Vec::new(),
                ));
            }

            if self.recipe.has_webview_fallbacks() {
                items.push(DesktopCapabilityActionItem::category(
                    DesktopCapabilityActionKind::IsolateWebViewIsland,
                    Vec::new(),
                    Vec::new(),
                ));
            }

            for area in &self.surface_audit.areas {
                let brief = area.implementation_brief();
                if !area.feature_checks_passed() {
                    items.push(DesktopCapabilityActionItem::area(
                        DesktopCapabilityActionKind::ResolveFeatureGaps,
                        area,
                        &brief,
                    ));
                }

                if area.is_roadmap() {
                    items.push(DesktopCapabilityActionItem::area(
                        DesktopCapabilityActionKind::StateRoadmapGap,
                        area,
                        &brief,
                    ));
                } else if area.is_webview_fallback() {
                    items.push(DesktopCapabilityActionItem::area(
                        DesktopCapabilityActionKind::IsolateWebViewIsland,
                        area,
                        &brief,
                    ));
                } else if area.needs_guardrails() {
                    items.push(DesktopCapabilityActionItem::area(
                        DesktopCapabilityActionKind::ApplyNativeGuardrails,
                        area,
                        &brief,
                    ));
                }
            }

            items.sort_by_key(|item| item.priority());
            items
        }

        /// Number of prioritized action items.
        pub fn action_item_count(&self) -> usize {
            self.action_items().len()
        }

        /// Action items that block generation.
        pub fn blocking_action_items(&self) -> Vec<DesktopCapabilityActionItem> {
            self.action_items()
                .into_iter()
                .filter(DesktopCapabilityActionItem::blocks_generation)
                .collect()
        }

        /// Count summary of remediation classes across all action items.
        pub fn remediation_summary(&self) -> PlatformFeatureGapRemediationSummary {
            let mut summary = PlatformFeatureGapRemediationSummary::default();
            for action in self.action_items() {
                if action.kind != DesktopCapabilityActionKind::ResolveFeatureGaps {
                    continue;
                }
                for gap in action.feature_gap_details {
                    summary.add(gap.remediation());
                }
            }
            summary
        }

        /// Content-safe pre-generation brief for agents and setup screens.
        pub fn brief(&self) -> DesktopCapabilityBrief {
            DesktopCapabilityBrief::from_plan(self)
        }

        /// Content-safe summary for logs and agents.
        pub fn to_text(&self) -> String {
            let remediation = self.remediation_summary();
            format!(
                "desktop capability plan: category {}, readiness {}, {} recipe surfaces, {} audited areas, {} implementation briefs, {} action items, {} feature gaps, {} remediation entries, webview {}, roadmap {}",
                self.category.as_str(),
                self.readiness().as_str(),
                self.recipe.surface_count(),
                self.surface_audit.area_count(),
                self.implementation_brief_count(),
                self.action_item_count(),
                self.feature_gap_count(),
                remediation.total(),
                self.has_webview_fallbacks(),
                self.has_roadmap_gaps()
            )
        }
    }

