    /// Evaluate arbitrary desktop surface areas against a capability report.
    pub fn desktop_surface_audit(
        category: Option<DesktopAppCategory>,
        areas: impl IntoIterator<Item = DesktopSurfaceArea>,
        report: &CapabilityReport,
    ) -> DesktopSurfaceAuditPlan {
        DesktopSurfaceAuditPlan {
            category,
            areas: areas
                .into_iter()
                .map(|area| DesktopSurfaceAreaPlan::evaluate(area, report))
                .collect(),
        }
    }

    /// Evaluate one Desktop primitive/API family against Kael's native,
    /// guarded-native, WebView-island, and roadmap surfaces.
    pub fn desktop_primitive_bridge(
        primitive: DesktopPrimitive,
        report: &CapabilityReport,
    ) -> DesktopPrimitiveBridge {
        let area = primitive.surface_area();
        let brief = area.implementation_brief();
        let checked_features = primitive.checked_features();
        let feature_gap_details = checked_features
            .iter()
            .copied()
            .filter_map(|feature| {
                let support = report.support_for(feature);
                (!support.is_available()).then_some(PlatformFeatureGap::new(feature, support))
            })
            .collect();

        DesktopPrimitiveBridge {
            primitive,
            area,
            route: brief.route,
            checked_features,
            feature_gap_details,
            native_primitive_count: brief.native_primitives.len(),
            webview_condition_count: brief.webview_when.len(),
            roadmap_item_count: brief.roadmap_items.len(),
        }
    }

