    #[test]
    fn test_capability_report_groups_fallback_risks() {
        let report = CapabilityReport {
            os: "test".into(),
            os_version: "1".into(),
            features: vec![
                FeatureReport {
                    feature: PlatformFeature::WebView,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::FileExportDrag,
                    support: SupportLevel::Partial,
                    note: Some("descriptor only".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::Geolocation,
                    support: SupportLevel::RequiresInit,
                    note: Some("permission required".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::FileBookmarks,
                    support: SupportLevel::Unsupported,
                    note: None,
                },
            ],
        };

        assert_eq!(report.full_features(), vec![PlatformFeature::WebView]);
        assert_eq!(
            report.available_features(),
            vec![
                PlatformFeature::WebView,
                PlatformFeature::FileExportDrag,
                PlatformFeature::Geolocation,
            ]
        );
        assert_eq!(
            report.partial_features(),
            vec![PlatformFeature::FileExportDrag]
        );
        assert_eq!(
            report.requires_init_features(),
            vec![PlatformFeature::Geolocation]
        );
        assert_eq!(
            report.unsupported_features(),
            vec![PlatformFeature::FileBookmarks]
        );
        assert_eq!(report.feature_count(), 4);
        assert_eq!(report.full_feature_count(), 1);
        assert_eq!(report.available_feature_count(), 3);
        assert_eq!(report.partial_feature_count(), 1);
        assert_eq!(report.requires_init_feature_count(), 1);
        assert_eq!(report.unsupported_feature_count(), 1);
        assert_eq!(report.fallback_risk_count(), 3);
        assert!(report.has_fallback_risks());
        assert_eq!(report.fallback_risk_features().len(), 3);

        let coverage = report.coverage_summary();
        assert_eq!(
            coverage,
            CapabilityCoverageSummary {
                total: 4,
                full: 1,
                available: 3,
                partial: 1,
                requires_init: 1,
                unsupported: 1,
                fallback_risk: 3,
            }
        );
        assert!(!coverage.is_all_full());
        assert!(coverage.has_unsupported());
        assert!(coverage.has_fallback_risks());
        assert_eq!(
            coverage.to_text(),
            "4 features: 1 full, 3 available, 1 partial, 1 requires init, 1 unsupported, 3 fallback risks"
        );

        let summary = report.fallback_risk_summary().unwrap();
        assert!(summary.contains("FileExportDrag"));
        assert!(summary.contains("descriptor only"));
        assert!(summary.contains("Geolocation"));
        assert!(summary.contains("RequiresInit"));
        assert!(summary.contains("FileBookmarks"));
    }

    #[test]
    fn test_device_access_execution_plan_maps_support_to_next_actions() {
        let report = CapabilityReport {
            os: "test".into(),
            os_version: "1".into(),
            features: vec![
                FeatureReport {
                    feature: PlatformFeature::UsbDevices,
                    support: SupportLevel::Unsupported,
                    note: Some("native USB backend missing for private-device".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::HidDevices,
                    support: SupportLevel::Partial,
                    note: Some("descriptor-only HID backend".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::SerialPorts,
                    support: SupportLevel::Disabled,
                    note: Some("blocked by local policy".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::BluetoothDevices,
                    support: SupportLevel::RequiresInit,
                    note: Some("usage description and permission required".into()),
                },
            ],
        };

        let usb = DeviceAccessRequest::usb("Read private USB scale.")
            .vendor_product(0x1234, 0xabcd)
            .build_checked()
            .unwrap();
        let usb_plan = report.device_access_plan(&usb);
        assert_eq!(usb_plan.kind(), DeviceAccessKind::Usb);
        assert_eq!(usb_plan.feature(), PlatformFeature::UsbDevices);
        assert_eq!(usb_plan.support(), SupportLevel::Unsupported);
        assert_eq!(
            usb_plan.next_action(),
            DeviceAccessPlanAction::BuildNativeBackend
        );
        assert!(usb_plan.requires_native_backend_work());
        assert!(usb_plan.has_vendor_id());
        assert!(usb_plan.has_product_id());
        assert!(usb_plan.requires_privacy_permission());
        let usb_text = usb_plan.to_text();
        assert!(usb_text.contains("device access plan usb"));
        assert!(usb_text.contains("next action build native backend"));
        assert!(!usb_text.contains("private"));
        assert!(!usb_text.contains("1234"));
        assert!(!usb_text.contains("abcd"));

        let hid_plan = report
            .device_access_plan_checked(
                DeviceAccessRequest::hid("Read private HID console.").vendor_id(0x1234),
            )
            .unwrap();
        assert_eq!(
            hid_plan.next_action(),
            DeviceAccessPlanAction::UseGuardedNativeDescriptor
        );
        assert!(hid_plan.requires_guarded_native_descriptor());
        assert!(hid_plan.has_vendor_id());
        assert!(!hid_plan.has_product_id());

        let serial_plan = report
            .device_access_plan_checked(
                DeviceAccessRequest::serial("Open private serial controller.")
                    .port_name_hint("tty.usbserial"),
            )
            .unwrap();
        assert_eq!(
            serial_plan.next_action(),
            DeviceAccessPlanAction::ChangePolicyOrConfiguration
        );
        assert!(serial_plan.requires_policy_change());
        assert!(serial_plan.has_port_name_hint());
        assert!(!serial_plan.to_text().contains("tty.usbserial"));

        let bluetooth_plan = report
            .device_access_plan_checked(
                DeviceAccessRequest::bluetooth("Pair private strap.")
                    .service_uuid("180D")
                    .allow_background(),
            )
            .unwrap();
        assert_eq!(
            bluetooth_plan.next_action(),
            DeviceAccessPlanAction::RequestPermissionOrMetadata
        );
        assert!(bluetooth_plan.requires_permission_or_metadata());
        assert!(bluetooth_plan.has_service_uuid());
        assert!(bluetooth_plan.allows_background());
        assert!(!bluetooth_plan.to_text().contains("180D"));
    }

