    #[test]
    fn test_capability_check_separates_required_and_preferred() {
        let report = CapabilityReport {
            os: "test".into(),
            os_version: "1".into(),
            features: vec![
                FeatureReport {
                    feature: PlatformFeature::WebView,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::GlobalHotkeys,
                    support: SupportLevel::Partial,
                    note: Some("interactive consent required".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::FileBookmarks,
                    support: SupportLevel::Unsupported,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::TouchInput,
                    support: SupportLevel::Partial,
                    note: Some("raw contacts require fallback UI".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::SpellChecking,
                    support: SupportLevel::Partial,
                    note: Some("descriptor only".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::Geolocation,
                    support: SupportLevel::RequiresInit,
                    note: Some("permission required".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::FileExportDrag,
                    support: SupportLevel::Partial,
                    note: Some("descriptor only".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::AppWindowCapture,
                    support: SupportLevel::Partial,
                    note: Some("descriptor only".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::UsbDevices,
                    support: SupportLevel::Partial,
                    note: Some("descriptor only".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::BluetoothDevices,
                    support: SupportLevel::Partial,
                    note: Some("descriptor only".into()),
                },
            ],
        };

        let result = CapabilityCheck::new()
            .require(PlatformFeature::WebView)
            .require_available(PlatformFeature::GlobalHotkeys)
            .prefer_available(PlatformFeature::TouchInput)
            .prefer_available(PlatformFeature::SpellChecking)
            .prefer_available(PlatformFeature::Geolocation)
            .prefer_available(PlatformFeature::FileExportDrag)
            .prefer_available(PlatformFeature::AppWindowCapture)
            .prefer_available(PlatformFeature::UsbDevices)
            .prefer_available(PlatformFeature::BluetoothDevices)
            .prefer(PlatformFeature::FileBookmarks)
            .evaluate(&report);

        assert!(result.is_ok());
        assert!(result.missing_required().is_empty());
        assert_eq!(result.missing_preferred().len(), 1);
        assert_eq!(
            result.missing_preferred()[0].feature,
            PlatformFeature::FileBookmarks
        );
    }

    #[test]
    fn test_app_parity_recipe_evaluates_media_player_surfaces() {
        let recipe = DesktopAppCategory::MediaPlayerEditor.recipe();
        assert_eq!(recipe.category, DesktopAppCategory::MediaPlayerEditor);
        assert!(recipe.surface_count() >= 6);
        assert!(recipe.route_count(AppParityRoute::NativeReady) >= 4);
        assert_eq!(recipe.route_count(AppParityRoute::WebViewFallback), 1);
        assert_eq!(recipe.route_count(AppParityRoute::Roadmap), 1);
        assert!(
            recipe
                .checked_features()
                .contains(&PlatformFeature::WebView)
        );
        assert!(recipe.to_text().contains("media player/editor"));

        let report = CapabilityReport {
            os: "test".into(),
            os_version: "1".into(),
            features: vec![
                FeatureReport {
                    feature: PlatformFeature::GpuRendering,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::GlobalHotkeys,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::FileBookmarks,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::FileExportDrag,
                    support: SupportLevel::Partial,
                    note: Some("descriptor only".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::ShareSheet,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::ProgressIndicator,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::WebView,
                    support: SupportLevel::Unsupported,
                    note: None,
                },
            ],
        };

        let plan = recipe.evaluate(&report);
        assert!(!plan.feature_checks_passed());
        assert_eq!(
            plan.feature_gaps,
            vec![
                PlatformFeature::NetworkAccess,
                PlatformFeature::Printing,
                PlatformFeature::DeveloperDiagnostics,
                PlatformFeature::PowerMonitor,
                PlatformFeature::WebView,
            ]
        );
        assert!(plan.has_webview_fallbacks());
        assert!(plan.has_roadmap_surfaces());
        assert_eq!(plan.route_count(AppParityRoute::NativeWithGuardrails), 4);

        let check = recipe.capability_check().evaluate(&report);
        assert!(check.is_ok());
        assert_eq!(check.missing_preferred().len(), 5);
        assert_eq!(
            check.missing_preferred()[0].feature,
            PlatformFeature::NetworkAccess
        );
    }

