    #[test]
    fn test_desktop_surface_audit_reports_non_webview_gaps() {
        let report = CapabilityReport {
            os: "test".into(),
            os_version: "1".into(),
            features: vec![
                FeatureReport {
                    feature: PlatformFeature::UsbDevices,
                    support: SupportLevel::Unsupported,
                    note: Some("native USB backend missing".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::HidDevices,
                    support: SupportLevel::Partial,
                    note: Some("descriptor only".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::SerialPorts,
                    support: SupportLevel::Unsupported,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::BluetoothDevices,
                    support: SupportLevel::RequiresInit,
                    note: Some("permission required".into()),
                },
                FeatureReport {
                    feature: PlatformFeature::WebView,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::AuxiliaryExecutable,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::SecureKeychain,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::Sandboxing,
                    support: SupportLevel::Full,
                    note: None,
                },
                FeatureReport {
                    feature: PlatformFeature::GpuRendering,
                    support: SupportLevel::Full,
                    note: None,
                },
            ],
        };

        let plan = DesktopSurfaceAuditPlan::for_category(DesktopAppCategory::PluginHeavy, &report);
        assert!(plan.has_feature_gaps());
        assert!(plan.has_webview_fallbacks());
        assert!(!plan.has_roadmap_gaps());

        let hardware = plan
            .areas
            .iter()
            .find(|area| area.area == DesktopSurfaceArea::HardwareDevices)
            .expect("plugin-heavy app should audit hardware device surfaces");
        assert_eq!(hardware.route, AppParityRoute::NativeWithGuardrails);
        assert_eq!(
            hardware.feature_gaps,
            vec![PlatformFeature::UsbDevices, PlatformFeature::SerialPorts]
        );
        assert!(hardware.needs_guardrails());
        assert!(!hardware.is_webview_fallback());
    }

