    #[test]
    fn test_desktop_generation_next_step_summarizes_contract_safely() {
        let report = full_media_category_report_with_private_notes();

        let contract = DesktopAppCategory::MediaPlayerEditor.generation_contract(&report);
        let next = contract.next_step();
        assert_eq!(
            next.action,
            DesktopGenerationNextAction::GenerateReadyNativeWork
        );
        assert!(next.ready_entry_count > 0);
        assert!(next.evidence_missing_count > 0);

        let text = next.to_text();
        assert!(text.contains("desktop generation next step"));
        assert!(text.contains("action generate-ready-native-work"));
        assert!(!text.contains("media.example"));
        assert!(!text.contains("private"));
        assert!(!text.contains("VideoPlaybackPlanBuilder"));
    }

    #[test]
    fn test_desktop_capability_portfolio_audit_rolls_up_all_categories() {
        let full = |feature| FeatureReport {
            feature,
            support: SupportLevel::Full,
            note: Some("https://portfolio.example.invalid/private".into()),
        };
        let report = CapabilityReport {
            os: "test".into(),
            os_version: "1".into(),
            features: vec![
                full(PlatformFeature::GpuRendering),
                full(PlatformFeature::PrecisionPointerInput),
                full(PlatformFeature::GestureInput),
                full(PlatformFeature::TextInputIme),
                full(PlatformFeature::SpellChecking),
                full(PlatformFeature::AppActivation),
                full(PlatformFeature::DisplayTopology),
                full(PlatformFeature::AppLifecycle),
                full(PlatformFeature::IpcMessaging),
                full(PlatformFeature::AlwaysOnTopWindows),
                full(PlatformFeature::WindowTabbing),
                full(PlatformFeature::SpatialAudio),
                full(PlatformFeature::GlobalHotkeys),
                full(PlatformFeature::StatusBarItem),
                full(PlatformFeature::ProgressIndicator),
                full(PlatformFeature::FileBookmarks),
                full(PlatformFeature::FileExportDrag),
                full(PlatformFeature::ShareSheet),
                full(PlatformFeature::AppWindowCapture),
                full(PlatformFeature::WebView),
                full(PlatformFeature::DeveloperDiagnostics),
                full(PlatformFeature::AppStorage),
                full(PlatformFeature::SecureKeychain),
                full(PlatformFeature::Printing),
                full(PlatformFeature::NetworkAccess),
                full(PlatformFeature::PowerMonitor),
                full(PlatformFeature::SystemIdle),
                full(PlatformFeature::NativeTheme),
                full(PlatformFeature::SpellChecking),
                full(PlatformFeature::Notifications),
                full(PlatformFeature::NotificationActions),
                full(PlatformFeature::ScreenCapture),
                full(PlatformFeature::MicrophoneCapture),
                full(PlatformFeature::SystemAudioLoopback),
                full(PlatformFeature::Geolocation),
                full(PlatformFeature::UsbDevices),
                full(PlatformFeature::HidDevices),
                full(PlatformFeature::SerialPorts),
                full(PlatformFeature::BluetoothDevices),
                full(PlatformFeature::AuxiliaryExecutable),
                full(PlatformFeature::SecureKeychain),
                full(PlatformFeature::AppStorage),
                full(PlatformFeature::Sandboxing),
                full(PlatformFeature::AutoUpdate),
                full(PlatformFeature::HardenedRuntime),
            ],
        };

        let audit = DesktopCapabilityPortfolioAudit::all(&report);
        assert_eq!(audit.entry_count(), DesktopAppCategory::all().len());
        assert_eq!(audit.blocked_entries().len(), 0);
        assert!(!audit.ready_entries().is_empty());
        assert_eq!(
            audit.can_generate_all_ready_work(),
            audit.ready_entries().len() == audit.entry_count()
        );
        assert_eq!(audit.mark_ready_entries().len(), 0);
        assert_eq!(
            audit.action_count(DesktopGenerationNextAction::GenerateReadyNativeWork),
            audit.ready_entries().len()
        );
        assert!(audit.action_count(DesktopGenerationNextAction::GenerateReadyNativeWork) > 0);
        assert!(audit.ready_entry_count() > 0);
        assert!(audit.evidence_item_count() > 0);
        assert_eq!(audit.evidence_item_count(), audit.evidence_missing_count());
        let focus = audit
            .recommended_focus()
            .expect("portfolio audit should recommend a focus");
        assert_eq!(
            audit.recommended_entry().map(|entry| entry.category),
            Some(focus.category)
        );
        assert_eq!(focus.action, audit.prioritized_entries()[0].next_action());
        let handoff = audit
            .recommended_handoff()
            .expect("portfolio audit should recommend a handoff");
        assert_eq!(handoff.focus.category, focus.category);
        assert_eq!(handoff.focus.action, focus.action);
        assert!(handoff.entry_count() > 0);
        assert_eq!(handoff.scaffold_hints().len(), handoff.entry_count());
        assert_eq!(handoff.acceptance_criteria().len(), handoff.entry_count());
        assert!(handoff.acceptance_evidence_report().item_count() > 0);
        let recommended_batch = audit
            .recommended_execution_batch()
            .expect("portfolio audit should expose a recommended execution batch");
        assert!(recommended_batch.has_kits());
        assert_eq!(
            audit
                .recommended_phase_assignment()
                .map(|assignment| assignment.kind),
            Some(recommended_batch.assignment.kind)
        );
        assert_eq!(
            handoff
                .current_execution_batch()
                .map(|batch| batch.assignment.kind),
            Some(recommended_batch.assignment.kind)
        );
        assert_eq!(
            handoff.current_execution_kit().map(|kit| kit.kind),
            Some(recommended_batch.assignment.kind)
        );
        assert_eq!(
            handoff
                .current_phase_assignment()
                .map(|assignment| assignment.kind),
            Some(recommended_batch.assignment.kind)
        );
        let passed_batch_evidence = recommended_batch
            .evidence_checklists()
            .into_iter()
            .map(|mut checklist| {
                for item in &mut checklist.items {
                    item.status = DesktopAcceptanceEvidenceStatus::Passed;
                }
                checklist
            })
            .collect::<Vec<_>>();
        let portfolio_continuation = handoff
            .continue_with_execution_batch_evidence(&recommended_batch, passed_batch_evidence);
        assert_eq!(portfolio_continuation.focus.category, focus.category);
        assert_eq!(
            portfolio_continuation.continuation.outcome_count,
            recommended_batch.kit_count
        );
        assert_eq!(
            portfolio_continuation.has_next_batch(),
            portfolio_continuation.continuation.has_next_batch()
        );
        let portfolio_continuation_text = portfolio_continuation.to_text();
        assert!(portfolio_continuation_text.contains("desktop capability portfolio continuation"));
        assert!(!portfolio_continuation_text.contains("portfolio.example"));
        assert!(!portfolio_continuation_text.contains("private"));
        let review = handoff.ready_evidence_review();
        assert_eq!(review.next_action, handoff.focus.action);
        assert!(!review.can_claim_parity());
        assert!(review.evidence.missing_count() > 0);
        let passed_checklists = handoff
            .acceptance_evidence_checklists()
            .into_iter()
            .map(|checklist| DesktopAcceptanceEvidenceChecklist {
                primitive: checklist.primitive,
                area: checklist.area,
                items: checklist
                    .items
                    .into_iter()
                    .map(|item| item.with_status(DesktopAcceptanceEvidenceStatus::Passed))
                    .collect(),
            })
            .collect::<Vec<_>>();
        let passed_review = handoff.review_evidence_checklists(passed_checklists);
        assert!(passed_review.is_complete());
        assert_eq!(passed_review.evidence.failed_count(), 0);
        assert_eq!(passed_review.evidence.missing_count(), 0);
        if handoff.focus.action == DesktopGenerationNextAction::ResolveGenerationBlockers {
            assert_eq!(
                passed_review.next_action,
                DesktopGenerationNextAction::ResolveGenerationBlockers
            );
        } else {
            assert!(matches!(
                passed_review.next_action,
                DesktopGenerationNextAction::BriefCaveats
                    | DesktopGenerationNextAction::ClaimParity
            ));
        }

        let text = audit.to_text();
        assert!(text.contains("desktop capability portfolio audit"));
        assert!(text.contains("6 categories"));
        assert!(text.contains("recommended action"));
        assert!(text.contains("generate-native actions"));
        assert!(!text.contains("portfolio.example"));
        assert!(!text.contains("private"));

        let focus_text = focus.to_text();
        assert!(focus_text.contains("desktop capability portfolio focus"));
        assert!(!focus_text.contains("portfolio.example"));
        assert!(!focus_text.contains("private"));

        let handoff_text = handoff.to_text();
        assert!(handoff_text.contains("desktop capability portfolio handoff"));
        assert!(!handoff_text.contains("portfolio.example"));
        assert!(!handoff_text.contains("private"));

        let review_text = review.to_text();
        assert!(review_text.contains("desktop capability portfolio evidence review"));
        assert!(!review_text.contains("portfolio.example"));
        assert!(!review_text.contains("private"));

        let passed_review_text = passed_review.to_text();
        assert!(passed_review_text.contains("desktop capability portfolio evidence review"));
        assert!(!passed_review_text.contains("portfolio.example"));
        assert!(!passed_review_text.contains("private"));

        let entry_text = audit.entries[0].to_text();
        assert!(entry_text.contains("desktop capability portfolio entry"));
        assert!(!entry_text.contains("portfolio.example"));
        assert!(!entry_text.contains("private"));
    }

    #[test]
    fn test_desktop_capability_portfolio_audit_surfaces_non_webview_blockers() {
        let full = |feature| FeatureReport {
            feature,
            support: SupportLevel::Full,
            note: None,
        };
        let unsupported = |feature| FeatureReport {
            feature,
            support: SupportLevel::Unsupported,
            note: Some("private-device://serial-controller".into()),
        };
        let report = CapabilityReport {
            os: "test".into(),
            os_version: "1".into(),
            features: vec![
                full(PlatformFeature::GpuRendering),
                full(PlatformFeature::PrecisionPointerInput),
                full(PlatformFeature::GestureInput),
                full(PlatformFeature::TextInputIme),
                full(PlatformFeature::SpellChecking),
                full(PlatformFeature::AppActivation),
                full(PlatformFeature::DisplayTopology),
                full(PlatformFeature::AppLifecycle),
                full(PlatformFeature::IpcMessaging),
                full(PlatformFeature::AlwaysOnTopWindows),
                full(PlatformFeature::WindowTabbing),
                full(PlatformFeature::SpatialAudio),
                full(PlatformFeature::GlobalHotkeys),
                full(PlatformFeature::StatusBarItem),
                full(PlatformFeature::ProgressIndicator),
                full(PlatformFeature::FileBookmarks),
                full(PlatformFeature::FileExportDrag),
                full(PlatformFeature::ShareSheet),
                full(PlatformFeature::AppWindowCapture),
                full(PlatformFeature::WebView),
                full(PlatformFeature::DeveloperDiagnostics),
                full(PlatformFeature::AppStorage),
                full(PlatformFeature::SecureKeychain),
                full(PlatformFeature::Printing),
                full(PlatformFeature::NetworkAccess),
                full(PlatformFeature::PowerMonitor),
                full(PlatformFeature::SystemIdle),
                full(PlatformFeature::NativeTheme),
                full(PlatformFeature::SpellChecking),
                full(PlatformFeature::Notifications),
                full(PlatformFeature::NotificationActions),
                full(PlatformFeature::ScreenCapture),
                full(PlatformFeature::MicrophoneCapture),
                full(PlatformFeature::SystemAudioLoopback),
                full(PlatformFeature::Geolocation),
                unsupported(PlatformFeature::UsbDevices),
                full(PlatformFeature::HidDevices),
                unsupported(PlatformFeature::SerialPorts),
                full(PlatformFeature::BluetoothDevices),
                full(PlatformFeature::AuxiliaryExecutable),
                full(PlatformFeature::SecureKeychain),
                full(PlatformFeature::AppStorage),
                full(PlatformFeature::Sandboxing),
                full(PlatformFeature::AutoUpdate),
                full(PlatformFeature::HardenedRuntime),
            ],
        };

        let audit = DesktopCapabilityPortfolioAudit::all(&report);
        assert!(!audit.can_generate_all_ready_work());
        assert_eq!(audit.blocked_entries().len(), 1);
        assert_eq!(
            audit.blocked_entries()[0].category,
            DesktopAppCategory::PluginHeavy
        );
        let blocker_actions =
            audit.entries_for_action(DesktopGenerationNextAction::ResolveGenerationBlockers);
        assert!(
            blocker_actions
                .iter()
                .any(|entry| entry.category == DesktopAppCategory::PluginHeavy)
        );
        assert!(blocker_actions.len() >= audit.blocked_entries().len());
        let focus = audit
            .recommended_focus()
            .expect("portfolio audit should recommend a focus");
        assert_eq!(
            focus.action,
            DesktopGenerationNextAction::ResolveGenerationBlockers
        );
        assert!(
            audit
                .prioritized_entries()
                .iter()
                .take(blocker_actions.len())
                .any(|entry| entry.category == DesktopAppCategory::PluginHeavy)
        );
        let handoff = audit
            .recommended_handoff()
            .expect("portfolio audit should recommend a handoff");
        assert_eq!(
            handoff.focus.action,
            DesktopGenerationNextAction::ResolveGenerationBlockers
        );
        assert_eq!(handoff.focus.category, focus.category);
        assert!(handoff.feature_gap_count() >= 2);
        assert!(
            handoff
                .entries
                .iter()
                .any(|entry| entry.primitive == DesktopPrimitive::HardwareDeviceApis)
        );
        let review = handoff.ready_evidence_review();
        assert_eq!(
            review.next_action,
            DesktopGenerationNextAction::ResolveGenerationBlockers
        );
        assert_eq!(
            review.claim.status,
            DesktopParityClaimStatus::BlockedByGeneration
        );
        assert!(!review.can_claim_parity());
        assert!(audit.feature_gap_count() >= 2);
        assert!(audit.ready_entries().len() < audit.entry_count());

        let text = audit.to_text();
        assert!(text.contains("desktop capability portfolio audit"));
        assert!(text.contains("1 blocked"));
        assert!(text.contains("recommended action resolve-generation-blockers"));
        assert!(text.contains("resolve-blocker actions"));
        assert!(!text.contains("private-device"));
        assert!(!text.contains("serial-controller"));

        let focus_text = focus.to_text();
        assert!(focus_text.contains("desktop capability portfolio focus"));
        assert!(focus_text.contains("action resolve-generation-blockers"));
        assert!(!focus_text.contains("private-device"));
        assert!(!focus_text.contains("serial-controller"));

        let handoff_text = handoff.to_text();
        assert!(handoff_text.contains("desktop capability portfolio handoff"));
        assert!(handoff_text.contains("action resolve-generation-blockers"));
        assert!(!handoff_text.contains("private-device"));
        assert!(!handoff_text.contains("serial-controller"));

        let review_text = review.to_text();
        assert!(review_text.contains("desktop capability portfolio evidence review"));
        assert!(review_text.contains("action resolve-generation-blockers"));
        assert!(!review_text.contains("private-device"));
        assert!(!review_text.contains("serial-controller"));
    }

    #[test]
    fn test_desktop_category_generation_contract_refreshes_claim_with_evidence() {
        let report = full_media_category_report_with_private_notes();

        let contract = DesktopAppCategory::MediaPlayerEditor.generation_contract(&report);
        let passed_checklists = contract
            .ready_evidence
            .checklists
            .iter()
            .map(|checklist| DesktopAcceptanceEvidenceChecklist {
                primitive: checklist.primitive,
                area: checklist.area,
                items: checklist
                    .items
                    .iter()
                    .cloned()
                    .map(|item| item.with_status(DesktopAcceptanceEvidenceStatus::Passed))
                    .collect(),
            })
            .collect::<Vec<_>>();

        let refreshed = contract.with_ready_evidence_checklists(passed_checklists);
        assert!(refreshed.ready_evidence.is_complete());
        assert_eq!(refreshed.ready_evidence.failed_count(), 0);
        assert_eq!(refreshed.ready_evidence.missing_count(), 0);
        assert_eq!(
            refreshed.ready_claim.status,
            DesktopParityClaimStatus::RequiresBriefing
        );
        assert!(!refreshed.can_claim_ready_parity());
        assert_eq!(
            refreshed.next_action(),
            DesktopGenerationNextAction::BriefCaveats
        );

        let next = refreshed.next_step();
        assert_eq!(next.action, DesktopGenerationNextAction::BriefCaveats);
        assert!(next.evidence_passed_count > 0);
        assert_eq!(next.evidence_failed_count, 0);
        assert_eq!(next.evidence_missing_count, 0);

        let text = refreshed.to_text();
        assert!(text.contains("desktop category generation contract"));
        assert!(text.contains("claim status requires-briefing"));
        assert!(!text.contains("media.example"));
        assert!(!text.contains("private"));

        let next_text = next.to_text();
        assert!(next_text.contains("desktop generation next step"));
        assert!(next_text.contains("action brief-caveats"));
        assert!(!next_text.contains("media.example"));
        assert!(!next_text.contains("private"));
    }

    #[test]
    fn test_desktop_category_generation_contract_blocks_failed_evidence() {
        let report = full_media_category_report();

        let contract = DesktopAppCategory::MediaPlayerEditor.generation_contract(&report);
        let mut failed = contract.ready_evidence.clone();
        if let Some(item) = failed
            .checklists
            .iter_mut()
            .flat_map(|checklist| checklist.items.iter_mut())
            .next()
        {
            item.status = DesktopAcceptanceEvidenceStatus::Failed;
        }

        let refreshed = contract.with_ready_evidence(failed);
        assert_eq!(
            refreshed.ready_claim.status,
            DesktopParityClaimStatus::BlockedByFailedEvidence
        );
        assert!(refreshed.ready_evidence.has_failures());
        assert!(!refreshed.can_claim_ready_parity());
        assert_eq!(
            refreshed.next_action(),
            DesktopGenerationNextAction::FixFailedEvidence
        );
    }

    #[test]
    fn test_desktop_category_generation_contract_claims_after_clean_evidence_without_caveats() {
        let report = full_media_category_report();

        let contract = DesktopAppCategory::MediaPlayerEditor.generation_contract(&report);
        let passed_checklists = contract
            .ready_evidence
            .checklists
            .iter()
            .map(|checklist| DesktopAcceptanceEvidenceChecklist {
                primitive: checklist.primitive,
                area: checklist.area,
                items: checklist
                    .items
                    .iter()
                    .cloned()
                    .map(|item| item.with_status(DesktopAcceptanceEvidenceStatus::Passed))
                    .collect(),
            })
            .collect::<Vec<_>>();

        let mut refreshed = contract.with_ready_evidence_checklists(passed_checklists);
        refreshed.brief.needs_briefing = false;
        refreshed.queue.needs_briefing = false;
        refreshed.ready_claim = refreshed
            .queue
            .parity_claim_decision(&refreshed.ready_evidence);

        assert_eq!(
            refreshed.ready_claim.status,
            DesktopParityClaimStatus::Allowed
        );
        assert!(refreshed.can_claim_ready_parity());
        assert_eq!(
            refreshed.next_action(),
            DesktopGenerationNextAction::ClaimParity
        );
    }

