    #[test]
    fn test_desktop_category_generation_queue_starts_with_native_when_ready() {
        let report = full_media_category_report_with_private_notes();

        let manifest = DesktopAppCategory::MediaPlayerEditor.generation_manifest(&report);
        let queue = manifest.generation_queue();
        assert!(queue.can_generate);
        assert!(!queue.is_blocked());
        assert_eq!(
            queue.current_phase().map(|phase| phase.kind),
            Some(DesktopGenerationStepKind::BuildNativeSurface)
        );
        assert_eq!(queue.entry_count(), manifest.entry_count());
        assert_eq!(
            queue.ready_entries().len(),
            queue
                .native_phase()
                .expect("native phase should be present")
                .entry_count()
        );
        assert!(
            queue
                .ready_entries()
                .iter()
                .any(|entry| entry.primitive == DesktopPrimitive::MediaPlaybackSurface)
        );
        assert!(
            queue
                .ready_scaffold_hints()
                .iter()
                .any(|hint| hint.module_path == "src/features/media/playback.rs")
        );
        assert!(
            queue
                .ready_acceptance_criteria()
                .iter()
                .any(|criteria| criteria.primitive == DesktopPrimitive::MediaPlaybackSurface)
        );
        assert!(
            queue
                .ready_acceptance_evidence_checklists()
                .iter()
                .any(
                    |checklist| checklist.primitive == DesktopPrimitive::MediaPlaybackSurface
                        && checklist.missing_count() == checklist.item_count()
                )
        );
        assert!(!queue.ready_acceptance_evidence_report().can_claim_parity());
        assert!(
            queue
                .ready_acceptance_evidence_report()
                .blocked_primitives()
                .contains(&DesktopPrimitive::MediaPlaybackSurface)
        );
        let decision = queue.ready_parity_claim_decision();
        assert_eq!(
            decision.status,
            DesktopParityClaimStatus::BlockedByMissingEvidence
        );
        assert!(!decision.can_claim_parity);
        assert!(
            queue
                .current_phase()
                .expect("native phase should be current")
                .acceptance_criterion_count()
                > 0
        );
        assert!(
            queue
                .current_phase()
                .expect("native phase should be current")
                .acceptance_evidence_report()
                .missing_count()
                > 0
        );

        let text = queue.to_text();
        let phase_text = queue.current_phase().unwrap().to_text();
        assert!(text.contains("desktop category generation queue"));
        assert!(text.contains("blocked false"));
        assert!(phase_text.contains("build-native-surface"));
        assert!(phase_text.contains("acceptance criteria"));
        assert!(!text.contains("media.example"));
        assert!(!phase_text.contains("media.example"));
        assert!(!phase_text.contains("VideoPlaybackPlanBuilder"));
        assert!(!phase_text.contains("src/features/media/playback.rs"));
        assert!(!phase_text.contains("media-key behavior"));
    }

